export const SITE_URL = "https://aussiecamps.app";
/** The App Store identifier AussieCamps is published under. Every store link, the smart app banner,
 * the QR card and the schema install URLs derive from this one constant. */
export const APP_ID = "6801098680";
/** Storefront-neutral so Apple sends each visitor to their own country's listing. */
export const APP_STORE_URL = `https://apps.apple.com/app/id${APP_ID}`;
/**
 * The final URL for a site path.
 *
 * The host serves every directory route with a trailing slash and 301s the slash-less form, so
 * `/guides` costs a redirect on every visit. Worse, it makes every canonical, hreflang tag and
 * sitemap entry name a URL that redirects rather than the one that answers. Canonicals, alternates,
 * sitemap entries and internal links all go through here so they name the served URL directly.
 *
 * Articles published at an existing `.html` URL are real files, not directories, and keep their
 * exact published path.
 */
export function sitePath(path: string): string {
  if (!path || path === "/") return "/";
  const [base, hash] = path.split("#");
  if (base.endsWith("/") || /\.[a-z0-9]+$/i.test(base)) return path;
  return `${base}/${hash ? `#${hash}` : ""}`;
}

export const SUPPORT_EMAIL = "support@cntxtlabs.co";
export const SUPPORT_MAILTO = `mailto:${SUPPORT_EMAIL}?subject=AussieCamps%20web%20contact`;

import { expandedArticles } from "@/lib/expanded-articles";
import { articleFaqs } from "@/lib/article-faqs";

export type ArticleCategory = "Road trips" | "Camping guides" | "Rules & safety" | "Trip planning" | "Costs & budget" | "App guides";
export type ArticleSection = { heading: string; body: string[]; tips?: string[] };
export type ArticlePriceTable = {
  asOf: string;
  note: string;
  rows: { label: string; audLow: number; audHigh?: number; unit?: string }[];
};
export type Article = {
  slug: string;
  title: string;
  description: string;
  category: ArticleCategory;
  region: string;
  readTime: number;
  places: string[];
  image: string;
  imageAlt: string;
  intro: string;
  sections: ArticleSection[];
  /**
   * Two questions this guide answers, in the words someone would search them.
   *
   * Deliberately not a duplicate of the homepage FAQ: two FAQPage blocks answering the same
   * question on one site compete with each other. Road trip guides carry none, because an itinerary
   * is not a question-shaped search and Google's own guidance points FAQ markup at pages that
   * answer questions.
   */
  faq?: readonly (readonly [string, string])[];
  sources?: { label: string; url: string }[];
  priceTable?: ArticlePriceTable;
};

type ArticleInput = Omit<Article, "image">;
/**
 * Reading time measured from the article's own words rather than declared by hand, so a short guide
 * never advertises the same "10 minute read" as a long one. 220 words per minute is a common adult
 * prose rate; tips and table rows are counted because readers do read them.
 */
export function readingMinutes(input: Pick<Article, "intro" | "sections"> & { priceTable?: Article["priceTable"] }) {
  const parts = [
    input.intro,
    ...input.sections.flatMap((part) => [part.heading, ...part.body, ...(part.tips ?? [])]),
    ...(input.priceTable ? [input.priceTable.note, ...input.priceTable.rows.map((row) => `${row.label} ${row.unit ?? ""}`)] : []),
  ];
  const words = parts.join(" ").trim().split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 220));
}

const article = (input: ArticleInput): Article => ({ ...input, readTime: readingMinutes(input), image: `/images/articles/${input.slug}.webp` });
const section = (heading: string, body: string[], tips?: string[]): ArticleSection => ({ heading, body, tips });

export const articles: Article[] = [
  article({
    slug: "great-ocean-road-camping-guide", title: "Great Ocean Road camping guide: a 3-day route", description: "Surf beaches, rainforest bends and a final sunset over the Twelve Apostles.", category: "Road trips", region: "Victoria Coast", readTime: 9,
    places: ["Torquay", "Aireys Inlet", "Apollo Bay Holiday Park", "Aire River East Campground", "Johanna Beach Campground", "Port Campbell", "Warrnambool"], imageAlt: "Great Ocean Road coast in Victoria", intro: "Three days gives the Great Ocean Road enough breathing room for lighthouse walks, forest detours and an evening beside the Southern Ocean. Drive west from Torquay and keep the final night near Port Campbell or Warrnambool.",
    sections: [
      section("Day 1: Torquay to Apollo Bay", ["Leave Melbourne early and make Torquay the first proper stop. Bells Beach, Point Addis and the clifftop road around Aireys Inlet are better enjoyed before the afternoon traffic builds.", "Apollo Bay works well for the first night. A holiday park gives you showers, power and an easy resupply, while nearby national park camps offer a quieter base. Book summer weekends well ahead."]),
      section("Day 2: Cape Otway and the forest", ["Turn into Great Otway National Park for tall forest, waterfalls and the Cape Otway coast. Aire River East and Aire River West are useful bases when access conditions suit your vehicle. Johanna Beach is exposed but memorable in settled weather.", "Expect weak reception away from towns. Carry water, check fire restrictions and do not rely on arriving late at a small campground. Coastal wind can make a mild forecast feel much colder after sunset."], ["Aire River East Campground", "Johanna Beach Campground", "Apollo Bay Holiday Park"]),
      section("Day 3: Port Campbell and the western cliffs", ["Reach the Twelve Apostles early, then continue to Loch Ard Gorge and the quieter lookouts beyond Port Campbell. The scenery improves when you leave time to walk instead of collecting viewpoints through a windscreen.", "Finish in Port Campbell or continue to Warrnambool for a wider choice of caravan parks, groceries and fuel. If you are returning to Melbourne, the inland highway is faster than retracing the coast."])
    ,section("Drive it westbound",["Travelling Melbourne to Warrnambool puts you on the ocean side of the road, which matters on a route where the lookouts are almost all on the coast. Eastbound you spend the trip crossing traffic to reach every stop.","The road is narrow, winding and busy with tour coaches, and it carries a poor crash record involving visiting drivers. Overtaking opportunities are rare and the pull-offs are small, so plan on a slow average and let faster traffic past.","Allow three days minimum. Done in one it becomes four hours of concentration past things you did not stop for, which is the single most common regret on this route."],["Drive westbound for the lookouts","Three days minimum","Coach traffic and few passing spots"]),section("Where the camping actually is",["Aire River and Johanna Beach are the standout low-cost options inside Great Otway National Park, both requiring booking through Parks Victoria and both filling over summer and school holidays. Neither has powered sites.","Apollo Bay and Port Campbell carry the commercial parks with showers, laundry and power, and they are the practical reset points on a three-day run. Book these well ahead between December and January.","Free camping along the road itself is essentially non-existent and heavily policed. Treat the corridor as a booked-accommodation route rather than one you can improvise through."],["Book Parks Victoria sites ahead","No realistic free camping on the road","Apollo Bay and Port Campbell for services"]),section("Timing the Twelve Apostles",["Sunset is the classic time and also when the car park is fullest, with coaches arriving in a block. Sunrise gives you comparable light with a fraction of the people, and the walk down to Gibson Steps is far more pleasant early.","The helicopter flights operate from beside the visitor area and give the only view that shows the full stack formation. They are weather dependent and worth booking for the morning so a cancellation can be moved.","Loch Ard Gorge, a few minutes further west, is quieter than the Apostles and arguably the better stop. The shipwreck story and the beach access make it worth more than the ten minutes most people give it."],["Sunrise beats sunset for crowds","Loch Ard Gorge is quieter","Book flights for the morning"]),section("The Otways and the wildlife",["Turning inland into the Otways gives you tall wet forest, Hopetoun Falls, Triplet Falls and the Otway Fly treetop walk, all within a short drive of the coast road. It is a completely different landscape and a good wet-weather option.","Cape Otway is the reliable place to see wild koalas along the road through the manna gums, though numbers have fluctuated with the health of the trees. Watch for them from the vehicle rather than approaching, and never feed them.","Glow worms appear in the Melba Gully area after dark, and the walk is short and easy. Take a red light and let your eyes adjust rather than sweeping a torch around."],["Otways are the wet-weather option","Koalas along the Cape Otway road","Red light for the glow worms"]),section("Beyond the Twelve Apostles",["Most traffic turns around at the Apostles, which means the coast west to Warrnambool through the Bay of Islands and the Bay of Martyrs is quieter and arguably as good. It is worth the extra hour.","Warrnambool itself has the Logans Beach whale nursery between May and October and works as a final night before turning inland or continuing to South Australia.","Port Fairy at the western end is a preserved fishing town with good camping and far fewer visitors than the eastern half of the route, which makes it a calm final night.","Check the Parks Victoria site for current campground status before you leave Melbourne, since storm damage and fire recovery work close individual sites at short notice along this coast."],["Traffic thins west of the Apostles","Bay of Islands is quieter","Whales at Warrnambool May to October"])]
  }),
  article({
    slug: "east-coast-road-trip-sydney-cairns", title: "Sydney to Cairns: a 14-day camping road trip", description: "Two weeks of beach camps, green hinterland and warm northern mornings.", category: "Road trips", region: "East Coast", readTime: 11,
    places: ["Myall Lakes", "Port Macquarie", "Dorrigo National Park", "Byron Bay", "Springbrook National Park", "K'gari", "Airlie Beach", "Mission Beach", "Cairns"], imageAlt: "Tropical east coast road in Queensland", intro: "Sydney to Cairns is about 2,500 kilometres before detours. Fourteen days is quick, so choose a few long stops instead of sleeping in a different town every night.",
    sections: [
      section("Sydney to the Mid North Coast", ["Break the first drive around Myall Lakes or Port Macquarie. Myall Lakes brings quiet water and national park camping, while Port Macquarie makes food, laundry and a powered site easy.", "Turn inland for Dorrigo if rainforest walks matter more than another beach night. The plateau is cooler, the road climbs sharply and cloud can settle quickly around the ranges."]),
      section("Northern NSW and south-east Queensland", ["Byron Bay is popular for a reason, but nearby caravan parks fill early and traffic is slow in holidays. Brunswick Heads, Lennox Head and the Tweed can provide a calmer base.", "Crossing into Queensland, choose between the Gold Coast hinterland and the coast. Springbrook National Park adds waterfalls and cooler nights. K'gari needs separate planning for tides, vehicle permits and sand driving."], ["Check school holiday dates", "Confirm K'gari vehicle rules", "Do not drive tired after a beach day"]),
      section("The long run to Cairns", ["The distance between the Sunshine Coast and Airlie Beach is larger than it looks. Split it around Agnes Water, Rockhampton or Cape Hillsborough, then give Airlie Beach a rest day.", "Mission Beach is a gentler final stop before Cairns. By this point the climate is tropical, cassowary warnings matter and swimming advice changes by season. Check local signs before entering any water."])
    ,section("Fourteen days is tight for this distance",["Sydney to Cairns is roughly 2,400 kilometres by the direct inland route and considerably more if you follow the coast properly. Two weeks means averaging around 200 kilometres a day with stops, which is comfortable only if you resist adding detours.","The common mistake is trying to include the Whitsundays, Fraser Island, the Daintree and a Great Barrier Reef trip in the same fortnight. Each of those wants two days minimum, and together they consume the entire trip.","Pick three highlights and treat the rest as driving days with a swim. Trying to do everything produces a trip where you were constantly in the vehicle."],["Around 2,400 km direct","Pick three highlights, not six","200 km a day is the realistic pace"]),section("The stops that justify a second night",["Byron Bay, Noosa, Airlie Beach and Port Douglas are the places where a single night leaves you packing up before you have done anything. Each has walks, beaches and boat trips that need a full day.","Between them, Coffs Harbour, Hervey Bay, Rockhampton and Townsville work as single-night transit stops with services, fuel and a caravan park. There is no need to make these interesting.","If you are heading for the reef, Cairns and Port Douglas are the two departure points and both need a spare day for weather. Reef trips are cancelled often enough that a same-day-arrival booking is a gamble."],["Two nights: Byron, Noosa, Airlie, Port Douglas","Spare day for reef weather","Transit towns need nothing special"]),section("Stingers, crocodiles and swimming",["North of about Gladstone, marine stingers make unprotected ocean swimming unsafe roughly from November to May. Stinger nets and full-body suits are the standard precaution and the signage is reliable, so follow it rather than judging by how calm the water looks.","Estuarine crocodiles are present in waterways from about Rockhampton north, and that includes rivers, creeks and beaches that look completely benign. Never swim, clean fish or camp at the water's edge in croc country, and obey every warning sign.","The safe swimming options up north are patrolled beaches inside stinger nets, freshwater pools where signage confirms it, and the many town lagoons. Cairns and Airlie Beach both have excellent free public lagoons for exactly this reason."],["Stinger season roughly November to May","Crocs from Rockhampton north","Town lagoons are the safe swim"]),section("Fuel, distances and the inland alternative",["The Bruce Highway is the coastal spine and carries heavy truck traffic, roadworks and flood closures in the wet season. It is not a scenic road for much of its length, which surprises people expecting ocean views.","Fuel is available regularly along this route, unlike most of Australia, so the planning issue is time rather than range. Roadhouse prices north of Townsville rise noticeably.","In the wet season, from roughly November to April, sections of the Bruce close with flooding and the tropical north gets serious rain. The dry season from May to October is the straightforward time to do this drive."],["Dry season is May to October","Bruce Highway floods in the wet","Fuel is not the constraint here"]),section("Island detours worth the time",["K'gari, the Whitsundays and Magnetic Island are the three island detours on this route, and each needs at least two days including transfers. Adding all three to a fortnight is what breaks the itinerary.","K'gari requires four-wheel drive and a vehicle permit or a tour, and it has strict dingo safety rules that must be followed. Choose one island and do it properly rather than rushing all three.","Whichever islands you choose, book the boat trip early in your stay in that town so a weather cancellation can be rescheduled rather than lost entirely.","Cyclone season in the tropical north runs from November to April, and a system can close the Bruce Highway and ground reef trips for several days at a time."],["Each island needs two days minimum","K'gari needs 4WD and a permit","Choose one, not three"])]
  }),
  article({
    slug: "perth-to-broome-road-trip", title: "Perth to Broome camping road trip", description: "White dunes, coral reefs, red gorges and the long bright road north.", category: "Road trips", region: "Western Australia", readTime: 11,
    places: ["The Pinnacles", "Kalbarri National Park", "Shark Bay", "Cape Range National Park", "Karijini National Park", "Eighty Mile Beach", "Broome"], imageAlt: "Red cliffs and coast in Western Australia", intro: "The west coast changes colour as you drive north from Perth. Limestone gives way to red river gorges, Ningaloo water and the long Pilbara stretches before Broome.",
    sections: [
      section("Perth to Shark Bay", ["Use Cervantes or Jurien Bay for the first night and visit the Pinnacles outside the hottest part of the day. Continue through Geraldton to Kalbarri, leaving time for both the coastal cliffs and inland gorge lookouts.", "Shark Bay is a detour, not a quick roadside stop. Base around Denham or a nearby caravan park for at least two nights if you want Monkey Mia, Shell Beach and Francois Peron country."], ["Cervantes", "Kalbarri National Park", "Denham"]),
      section("Ningaloo and Karijini", ["Cape Range National Park and Exmouth deserve several nights. Book national park camps early in the dry season and confirm water, shade and generator conditions. Coral Bay is smaller and often busy.", "The inland turn to Karijini adds serious distance. Roads, heat and gorge access change with conditions. Stay at an authorised campground and carry more water than a coastal day would suggest."]),
      section("Pilbara to Broome", ["Break the final run around Port Hedland or Eighty Mile Beach rather than forcing a very long day. Roadhouses can have limited hours, so fuel before you need it.", "Broome is an easy place to stop moving for a while. Caravan parks book out in the dry season, particularly around school holidays and major events. Reserve before leaving the Pilbara."])
    ,section("Distances change how you plan",["Perth to Broome is roughly 2,200 kilometres and the towns are far apart, with long stretches where the next fuel is several hundred kilometres away. This is the trip where range planning stops being theoretical.","Ten days is the minimum that allows stops at Kalbarri, Shark Bay, Coral Bay and Exmouth. Two weeks lets you add Karijini, which is the single best detour on the route and adds around 600 kilometres.","Book accommodation at Exmouth, Coral Bay and Broome in the dry season, because they fill with southern travellers escaping winter and there is no overflow capacity."],["Roughly 2,200 km","Ten days minimum, two weeks better","Dry season books out up north"]),section("Ningaloo is the reason to go",["Ningaloo Reef comes within a few metres of the beach at Coral Bay and Turquoise Bay, which makes it the most accessible major reef in the country. You can snorkel straight off the sand without a boat.","Whale shark tours run from roughly March to July and humpback swims later in the season. Both book out and both are weather dependent, so allow a spare day and book early in your stay rather than at the end.","Turquoise Bay has a drift snorkel where the current carries you along the reef. Get out before the sandbar at the southern end, because the current continues past it and swimming back against it is genuinely hard."],["Snorkel straight off the beach","Whale sharks roughly March to July","Exit the Turquoise Bay drift early"]),section("Karijini and the gorges",["Karijini National Park sits inland from the coast and holds the best gorge country in Western Australia, with Dales Gorge, Hancock Gorge and Weano all offering swimming in deep pools. The park is remote and the roads in include unsealed sections.","The gorge walks are graded and some are genuinely serious, involving scrambling, cold water and confined spaces. People have died in these gorges, and flash flooding after rain is the specific hazard. Do not enter a gorge if rain is forecast anywhere upstream.","There is no fuel inside the park and the nearest services are at Tom Price or Auski. Arrive with a full tank, plenty of water and enough food, because the campgrounds are basic and there is no shop."],["No fuel inside Karijini","Gorges flash flood after rain","Some walks are genuinely serious"]),section("Season, heat and the wet",["This route works in the dry season, roughly May to October, when the north is warm and dry and the roads are open. The wet season brings extreme heat, humidity, cyclones and road closures across the Pilbara and Kimberley.","Even in the dry, daytime temperatures north of Carnarvon are high and the sun is severe. Carry far more water than feels necessary, start walks early, and treat the middle of the day as time to be somewhere shaded.","Cyclone season runs roughly November to April in the north west. If you are travelling in that window, monitor warnings daily and understand that a cyclone will close roads and towns with little notice."],["Dry season is May to October","Cyclones November to April","Walk early, rest through midday"]),section("Shark Bay and the stops between",["Shark Bay is a World Heritage area with the Monkey Mia dolphins, the stromatolites at Hamelin Pool and Shell Beach, made entirely of shells metres deep. It is a substantial detour off the highway and worth a full day.","Kalbarri sits between Perth and Shark Bay with coastal cliffs and the inland gorges including Nature's Window. The park closes tracks in extreme heat, so summer visits need an early start.","Broome itself deserves two nights for Cable Beach, the Staircase to the Moon on the right dates and the pearling history at the museum.","Karijini and Ningaloo both sit a long way off the highway, so decide which you are including before leaving Perth rather than trying to fit both into a tight schedule."],["Shark Bay is a full-day detour","Kalbarri closes tracks in heat","Stromatolites are worth seeing"])]
  }),
  article({
    slug: "brisbane-to-cape-tribulation", title: "Brisbane to Cape Tribulation camping route", description: "Beach towns give way to reef islands and rainforest as the coast turns tropical.", category: "Road trips", region: "Queensland Coast", readTime: 11,
    places: ["Noosa", "K'gari", "Agnes Water", "Cape Hillsborough", "Airlie Beach", "Mission Beach", "Atherton Tablelands", "Cape Tribulation"], imageAlt: "Rainforest road near Cape Tribulation", intro: "North of Brisbane the seasons change faster than the scenery. Give the drive at least two weeks and move your longest days away from the places you most want to swim, walk or sit still.",
    sections: [
      section("Brisbane to the Capricorn Coast", ["Start with Noosa or the Cooloola coast, then decide whether K'gari fits your vehicle and schedule. Island travel brings permits, tide windows and soft sand, so it should never be treated as a spontaneous side road.", "Agnes Water is a comfortable break before the longer central coast distances. Restock in major towns and avoid turning a late finish into night driving through wildlife country."]),
      section("Whitsundays to the wet tropics", ["Cape Hillsborough offers forest, beach and a quieter night before Airlie Beach. Airlie is the practical base for Whitsunday trips, with more services and busy holiday parks.", "Mission Beach slows the pace again. Read cassowary signs, secure food and follow seasonal swimming advice. Inland, the Atherton Tablelands can be cooler and provides waterfalls, farm stays and caravan parks."], ["Cape Hillsborough", "Airlie Beach", "Mission Beach"]),
      section("Daintree and Cape Tribulation", ["Cross the Daintree River with enough fuel and daylight. Mobile reception can be patchy, roads may be affected by heavy rain and large vehicles need to check access carefully.", "Choose a legal campground or caravan park and keep food secure. Check crocodile warnings and never assume a beach or creek is safe for swimming because other people are near the water."])
    ,section("Where the Daintree changes the rules",["North of the Daintree River the road becomes narrower, steeper and partly unsealed beyond Cape Tribulation. The Bloomfield Track to Cooktown is four-wheel drive only, prohibited in most rentals, and impassable after rain.","The Daintree River ferry is the only crossing and runs to set hours with a queue in peak season. Check the operating times before planning a late return, because being on the wrong side after the last ferry means a very long detour.","Accommodation north of the river is limited and books out. There is no supermarket and fuel is expensive, so restock in Mossman or Port Douglas before crossing."],["Ferry has set hours and queues","Restock before crossing the river","Bloomfield Track is 4WD only"]),section("Crocodiles are the constraint up here",["Estuarine crocodiles inhabit every waterway in the tropical north, including creeks, mangroves, estuaries and the beaches themselves. The Daintree and Cape Tribulation coast is prime habitat and the risk is real rather than theoretical.","Do not swim in or beside any waterway unless it is a designated safe swimming area. Do not camp within a few metres of the water, do not clean fish at the edge, and do not stand in the shallows for a photograph.","The safe swimming here is in the designated freshwater holes such as Mossman Gorge and Emmagen Creek, and even those carry signage worth reading each visit because conditions change."],["Assume crocs in every waterway","No swimming outside designated spots","Read the signage on every visit"]),section("Rainforest, reef and the wet season",["The Daintree is the oldest continuously surviving rainforest on the planet and the boardwalks at Marrdja and Dubuji are the easiest way to see it properly. Early morning gives the best chance of cassowaries and the fewest people.","Cape Tribulation is where the rainforest meets the reef, and reef trips run from Cape Trib and Port Douglas. The northern reef sites are generally in better condition than those closer to Cairns.","The wet season, roughly November to April, brings heavy rain, road closures and stinger season. The dry season is the straightforward time to visit and also when the roads and tours reliably operate."],["Boardwalks are the easy access","Cassowaries are most active early","Dry season May to October"]),section("Breaking the drive from Brisbane",["Brisbane to Cape Tribulation is around 1,900 kilometres and needs a minimum of five driving days to be enjoyable. The Sunshine Coast, Hervey Bay, Airlie Beach and Townsville are the natural overnight breaks.","The Bruce Highway carries heavy freight and is not a scenic drive for much of its length. Treat the southern half as transit and save the time for the tropical north, which is what you came for.","Consider flying to Cairns and hiring there if your time is limited. It removes four days of driving and puts you straight into the part of the route that is genuinely distinctive."],["Around 1,900 km from Brisbane","Southern half is transit","Flying to Cairns saves four days"]),section("Cassowaries and driving in the wet tropics",["Southern cassowaries live in the rainforest between Mission Beach and the Daintree and are struck by vehicles regularly. Signed cassowary zones require reduced speed and they mean it.","They are large, powerful birds and can be dangerous if approached or fed. Never feed one, keep well back, and if one approaches put a tree or your vehicle between you rather than running.","Mission Beach and Etty Bay south of Cairns are the other reliable cassowary areas, and Etty Bay in particular sees them come onto the beach.","The Daintree ferry queue can exceed an hour in peak season, so aim to cross mid-morning or late afternoon rather than around the middle of the day."],["Slow in signed cassowary zones","Never feed or approach one","Put an object between you, do not run"])]
  }),
  article({
    slug: "melbourne-to-adelaide-coastal-route", title: "Melbourne to Adelaide coastal camping route", description: "Sea cliffs, fishing towns and empty Coorong beaches on the slower road west.", category: "Road trips", region: "Southern Coast", readTime: 9,
    places: ["Torquay", "Apollo Bay", "Port Fairy", "Mount Gambier", "Robe", "Coorong National Park", "Adelaide"], imageAlt: "Limestone coast between Victoria and South Australia", intro: "The coastal road from Melbourne to Adelaide works best over five to seven days. It combines the Great Ocean Road with volcanic country, fishing towns and the long lagoons of the Coorong.",
    sections: [
      section("Melbourne to Port Fairy", ["Follow the Great Ocean Road through Torquay and Apollo Bay, then stay west of the busiest viewpoints for the night. Port Campbell, Warrnambool and Port Fairy all have caravan parks and groceries.", "Do not underestimate fatigue on the winding section. Short distances take time and wildlife becomes harder to see near dusk."]),
      section("The Limestone Coast", ["Cross into South Australia through Mount Gambier, where sinkholes, crater lakes and full-service caravan parks make an easy reset. Continue to Beachport or Robe for a coast night.", "Check whether beach tracks suit your vehicle and rental agreement. Soft sand, tide and changing access make local advice more valuable than an old track report."], ["Mount Gambier", "Robe", "Beachport"]),
      section("Coorong to Adelaide", ["The Coorong is long, windswept and sparse. Camp only in designated areas, carry water and protect food from wildlife. Fire rules can be strict even when evenings feel cool.", "Approach Adelaide through Meningie and the lower Murray, or take more time around the Fleurieu Peninsula. Finish with a powered site if you need laundry and a full vehicle reset."])
    ,section("Two routes, two very different trips",["The coastal route through the Great Ocean Road and Warrnambool to Mount Gambier is roughly 900 kilometres and takes at least four days done properly. The inland Western Highway is around 730 kilometres and can be driven in a long day.","The coastal option gives you the Twelve Apostles, the Bay of Islands, Cape Bridgewater and the Limestone Coast. The inland option gives you the Grampians, which is a serious destination in its own right.","If you have a week, do the coast one way and the Grampians on the return. That covers both and avoids driving the same road twice."],["Coast is 900 km, inland 730 km","Coast out, Grampians back","Four days minimum for the coast"]),section("The Limestone Coast and the sinkholes",["Mount Gambier sits on limestone country and the Blue Lake changes colour dramatically from grey to intense blue around November each year. Umpherston Sinkhole, a collapsed cave turned into a sunken garden, is free and genuinely unusual.","Cave diving in the region is world-renowned and strictly certification-controlled. The Kilsby Sinkhole and Piccaninnie Ponds have snorkelling options for people without cave qualifications, and the water clarity is extraordinary.","Robe and Beachport further north are quieter coastal towns with good camping and far fewer visitors than the Victorian side of the border. They make an easy final night before Adelaide."],["Blue Lake turns blue around November","Umpherston Sinkhole is free","Robe and Beachport are quiet"]),section("Crossing the border",["South Australia enforces fruit fly quarantine at the border, and fresh fruit and vegetables cannot be carried in. Disposal bins are provided at the checkpoint and fines apply for carrying prohibited produce, whether or not you knew.","Plan your shopping around this: buy fresh produce after the border rather than before it. This catches out a substantial number of travellers who stock up in Victoria the night before crossing.","There is also a time zone change of half an hour between Victoria and South Australia, which matters for ferry bookings, tour times and campground check-in."],["No fresh produce into South Australia","Shop after the border","Half-hour time zone change"]),section("Whales, seals and the southern coast",["Southern right whales calve along this coast between roughly May and October, and Logans Beach at Warrnambool has a purpose-built viewing platform where they come close to shore. Nearby Portland and Cape Bridgewater add seal colonies.","Cape Bridgewater has one of the largest Australian fur seal colonies on the mainland, reachable by a clifftop walk. The blowholes and the petrified forest walk nearby make it a half day rather than a quick stop.","Tower Hill, an extinct volcano near Warrnambool, is a wildlife reserve with emus, koalas and kangaroos in an unusually accessible setting. It is free and quiet in the early morning."],["Whales May to October","Cape Bridgewater seal colony","Tower Hill is free and quiet"]),section("The Coorong and the Murray mouth",["East of Adelaide the Coorong stretches for over a hundred kilometres of lagoon behind a dune barrier, with camping, birdlife and almost nobody. It is a very different landscape from the limestone coast.","The Murray mouth at Goolwa marks the end of Australia's largest river system, and the barrages and ferry crossings around it are worth the detour before the run into Adelaide.","Allow time for the Fleurieu Peninsula on the approach to Adelaide, where McLaren Vale and the coast at Victor Harbor make an easy final day.","Grampians access roads and walking tracks have been affected by fire and flood in recent years, so confirm the specific track is open before building a day around it."],["Coorong is quiet and unusual","Murray mouth is worth the detour","Free ferry crossings near Goolwa"])]
  }),
  article({
    slug: "tasmania-camping-loop", title: "Tasmania camping loop: 10 days from Hobart", description: "Granite bays, tall forests and cold mountain mornings on a lap from Hobart.", category: "Road trips", region: "Tasmania", readTime: 10,
    places: ["Hobart", "Freycinet National Park", "Bay of Fires", "Launceston", "Cradle Mountain", "Strahan", "Mount Field National Park"], imageAlt: "Granite coast and blue water in Tasmania", intro: "Ten days is enough for a rewarding Tasmanian loop if you accept that one coast will always tempt you to stay longer. Carry warm layers in every season and leave room for weather to change the order.",
    sections: [
      section("Hobart to the east coast", ["Leave Hobart for the Tasman Peninsula or head directly to Freycinet. National park entry needs a valid pass and popular camps around Freycinet use booking arrangements that can change by season.", "Continue north through Bicheno to the Bay of Fires. Use established campgrounds, protect fragile dunes and expect simple facilities away from town."], ["Freycinet National Park", "Bicheno", "Bay of Fires"]),
      section("North to Cradle Mountain", ["Launceston is the best place to restock before turning west. Cradle Mountain weather can move from sun to sleet in a single afternoon, and the visitor transport system affects how you reach walks.", "Stay at a campground or holiday park that suits your heating, power and shower needs. A cold wet night is easier when your gear has somewhere to dry."]),
      section("West coast and the return south", ["Strahan and the west coast bring long bends, wet forest and slower driving. Fuel early and avoid building a tight schedule around a road that rewards patience.", "Return through the central highlands or Mount Field National Park. If conditions turn poor, choose the lower and safer route rather than forcing an alpine plan."])
    ,section("Getting the vehicle there",["The Spirit of Tasmania sails Geelong to Devonport and takes vehicles, with day and night crossings across Bass Strait. Fares are set by vehicle length and height, book out over summer, and the strait can be genuinely rough.","Flying and hiring locally is the alternative and frequently cheaper for a shorter trip, since the ferry plus fuel to Geelong adds up. Hire vehicles in Tasmania are limited in peak season and should be booked early.","Whichever way you arrive, Tasmania has strict quarantine on fresh produce, plants and honey. Eat or dispose of fruit and vegetables before boarding rather than having them confiscated."],["Ferry priced by vehicle size","Flying and hiring is often cheaper","No fresh produce across the strait"]),section("Ten days and the shape of the loop",["A clean circuit from Hobart runs east coast to Bay of Fires, across to Launceston, west to Cradle Mountain, down the west coast through Strahan, and back via Lake St Clair and the Derwent Valley. That is roughly 1,400 kilometres.","Tasmanian distances look small and drive long. The roads are winding, often narrow, and the west coast in particular is slow. Budget well above what the map suggests, especially in a campervan.","Two nights at Cradle Mountain and two on the east coast are the ones worth protecting. Everything else can flex around weather, which in Tasmania it will need to."],["Roughly 1,400 km loop","Roads drive far longer than they look","Two nights at Cradle Mountain"]),section("Cradle Mountain and the park pass",["A Tasmania Parks Pass is required for vehicle entry to national parks and a holiday pass covering all parks for eight weeks is far better value than individual day entries if you visit more than two.","Cradle Mountain runs a mandatory shuttle bus from the visitor centre during the day, with private vehicle access restricted. Plan around the shuttle timetable and book the pass in advance in peak season.","Dove Lake circuit is the accessible highlight at around two hours. The summit climb is a serious six to eight hour day with exposed scrambling and weather that changes fast, and it is not a casual walk."],["Buy the holiday parks pass","Shuttle bus is mandatory at Cradle","Summit climb is a serious day"]),section("Weather and the west coast",["Tasmania's weather is the most changeable in the country and the west coast is one of the wettest places in Australia. Four seasons in a day is a genuine description rather than a saying, and alpine areas can get snow in any month.","Carry warm and waterproof layers even in January, and treat any walk above the treeline as an alpine outing regardless of the forecast at the car park. People get into trouble on Tasmanian day walks every season.","The west coast towns of Strahan, Queenstown and Zeehan are worth the detour for the Gordon River cruise and the mining history, and they are considerably quieter than the east."],["Snow possible in any month","Treat walks above treeline as alpine","West coast is wet and quiet"]),section("Wineglass Bay and the east coast",["Freycinet's Wineglass Bay lookout is around an hour and a half return and the beach itself adds another hour each way. The car park fills early in summer and a shuttle operates in peak season.","The Bay of Fires further north has free and low-cost camping behind orange lichen-covered granite and white sand, and it is one of the best stretches of coastal camping in the country.","Bruny Island south of Hobart adds a day and delivers cheese, oysters, a lighthouse and some of the best coastal scenery in the state.","Book the Spirit of Tasmania as early as your dates allow, because vehicle spaces on the popular sailings sell out months ahead over summer."],["Freycinet car park fills early","Bay of Fires has free camping","Lookout is 90 minutes return"])]
  }),
  article({
    slug: "darwin-kakadu-litchfield-loop", title: "Darwin, Kakadu and Litchfield camping loop", description: "Waterfalls, stone country and wide floodplains beneath the Top End dry-season sky.", category: "Road trips", region: "Northern Territory", readTime: 10,
    places: ["Darwin", "Litchfield National Park", "Wangi Falls Campground", "Kakadu National Park", "Cooinda", "Mary River National Park"], imageAlt: "Top End waterfall and escarpment", intro: "A week from Darwin can connect Litchfield, Kakadu and Mary River, but water access, campgrounds and roads change sharply between wet and dry seasons.",
    sections: [
      section("Litchfield first", ["Drive south from Darwin and settle into a designated Litchfield campground before chasing waterfalls. Wangi Falls, Florence Falls and other swimming areas open or close according to conditions.", "Never treat clear water as permission to swim. Read crocodile and closure signs at every location, every time."], ["Wangi Falls Campground", "Florence Falls", "Darwin"]),
      section("Across to Kakadu", ["Allow more than one night in Kakadu. The park is vast and distances between art sites, wetlands and campgrounds add up quickly. A park pass and separate campground arrangements may apply.", "Cooinda is a useful serviced base, while simpler camps trade facilities for location. Carry water, fuel conservatively and check roads after any rain."]),
      section("Mary River and the return", ["Mary River wetlands make a slower final leg before Darwin. Stay back from water edges and follow local crocodile advice, including at boat ramps and fishing spots.", "The Top End heat remains serious in the dry. Walk early, rest through the hottest hours and keep drinking water accessible inside the vehicle."])
    ,section("The wet and the dry decide everything",["The dry season, roughly May to October, is when this loop works: roads open, waterfalls accessible, humidity manageable and campgrounds operating. The wet season closes large parts of Kakadu and makes travel genuinely difficult.","The shoulder months at either end are the sweet spot. Waterfalls still run strongly in May and June after the wet, while the roads have reopened and the crowds have not fully arrived.","In the wet, from November to April, expect extreme humidity, monsoonal storms, road closures and many walks and campgrounds shut. Some people prefer it for the scale of the waterfalls, but it is not a straightforward trip."],["Dry season is May to October","May and June for full waterfalls","Wet season closes much of Kakadu"]),section("Crocodiles govern every water decision",["Kakadu and Litchfield are both serious crocodile country and estuarine crocodiles are present in waterways that look completely safe. Every year animals are removed from swimming holes, and the survey status of a hole can change between seasons.","Swim only where current signage explicitly permits it, and check on the day rather than relying on a guidebook or a previous visit. Wangi Falls and Florence Falls in Litchfield are the commonly open ones, and even they close after surveys.","Do not camp at the water's edge, clean fish beside a river or launch a kayak in unsurveyed water. Freshwater crocodiles are also present and are generally harmless if left alone, but distinguishing them from a distance is not a skill to rely on."],["Only swim where signed open today","Holes close after surveys","Never camp at the water's edge"]),section("Kakadu permits, passes and culture",["Kakadu requires a park pass, purchasable online, and it is a living cultural landscape jointly managed with its Traditional Owners. Some areas are restricted and photography is prohibited at certain rock art and ceremonial sites.","The rock art at Ubirr and Nourlangie is among the oldest continuous artistic tradition anywhere, some of it tens of thousands of years old. Take a guided walk if one is running, because the interpretation transforms what you are looking at.","Respect closures and restricted areas without exception. These are not administrative boundaries but conditions of access to somebody's country."],["Buy the Kakadu pass online","Some sites prohibit photography","Guided walks transform the rock art"]),section("Vehicle requirements and Litchfield",["Much of Kakadu's best country, including Jim Jim Falls and Twin Falls, requires a high-clearance four-wheel drive and involves creek crossings. Two-wheel drive vehicles are limited to the sealed roads, which still reach Ubirr, Nourlangie and Gunlom.","Litchfield is considerably more accessible, with Florence, Wangi and Tolmer falls all reachable in a two-wheel drive on sealed roads. For travellers without a four-wheel drive, Litchfield delivers more per day than Kakadu.","Check your rental agreement before attempting any unsealed road here. Most standard hire agreements prohibit them entirely, and recovery in this country is expensive."],["Jim Jim and Twin Falls need 4WD","Litchfield works in a 2WD","Most rentals prohibit unsealed roads"]),section("Darwin as a base",["Darwin has the services, supermarkets and hire depots that nothing else up here does, plus Mindil Beach markets in the dry season and the Museum and Art Gallery explaining Cyclone Tracy and the 1942 bombing.","Restock properly before heading into either park, because there is no supermarket in Kakadu and prices at the roadhouses reflect the distance. Fuel is also considerably cheaper in town.","Katherine and Nitmiluk Gorge sit south of the loop and are worth adding if you have the days, with boat trips and canoeing through the gorge system.","Waterfall access in Kakadu opens progressively as the wet recedes, so a May visit may find some sites still closed that will be open by June."],["Restock and refuel in Darwin","Mindil markets run in the dry","No supermarket inside Kakadu"])]
  }),
  article({
    slug: "adelaide-to-uluru-road-trip", title: "Adelaide to Uluṟu: an outback camping route", description: "Flinders ridges, underground Coober Pedy and red desert horizons all the way north.", category: "Road trips", region: "Outback", readTime: 11,
    places: ["Flinders Ranges", "Wilpena Pound", "Coober Pedy", "Marla", "Erldunda", "Uluṟu-Kata Tjuṯa National Park", "Alice Springs"], imageAlt: "Red outback road in central Australia", intro: "Adelaide to Uluṟu is a long desert journey, not a single transfer. Seven to ten days allows time for Ikara, Coober Pedy and the Red Centre without stacking exhausting drives.",
    sections: [
      section("Adelaide to the Flinders", ["Break north around the Clare Valley or reach Hawker for the first major base. Ikara-Flinders Ranges rewards at least two nights, with walks starting early before the heat rises.", "Check park entry, campground booking and road conditions. Unsealed gorge roads may be unsuitable after rain or under a rental agreement."], ["Hawker", "Wilpena Pound", "Ikara-Flinders Ranges"]),
      section("Coober Pedy to the border", ["The Stuart Highway opens into long distances after Port Augusta. Coober Pedy provides fuel, groceries, repairs and a memorable roofed night underground if you want a break from the tent.", "Continue through Marla with a firm fuel plan. Roadhouses can change hours and mobile coverage is not a safety system."]),
      section("Uluṟu and beyond", ["Turn west at Erldunda for Uluṟu-Kata Tjuṯa National Park. Stay in authorised accommodation around Yulara and respect closures, cultural guidance and photography restrictions.", "Alice Springs is another substantial drive. If it follows your Uluṟu stay, add Kings Canyon only when time, fuel and road access genuinely fit."])
    ,section("The Stuart Highway and its distances",["Adelaide to Uluru is roughly 1,600 kilometres, most of it on the Stuart Highway through country with very few towns. Coober Pedy, Marla and Kulgera are the main service points and the gaps between them are substantial.","Carry more water than you think you need, a minimum of four litres per person per day plus a reserve for the vehicle. Fuel range should assume the next station may be closed, because in this country it sometimes is.","Allow four days each way at a sensible pace. Done faster it becomes an endurance exercise, and fatigue on straight outback roads is a well-documented killer."],["Roughly 1,600 km each way","Four litres of water per person per day","Four days each way is sensible"]),section("Coober Pedy is worth a night",["Coober Pedy is the opal mining town where much of the population lives underground to escape the heat, and the dugout homes, underground churches and hotels are genuinely unusual rather than a novelty.","Summer temperatures regularly exceed forty degrees and the underground accommodation is the practical choice as well as the interesting one. The Breakaways, a short drive out, are best at sunrise or sunset.","Do not walk near mine shafts. The area around the town is riddled with unmarked and unfenced shafts, and people have died falling into them. Stay on marked areas and never walk backwards while taking photographs."],["Underground stays beat the heat","Breakaways at sunrise or sunset","Unmarked mine shafts are lethal"]),section("Uluru and respecting the site",["Climbing Uluru has been prohibited since 2019 at the request of the Anangu Traditional Owners. The base walk, around ten kilometres, is the proper way to experience it and shows you far more than the climb ever did.","Some areas of the rock are sacred and photography is prohibited there, marked by signage. Respecting those signs is a basic condition of visiting, not an optional courtesy.","Start the base walk early. Summer temperatures make it dangerous after mid-morning and rangers close sections when the forecast exceeds a threshold. Carry more water than the distance suggests."],["Climbing is prohibited","No photography at signed sacred areas","Start the base walk at first light"]),section("Kata Tjuta and Kings Canyon",["Kata Tjuta, around fifty kilometres from Uluru, is arguably the more impressive formation and the Valley of the Winds walk is the best in the park. It is exposed and closes in heat, so start it at dawn.","Kings Canyon sits between Uluru and Alice Springs on the Red Centre Way, and the rim walk is a three to four hour circuit with a steep initial climb and genuine drop-offs. It is the highlight of many trips out here.","A national park pass covers Uluru-Kata Tjuta and is bought in advance. Watarrka, containing Kings Canyon, is separate. Check what your route needs before arriving at a gate."],["Valley of the Winds at dawn","Kings Canyon rim walk is 3 to 4 hours","Park passes differ, check both"]),section("Sunrise, sunset and the viewing areas",["There are designated sunrise and sunset viewing areas for both Uluru and Kata Tjuta, and they fill with coaches. Arriving early enough to park and walk to a spot away from the main platform is worth the effort.","Photography restrictions apply at signed sacred areas and commercial photography needs a permit. The Field of Light installation and the various dining experiences book out well ahead in peak season.","Consider flying one leg if time is short, since Ayers Rock Airport has direct services and the drive is the same in both directions.","Summer temperatures at Uluru regularly exceed forty degrees and walks close on extreme days, which makes winter the far more comfortable season for this route."],["Designated viewing areas fill early","Photography restrictions are signed","Book experiences well ahead"])]
  }),
  article({
    slug: "sydney-south-coast-camping", title: "Sydney to the Sapphire Coast camping guide", description: "Quiet coves, spotted gums and small coastal towns between Sydney and Eden.", category: "Road trips", region: "NSW South Coast", readTime: 9,
    places: ["Royal National Park", "Jervis Bay", "Murramarang National Park", "Bermagui", "Mimosa Rocks National Park", "Eden"], imageAlt: "NSW South Coast beach and forest", intro: "The NSW South Coast can fill a long weekend or two relaxed weeks. Outside peak holidays, the rhythm is simple: a short drive, a swim or walk, then camp before dark.",
    sections: [
      section("Sydney to Jervis Bay", ["Leave Sydney through Royal National Park or take the faster highway south. Kiama and the Shoalhaven make good food stops before the beaches around Jervis Bay.", "National park, council and commercial campgrounds all use different booking systems. Summer and Easter sites disappear early."], ["Royal National Park", "Kiama", "Jervis Bay"]),
      section("Murramarang to Bermagui", ["Murramarang National Park mixes spotted gum forest with small beaches and wildlife around camp. Store food properly and keep a respectful distance from kangaroos.", "Batemans Bay, Moruya and Narooma cover fuel and groceries. Bermagui gives the trip a slower small-town night before the more remote coast south." ]),
      section("Mimosa Rocks to Eden", ["Mimosa Rocks has beautiful simple campgrounds, but access, water and facilities vary. Read the exact campground page before turning in.", "Finish around Eden for caravan parks, roofed stays and a full resupply. In fire or storm conditions, stay flexible and use the main highway rather than forcing a park road."])
    ,section("The stretch that makes this trip",["South of Wollongong the coast opens into Jervis Bay, Ulladulla, Batemans Bay and the Sapphire Coast, with white sand beaches and national parks running most of the way to the Victorian border. It is around 500 kilometres to Eden.","Jervis Bay has some of the whitest sand in the world at Hyams Beach and Booderee National Park, which is jointly managed with the Wreck Bay Aboriginal Community and charges its own entry fee separate from NSW parks.","The Grand Pacific Drive and Sea Cliff Bridge just south of Sydney are worth the slower coastal start rather than taking the highway. It adds under an hour and is one of the better short drives in the state."],["Around 500 km to Eden","Booderee charges separately","Take the Sea Cliff Bridge route"]),section("Booking national park campgrounds",["NSW National Parks campgrounds along this coast are booked online and the popular ones, particularly in Murramarang and Booderee, sell out months ahead for summer and school holidays. Walk-up availability is rare.","Vehicle entry fees apply to many parks separately from camping fees, and an annual All Parks Pass is worth it if you are visiting several. Check whether your campground booking includes entry.","Outside peak periods the same sites are quiet and frequently available a few days ahead, which makes autumn and spring the easy time to do this route."],["Book NSW parks months ahead in summer","Vehicle entry is often separate","Autumn and spring are easy"]),section("Kangaroos on the beach and other wildlife",["Pebbly Beach and Depot Beach in Murramarang are known for eastern grey kangaroos on the sand, and they are entirely wild despite being habituated to people. Do not feed them, and keep a distance, because large males can be dangerous.","Whale migration passes this coast twice a year, northbound roughly May to July and southbound September to November. Eden has a whale festival and land-based viewing from headlands is genuinely good.","Seals, dolphins and little penguins are all present along the coast, and Montague Island off Narooma runs tours to a seal colony and penguin rookery. Trips are weather dependent."],["Do not feed the kangaroos","Whales May to July, then Sept to Nov","Montague Island for seals"]),section("Bushfire awareness on this coast",["The South Coast was severely burnt in the 2019 to 2020 fires and remains high risk in summer. Fire danger ratings are posted at park entrances and on roadside signs, and total fire bans are common in summer.","Have a plan for a catastrophic day, which usually means leaving early rather than sheltering. Campgrounds in forested areas are among the worst places to be, and roads close quickly once a fire is running.","Download the Fires Near Me app or equivalent and check it daily in summer. Reception is patchy along parts of this coast, so check while you have signal rather than assuming you can look it up later."],["Check fire danger ratings daily","Leave early on catastrophic days","Reception is patchy, check in advance"]),section("Oysters, dairy and the food stops",["The Clyde River at Batemans Bay and the Pambula and Wapengo estuaries produce some of the best oysters in the country, sold directly from the growers at a fraction of restaurant prices.","Bermagui, Central Tilba and Milton are the food stops worth planning around, with Tilba a preserved dairy village and Milton a good base between Ulladulla and Jervis Bay.","Eden at the southern end has the Killer Whale Museum and works as either a turning point or a stop on the way into Victoria.","NSW National Parks releases campground bookings on a rolling window, and the best coastal sites for summer are taken within minutes of becoming available."],["Buy oysters direct from growers","Central Tilba is a preserved village","Milton works as a base"])]
  }),
  article({
    slug: "nullarbor-crossing-camping-guide", title: "Crossing the Nullarbor: camps, fuel and preparation", description: "A huge sky, a straight road and more life along the plain than first meets the eye.", category: "Road trips", region: "Nullarbor", readTime: 10,
    places: ["Ceduna", "Penong", "Nullarbor Roadhouse", "Border Village", "Eucla", "Madura", "Norseman"], imageAlt: "Eyre Highway across the Nullarbor Plain", intro: "Ceduna to Norseman is roughly 1,200 kilometres. The Eyre Highway is sealed, but wind, heat, wildlife, fuel spacing and fatigue still demand a conservative plan.",
    sections: [
      section("Before Ceduna", ["Service the vehicle, check the spare tyre and learn how to use the jack before leaving a major centre. Fill water containers and keep food that can survive a delayed day.", "Ceduna is the last broad resupply before the crossing. Check South Australian and Western Australian biosecurity rules before carrying fruit, vegetables, honey or plant material west."], ["Vehicle fluids checked", "Tyre pressures checked", "Water accessible", "Biosecurity items sorted"]),
      section("Across the plain", ["Use Penong, Nullarbor Roadhouse, Border Village, Eucla and Madura to divide the drive. Fuel prices are part of remote travel, and passing an open pump to save a little can erase your margin.", "Do not drive at dawn, dusk or night if you can avoid it. Wildlife and stock are harder to see, and fatigue builds quietly on long straight sections." ]),
      section("Camping and the Bight", ["Use legal roadside, roadhouse or caravan park options and keep clear of truck rest areas. Some coastal tracks are exposed, unsealed or unsuitable after weather.", "Cliff lookouts along the Great Australian Bight are unforgettable, but barriers and warnings matter. Wind is powerful and cliff edges are unstable. Keep well back."])
    ,section("The scale of it",["The Eyre Highway between Norseman and Ceduna is around 1,200 kilometres, including the 90 Mile Straight, the longest straight stretch of sealed road in Australia at 146.6 kilometres. Roadhouses are the only services and they are spaced 100 to 200 kilometres apart.","Three days is a comfortable crossing. Two is possible and tiring, and one is dangerous. Fatigue is the single biggest risk out here, more than mechanical failure or wildlife.","Fuel is available at every roadhouse but at a substantial premium over city prices. Budget for it rather than trying to stretch between the cheaper ones, which is how people run dry."],["Around 1,200 km, three days","Roadhouses every 100 to 200 km","Fuel is expensive, budget for it"]),section("Preparation that actually matters",["Carry at least twenty litres of drinking water regardless of season, a working spare with the tools to fit it, and enough food for a day longer than you plan. Mobile coverage exists only near roadhouses and towns.","Tell someone your route and expected arrival. If you break down, stay with the vehicle: it is shelter, it is visible from the air and the road, and walking in this country has killed people.","Consider a satellite messenger or a personal locator beacon. They are cheap to hire and are the only reliable way to call for help across most of the crossing."],["Twenty litres of water minimum","Stay with the vehicle if you break down","Hire a satellite messenger"]),section("Wildlife, road trains and driving hours",["Kangaroos, wombats, emus and camels are all active around dawn and dusk, and a strike at highway speed will disable a vehicle. Drive only in full daylight and accept a shorter day rather than pushing into the last light.","Road trains up to 53.5 metres run this highway constantly. Overtaking one requires a very long clear stretch, and the turbulence as they pass is significant in a high-sided vehicle. Give them room and do not sit in the blind spot.","Stop every two hours. The road is straight, the scenery repeats and hypnosis is a genuine documented phenomenon here. The roadhouse stops exist for exactly this reason."],["Drive in daylight only","Road trains up to 53.5 metres","Stop every two hours"]),section("What is actually worth stopping for",["The Bunda Cliffs, where the Nullarbor Plain drops straight into the Southern Ocean, are the visual highlight and there are several signed lookouts along the highway. They are unfenced, so keep well back from the edge.","The Head of Bight is a southern right whale nursery between roughly June and October, with a boardwalk and viewing platforms. It is one of the best land-based whale viewing sites in the country.","Eucla has the ruins of the old telegraph station being swallowed by sand dunes, and the golf course spanning the crossing has holes at roadhouses along the route. Also note the time zone changes, including an unofficial one used locally."],["Bunda Cliffs are unfenced","Head of Bight whales June to October","Multiple time zone changes"]),section("Where to actually sleep",["Roadhouses along the Eyre Highway offer powered and unpowered sites, and there are free rest areas and gravel pits between them where overnight stops are permitted. The roadhouse option buys a shower and security.","Several free camps sit along the Bunda Cliffs with no facilities and extraordinary positions. They are exposed, unfenced and have no water, so they suit self-sufficient vehicles only.","Norseman and Ceduna bookend the crossing and both are worth a proper rest stop, with services, fuel and somewhere to sleep before or after the long stretch.","Quarantine applies in both directions, with fruit fly checks entering South Australia and a separate checkpoint entering Western Australia, so plan the fridge for both."],["Roadhouses buy a shower","Cliff camps have no facilities","Exposed and unfenced sites"])]
  }),
  article({
    slug: "queensland-outback-way", title: "Queensland outback camping route", description: "Sandstone gorge walks, stock-route towns and ancient country across western Queensland.", category: "Road trips", region: "Outback Queensland", readTime: 10,
    places: ["Carnarvon Gorge", "Takarakka Bush Resort", "Longreach", "Winton", "Mount Isa", "Boodjamulla National Park"], imageAlt: "Outback Queensland gorge country", intro: "Carnarvon Gorge to Boodjamulla crosses very large distances. Ten days is a minimum for meaningful stops, and the cooler dry months are far kinder for walking and camping.",
    sections: [
      section("Carnarvon Gorge", ["Book a base near Carnarvon Gorge and start walks early. Takarakka and national park arrangements differ, so confirm the exact site, access and facilities.", "Carry water on every walk and do not plan a long gorge day immediately after a full driving day." ]),
      section("Longreach and Winton", ["Longreach provides repairs, groceries and a strong dose of pastoral history. Winton adds dinosaur country and makes a sensible second base before turning farther west.", "Fuel distances grow and reception thins. Ask locally about road conditions, especially after rain, and avoid unsealed shortcuts that do not suit your vehicle."], ["Longreach", "Winton", "Mount Isa"]),
      section("Boodjamulla", ["Boodjamulla National Park is remote and seasonal access matters. Confirm the road, campground booking, fuel range and whether your vehicle setup is suitable before leaving Mount Isa or Camooweal.", "Stay longer than one night if conditions allow. The journey is too substantial to treat the park as a quick photograph before turning around."])
    ,section("Distances and the roadhouse rhythm",["Outback Queensland runs on roadhouses rather than towns, and the gaps between fuel can exceed 200 kilometres. Winton, Longreach, Barcaldine and Charleville are the main service centres and everything between them is sparse.","Fuel range is the planning constraint. Fill at every opportunity rather than at every need, and carry twenty litres of drinking water minimum plus food for an extra day.","Mobile coverage exists in towns and disappears between them. Tell someone your route and expected arrival, and consider hiring a satellite messenger for the remoter legs."],["Fill at every roadhouse","20 litres of water minimum","No coverage between towns"]),section("Dinosaurs and the inland sea",["Winton and Richmond sit on some of the richest dinosaur fossil country in the world, and the Australian Age of Dinosaurs facility near Winton holds the largest collection of Australian dinosaur fossils. Tours run to a working laboratory.","Lark Quarry preserves a set of dinosaur trackways, and the drive out is unsealed and can close after rain. Check conditions before committing, because the road becomes impassable quickly.","Richmond and Hughenden complete the fossil trail to the north, and together they explain the inland sea that covered this country. It is a genuinely unusual thing to build a road trip around."],["Age of Dinosaurs near Winton","Lark Quarry road closes after rain","Fossil trail runs Winton to Richmond"]),section("Unsealed roads and the wet",["Many outback Queensland roads are unsealed and close entirely after rain, sometimes for days, because driving them wet destroys the surface and attracts substantial fines. Closure is enforced and not advisory.","Check road conditions with the relevant council or the state road authority before setting out each day. A dry forecast where you are means nothing if it rained upstream two days ago.","The wet season, roughly November to March, brings extreme heat as well as closures. The dry season from April to October is when this country is comfortable and accessible."],["Driving closed roads carries fines","Check conditions daily","Dry season April to October"]),section("Artesian baths and stargazing",["The Great Artesian Basin feeds hot bore baths in many outback towns, and soaking in mineral water at forty degrees under a desert sky is one of the genuine pleasures of this trip. Mitchell, Cunnamulla and Eulo all have facilities.","The night skies out here are among the darkest accessible anywhere, with essentially no light pollution. Charleville has the Cosmos Centre with telescope viewing, and any roadhouse car park will show you the Milky Way properly.","Bring a red torch and give your eyes twenty minutes to adjust. A phone screen at full brightness ruins night vision for everyone nearby, and out here that is a real loss."],["Artesian bore baths in many towns","Some of the darkest skies anywhere","Red torch, 20 minutes to adjust"]),section("Longreach and the Stockman's Hall of Fame",["Longreach holds the Australian Stockman's Hall of Fame and the Qantas Founders Museum, including a decommissioned 747 you can walk through. Together they explain the inland far better than the landscape alone does.","Winton has the Waltzing Matilda Centre and the Musical Fence, and the town's pubs are worth an evening. These inland towns depend on visitor spending, so stopping matters more here than on the coast.","Charleville and Cunnamulla in the south link back towards New South Wales, and both have artesian bore baths and dark sky facilities.","Unsealed outback roads close after rain and stay closed until they dry, which can be several days, so build flexibility into any route using them."],["Qantas museum has a walk-through 747","Winton for Waltzing Matilda","Inland towns depend on visitors"])]
  }),
  article({
    slug: "south-west-wa-camping-loop", title: "South West WA camping loop from Perth", description: "Vineyards, giant karri forest and granite bays on the green edge of Western Australia.", category: "Road trips", region: "Western Australia Coast", readTime: 10,
    places: ["Bunbury", "Margaret River", "Hamelin Bay", "Pemberton", "Walpole", "Albany", "Esperance", "Cape Le Grand National Park"], imageAlt: "Turquoise bay in south-west Western Australia", intro: "A Perth to Esperance loop can take ten days, but two weeks lets Margaret River, the karri forests and the south coast feel like places rather than fuel stops.",
    sections: [
      section("Perth to the capes", ["Head south through Bunbury toward Busselton and Margaret River. Caravan parks are plentiful, while national park camps need closer attention to booking, water and fire conditions.", "Hamelin Bay and the capes are exposed to changing wind. Choose the side of the coast that fits the forecast rather than locking every night months ahead." ]),
      section("Karri country to Albany", ["Pemberton and Walpole trade surf for tall forest, cooler nights and winding roads. Give wet gear time to dry and watch for wildlife through shaded sections.", "Albany makes an excellent two-night reset with history, coastal walks, food and repairs. Summer remains fire season even when the forest feels green."], ["Pemberton", "Walpole", "Albany"]),
      section("Esperance and Cape Le Grand", ["The drive from Albany to Esperance is long enough to deserve a break. Reach Cape Le Grand with food, water and a confirmed campground if staying inside the park.", "Beach access is not a promise that every vehicle belongs on the sand. Check local conditions, tyre advice and rental exclusions before leaving sealed roads."])
    ,section("Wildflowers and the season",["Western Australia's wildflower season runs roughly August to November, moving south as the year progresses, and the south west is at its best in September and October. It is one of the largest wildflower displays on the planet.","Spring is also when the whales pass and the weather is mild, which makes it the single best window for this loop. Summer is hot and dry inland, though the coast stays pleasant.","Winter brings rain and cold to the south west, and while the forests are beautiful in it, camping is considerably less comfortable and some unsealed tracks become difficult."],["Wildflowers August to November","September and October are peak","Spring combines flowers and whales"]),section("Karri forests and the climbing trees",["The karri forests around Pemberton and Walpole hold some of the tallest hardwood trees in the world. The Valley of the Giants Tree Top Walk near Walpole is a suspended walkway forty metres up through the canopy.","The Gloucester Tree and Dave Evans Bicentennial Tree are climbable fire lookouts with metal spikes driven into the trunk and no safety harness. They are genuinely exposed and not for anyone uncertain about heights.","Beedelup Falls and the Karri Forest Explorer drive link the best of the forest country, and there are several campgrounds within it. Book through the WA parks system in peak season."],["Tree Top Walk at Walpole","Climbing trees have no harness","Book WA parks sites in spring"]),section("Margaret River and the coast",["Margaret River is the wine region but the coastline is the reason to camp here, with a string of surf breaks, limestone caves and the Cape to Cape track running 123 kilometres between the two lighthouses.","The caves at Jewel, Lake and Mammoth are separately ticketed and worth choosing between rather than doing all of them. Ngilgi Cave near Yallingup is the most accessible.","Cellar door tastings frequently charge a fee credited against purchase, and cycling between them is not practical here because the distances are larger than they look. Use a tour if you want to taste properly."],["Cape to Cape track is 123 km","Pick one or two caves","Wineries are too spread out to cycle"]),section("Sharks, rips and swimming safely",["The south west coast has genuine surf and strong rips, and many beaches are unpatrolled. Swim between the flags where they exist and, where they do not, be conservative about entering the water at all.","White sharks are present along this coast and there have been incidents. The practical response is to avoid dawn, dusk and murky water, avoid swimming alone, and follow any beach closure without argument.","Rip currents cause far more trouble than sharks. If caught in one, do not swim against it: swim parallel to the beach until you are out of the pull, or float and signal for help."],["Many beaches are unpatrolled","Avoid dawn, dusk and murky water","Swim parallel out of a rip"]),section("Albany and the south coast",["Albany has the National Anzac Centre, one of the better museums in the country, and the Gap and Natural Bridge on the granite coast nearby. The Torndirrup peninsula is exposed and spectacular.","Denmark and Walpole between Albany and Pemberton have the Valley of the Giants and Greens Pool, where granite boulders shelter a calm swimming area. This coast is cooler and wetter than the Margaret River side.","Fremantle and Rottnest Island bookend the loop at the Perth end, and Rottnest is a car-free day trip reached by ferry.","Wildflower timing shifts each year with rainfall, so check current reports rather than assuming a fixed date range when planning a spring trip."],["National Anzac Centre in Albany","Greens Pool is sheltered swimming","South coast is cooler and wetter"])]
  }),
  article({
    slug: "victoria-high-country-camping", title: "Victoria High Country camping road trip", description: "River camps, clear mountain air and winding roads beyond Bright and Omeo.", category: "Road trips", region: "Victoria High Country", readTime: 9,
    places: ["Bright", "Mount Buffalo National Park", "Harrietville", "Dinner Plain", "Omeo", "Howqua Hills"], imageAlt: "Mountain road in Victoria High Country", intro: "Victoria's High Country offers sealed touring, rough four-wheel-drive tracks and everything between. Build the route around the least capable vehicle in your group.",
    sections: [
      section("Bright and Mount Buffalo", ["Bright is the easiest place to fuel, shop and check the forecast. Mount Buffalo National Park adds granite views and booked camping at Lake Catani when open.", "Alpine nights can be cold in summer. Carry insulation and rain gear even when the valley forecast looks settled." ]),
      section("Harrietville to Omeo", ["The Great Alpine Road climbs through Harrietville and Dinner Plain before descending to Omeo. It is sealed, but weather, cyclists and sharp bends keep speeds low.", "Use a holiday park or established campground around Omeo before taking on more remote roads. Ask locally about closures and recent storm damage."], ["Harrietville", "Dinner Plain", "Omeo"]),
      section("River camps and seasonal roads", ["Howqua Hills and other river valleys can be popular, basic and vulnerable to flood or fire closures. Camp on durable ground and keep clear of riverbanks in rising weather.", "Many mountain tracks close seasonally. A closed gate is not an invitation to find a way around it."])
    ,section("Four-wheel drive tracks and seasonal closures",["The High Country's famous tracks, including Billy Goat Bluff and the Blue Rag Range, are four-wheel drive only, steep and often closed seasonally. Seasonal road closures typically run from the Queen's Birthday weekend in June to the Melbourne Cup weekend in November.","The sealed roads through Bright, Mount Beauty, Omeo and Dargo remain open year round and reach excellent camping without needing a four-wheel drive. Do not assume you need one to enjoy this region.","Check the Parks Victoria closure list before planning any track. Driving a closed seasonal road carries fines and does real damage to a surface that is closed precisely because it is fragile when wet."],["Seasonal closures June to November","Sealed roads reach good camping","Closed track fines are substantial"]),section("Rivers, huts and the cattlemen's history",["The high plains are dotted with historic cattlemen's huts, many maintained by volunteer associations. They are emergency shelter rather than accommodation, and the convention is to leave them stocked, swept and available.","The Mitta Mitta, Ovens and Howqua rivers all have excellent riverside camping, much of it free and first come. These fill fast over long weekends and summer, and the access tracks vary in difficulty.","Craig's Hut on the Mount Stirling road is the best known, rebuilt after fires and reached by a moderate drive. It is worth the detour for the view across the ranges alone."],["Huts are shelter, not accommodation","River sites fill on long weekends","Craig's Hut for the view"]),section("Alpine weather and fire risk",["Snow falls on the high plains from roughly June to September and can occur outside those months. Even in summer, alpine nights are cold and weather changes fast, so carry warm layers regardless of the forecast in Bright.","Summer brings serious bushfire risk to this country, and the High Country has burnt repeatedly. Check fire danger ratings daily, understand that campgrounds in forest are poor places to shelter, and leave early on bad days.","Total fire bans are common through summer and prohibit all open flame including solid fuel barbecues. Carry a gas cooker, which is generally still permitted, and check the specific ban conditions."],["Cold alpine nights year round","Check fire ratings daily in summer","Gas cooker for total fire ban days"]),section("Bright, Beechworth and the rail trails",["Bright is the natural base with services, breweries and the Murray to Mountains Rail Trail, a sealed cycle path running to Beechworth and Wangaratta. Bike hire is straightforward and the trail suits all abilities.","Autumn is Bright's season, with European deciduous trees turning through April and May and the Autumn Festival drawing crowds. Book accommodation well ahead for that window.","Beechworth is a well preserved gold rush town with the Ned Kelly history, and Milawa nearby has the food and wine. Together they make an easy two-day loop off the alpine roads."],["Rail trail suits all abilities","Autumn colour through April and May","Beechworth for gold rush history"]),section("Fly fishing and the rivers",["The Mitta Mitta, Howqua, Delatite and King rivers hold trout and the region is one of Australia's best fly fishing areas. A Victorian recreational fishing licence is required and easily bought online.","Closed seasons apply to some waters to protect spawning, generally over winter. Check the current rules for the specific river before fishing, because they differ between waters.","Mount Buffalo is the accessible alpine option with sealed road access to the plateau, granite tors and walks suitable for most people.","Seasonal road closures are published annually by Parks Victoria, and the dates shift slightly each year with conditions, so confirm before planning an alpine track."],["Fishing licence required in Victoria","Closed seasons protect spawning","Check rules per river"])]
  }),
  article({
    slug: "flinders-ranges-camping-guide", title: "Flinders Ranges camping guide", description: "Ancient folded ranges, dry creek beds and campfire-coloured evenings around Ikara.", category: "Road trips", region: "South Australia", readTime: 9,
    places: ["Hawker", "Wilpena Pound Resort", "Ikara-Flinders Ranges National Park", "Brachina Gorge", "Parachilna", "Arkaroola"], imageAlt: "Ikara-Flinders Ranges at sunset", intro: "The Flinders Ranges are easiest from April to October. Use Hawker or Wilpena as a base, then decide whether the rougher northern roads fit your vehicle and experience.",
    sections: [
      section("Hawker and Ikara", ["Hawker is the practical gateway for fuel, food and local road advice. Inside Ikara-Flinders Ranges National Park, choose a booked campground that matches your setup and walking plans.", "Start ridge and pound walks early. Carry water and respect cultural guidance around Ikara and other significant places." ]),
      section("Brachina and Bunyeroo", ["The gorge roads reveal geology and wildlife at a slower pace. Conditions change after rain and creek crossings can close, so check with the park before entering.", "Yellow-footed rock-wallabies are best watched quietly from a distance. Do not feed wildlife or crowd a sighting with vehicles."], ["Brachina Gorge", "Bunyeroo Gorge", "Wilpena Pound"]),
      section("North to Parachilna and Arkaroola", ["Parachilna provides a memorable pub stop before the road pushes farther north. Arkaroola is remote, with private accommodation and activities that benefit from advance booking.", "Fuel range, tyres and heat matter more beyond the central park. Turn back early if the road or vehicle is not right."])
    ,section("Wilpena Pound and the walks",["Wilpena Pound is a natural amphitheatre roughly seventeen kilometres long, and the walks range from the easy Wangara Lookout to the demanding St Mary Peak, which is the highest point in the ranges at 1,171 metres.","St Mary Peak is a serious six to eight hour day with scrambling near the summit. Adnyamathanha Traditional Owners ask visitors not to climb to the summit itself for cultural reasons, and the outside route to Tanderra Saddle is the respectful alternative.","Start early in any season. Summer temperatures here exceed forty degrees and walks become genuinely dangerous, with rangers closing tracks on extreme days."],["Traditional Owners ask you not to summit St Mary Peak","Start walks at first light","Tracks close on extreme heat days"]),section("When to visit",["Autumn and spring are the seasons here. April to May and August to October give comfortable temperatures for walking and, after winter rain, the wildflower displays through the ranges can be exceptional.","Summer is severe, with sustained heat above forty degrees and real risk on any walk. Winter is cold at night with occasional frost but pleasant for walking during the day, and the country is green.","The ranges are also excellent for stargazing, with almost no light pollution. Clear winter nights are the best of the year for it."],["Autumn and spring are best","Summer is genuinely dangerous","Winter nights are best for stars"]),section("Roads, fuel and the northern ranges",["The sealed road reaches Wilpena via Hawker, and beyond that the Flinders becomes unsealed. Brachina Gorge, Bunyeroo and the Moralana Scenic Drive are usually accessible in a two-wheel drive when dry but close after rain.","Fuel is available at Hawker, Wilpena, Blinman and Parachilna, and the gaps are meaningful. Fill up whenever you pass one rather than planning to reach the next.","Further north into Arkaroola and the Gammon Ranges the country becomes genuinely remote and four-wheel drive territory. That is a different trip requiring more preparation than the southern ranges."],["Unsealed roads close after rain","Fuel at Hawker, Wilpena, Blinman","Arkaroola needs 4WD and preparation"]),section("Geology and Adnyamathanha country",["The Flinders exposes some of the oldest visible geology on Earth, including Ediacaran fossils that record early complex life. The Brachina Gorge Geological Trail is a self-guided drive through 130 million years of rock.","This is Adnyamathanha country and the ranges carry creation stories that explain the landscape, including the Pound itself. Guided walks with Adnyamathanha guides are available and transform the visit.","Yellow-footed rock wallabies were nearly lost here and have recovered through predator control. They are most visible around Brachina Gorge in the early morning and late afternoon."],["Ediacaran fossils in the gorges","Adnyamathanha guided walks","Rock wallabies at Brachina early"]),section("Where to stay in the ranges",["Wilpena Pound Resort has powered sites and a shop, and the Ikara-Flinders Ranges National Park has campgrounds along Brachina and Bunyeroo with no facilities. Rawnsley Park and Willow Springs are private station options.","Book Wilpena in school holidays and long weekends. The bush campgrounds are first come and rarely full outside those windows, but they have no water, so carry everything you need.","Quorn and Hawker at the southern end have the Pichi Richi railway and good bakeries, and both work as the last restock before the ranges.","Summer here is severe enough that walks close on high temperature days, and the ranges are far better visited in autumn, winter or spring."],["Bush campgrounds have no water","Book Wilpena for holidays","Station stays are a good alternative"])]
  }),
  article({
    slug: "red-centre-way-camping", title: "Red Centre Way camping route", description: "Desert waterholes, red walls and long sunsets between Alice Springs and Uluṟu.", category: "Road trips", region: "Northern Territory Outback", readTime: 10,
    places: ["Alice Springs", "Ormiston Gorge Campground", "Tjoritja", "Kings Canyon Resort", "Curtin Springs", "Uluṟu"], imageAlt: "Red Centre gorge and desert road", intro: "The Red Centre Way links Alice Springs, Tjoritja, Kings Canyon and Uluṟu. Sealed and unsealed options differ, so the route must match the vehicle rather than the line on a map.",
    sections: [
      section("Alice Springs to Tjoritja", ["Stock water, food and fuel in Alice Springs, then drive west through Tjoritja. Ormiston Gorge and other designated campgrounds make strong bases for early walks.", "A visitor pass or campground booking may be required. Keep footwear on around camp and check waterhole safety advice locally." ]),
      section("Kings Canyon", ["Choose the sealed route unless your vehicle, rental terms and current road advice support an unsealed alternative. Kings Canyon Resort provides the main nearby facilities.", "Start the Rim Walk early and obey heat closures. Carry enough water for the full route rather than relying on how cool sunrise feels."], ["Ormiston Gorge Campground", "Kings Canyon Resort", "Curtin Springs"]),
      section("Uluṟu and the return", ["Curtin Springs can break the journey before Yulara. Around Uluṟu, follow Anangu requests, park rules and photography guidance.", "Do not squeeze sunrise, a long walk and a major onward drive into one day. Desert fatigue is still fatigue."])
    ,section("The loop and its unsealed section",["The Red Centre Way links Alice Springs, the West MacDonnell Ranges, Kings Canyon and Uluru. The Mereenie Loop Road between Glen Helen and Kings Canyon is unsealed, requires a permit, and is prohibited in most standard hire agreements.","The sealed alternative runs back through Alice and down the Stuart Highway, adding distance but keeping you on bitumen. Decide which you are doing before hiring the vehicle, not after.","The Mereenie permit is inexpensive and available from visitor centres. It exists because the road crosses Aboriginal land, and camping along it is not permitted."],["Mereenie Loop needs a permit","Most rentals prohibit it","No camping along the Mereenie"]),section("The West MacDonnells are underrated",["Ormiston Gorge, Ellery Creek Big Hole, Standley Chasm and Simpsons Gap are all within easy reach of Alice on sealed roads, and several have swimming. Ormiston in particular is one of the best gorges in the country.","The water in these gorges is snowmelt-cold year round because it sits in permanent shade. Swimming is a shock even in forty degree heat, and people have got into trouble misjudging it.","The Larapinta Trail runs 223 kilometres through this country and individual sections make excellent day walks from the road. Section three from Standley Chasm is a good sample."],["Gorge water is cold year round","Ormiston is the standout","Larapinta sections make day walks"]),section("Heat, water and walking safely",["Central Australian summer regularly exceeds forty degrees and walks are dangerous in it. Rangers close tracks when forecasts pass thresholds, and the Larapinta is effectively a winter trail.","Carry at least four litres of water per person for any walk and more in heat. Start at first light and be finished by mid-morning in summer. Dehydration here develops faster than most visitors expect.","Winter, from May to August, is the season: warm days, cold nights that can drop below freezing, and clear skies. Pack for both ends of that range because the diurnal swing is large."],["Four litres per person per walk","Winter nights drop below freezing","Be finished walking by mid-morning"]),section("Alice Springs as a base",["Alice has the services, supermarkets, mechanics and hospital that nothing else out here does. Restock properly before heading out on any leg, and deal with vehicle issues here rather than hoping.","The Alice Springs Desert Park and the Royal Flying Doctor Service base both explain the country and how people live in it, and both are worth half a day. The Telegraph Station explains why the town exists at all.","Fuel prices rise sharply once you leave. Fill in Alice, and again at Erldunda or Curtin Springs, and treat every roadhouse as a top-up rather than a decision."],["Restock and repair in Alice","Fuel rises sharply outside town","Desert Park explains the country"]),section("Alice Springs and the desert parks",["The East MacDonnell Ranges east of Alice are quieter than the west and include Trephina Gorge and the historic Arltunga goldfields. They are frequently overlooked entirely.","Both ranges have basic national park campgrounds requiring a Parks and Wildlife pass. Fees are low, facilities are minimal and most sites are first come outside peak season.","Consider the Larapinta Trail as a reason to return, since individual sections make excellent multi-day walks with vehicle support available.","Winter nights in central Australia drop below freezing while days stay warm, so pack for a genuinely large temperature swing rather than a single climate."],["East MacDonnells are much quieter","NT parks pass required","Facilities are minimal"])]
  }),
  article({
    slug: "kangaroo-island-camping-guide", title: "Kangaroo Island camping guide", description: "Wild beaches, slow roads and wildlife-filled evenings beyond the ferry at Penneshaw.", category: "Road trips", region: "South Australia Coast", readTime: 9,
    places: ["Penneshaw", "Kingscote", "American River", "Flinders Chase National Park", "Vivonne Bay", "Stokes Bay"], imageAlt: "Rocky coast on Kangaroo Island", intro: "Kangaroo Island is larger and slower than many first visits allow. Four or five nights gives the west end, south coast and quieter northern beaches enough room.",
    sections: [
      section("Ferry and first night", ["Reserve the vehicle ferry and arrive with enough time for check-in. Penneshaw is an easy first night, while American River or Kingscote provides more groceries and services.", "Check what food and plant material can be taken to the island. Biosecurity protects local agriculture and wildlife." ]),
      section("Flinders Chase and the south coast", ["Drive to Flinders Chase in daylight. Wildlife is active near the road and distances take longer than expected. Park entry and campground bookings are separate checks.", "Vivonne Bay works as a central south-coast base. Wind and surf change quickly, so read local swimming advice before entering the water."], ["Flinders Chase National Park", "Vivonne Bay", "Kingscote"]),
      section("North coast and the return", ["Stokes Bay and the north coast reward a slow day. Carry food and water away from the main towns, then refuel before the ferry rather than arriving on fumes.", "Leave a generous buffer for the drive back to Penneshaw. A missed ferry is an expensive way to learn how slow island roads can be."])
    ,section("Getting there and the ferry",["The SeaLink ferry runs from Cape Jervis to Penneshaw, takes about 45 minutes and carries vehicles. Fares are set by vehicle length and the crossing books out over summer and school holidays, so reserve well ahead.","Taking your own vehicle is usually better value than hiring on the island, where the fleet is small and prices reflect that. Fuel on the island is also more expensive, so arrive with a full tank.","The island is larger than most visitors expect at around 155 kilometres end to end, with many unsealed roads. Three days is a realistic minimum and four is better."],["Ferry priced by vehicle length","Fill up before crossing","155 km end to end, allow 3 to 4 days"]),section("Recovering from the 2020 fires",["The 2019 to 2020 bushfires burnt roughly half the island, including much of Flinders Chase National Park. Regeneration is well advanced and the landscape is genuinely interesting to see recovering, but some facilities and tracks remain altered.","Check current park status and track openings before planning specific walks. Flinders Chase facilities have been progressively rebuilt and the situation has changed several times since the fires.","The eastern end of the island was largely unburnt and holds much of the wildlife viewing, including Seal Bay and the penguin colonies. Plan around what is open rather than what a pre-2020 guidebook describes."],["Half the island burnt in 2020","Check park and track status","Eastern end was largely unburnt"]),section("Wildlife and how to see it responsibly",["Seal Bay allows a guided beach walk among wild Australian sea lions, one of the few places anywhere this is possible. Bookings are required and the boardwalk option is available without a guide.","Kangaroo Island has a distinct kangaroo subspecies, plus koalas, echidnas and a population of Ligurian honeybees that is the last pure strain in the world. Because of that, importing honey or used beekeeping equipment is prohibited.","Wildlife on roads is the main hazard here. Do not drive after dark: the roadkill rate is high, many roads are unsealed and unlit, and animal strikes are the most common way visitors damage vehicles."],["Book Seal Bay guided walks","No honey imports to the island","Do not drive after dark"]),section("Camping and the food",["National park campgrounds in Flinders Chase and along the coast are booked through the South Australian parks system and fill in peak season. There are also commercial parks at Penneshaw, Kingscote and American River.","The island produces excellent food: sheep dairy, honey, gin, marron and seafood, with several producers open for tastings. It is one of the better places in the country to eat well from a camp kitchen.","Fresh produce cannot be brought onto the island under South Australian quarantine rules in some circumstances, so check before loading the vehicle in Adelaide."],["Book SA parks campgrounds ahead","Excellent local produce","Check quarantine before loading up"]),section("Remarkable Rocks and the west end",["Remarkable Rocks and Admirals Arch sit at the western end in Flinders Chase and are the island's signature landscapes. Both are exposed, and the rocks are slippery and unfenced above a considerable drop.","The west end is roughly two hours from the ferry, which makes it a full day out and a strong argument for camping at that end rather than driving back and forth from Penneshaw.","Kingscote and American River on the eastern side have the services and the calmest water, and both are considerably closer to the ferry than Flinders Chase.","Ferry sailings book out over summer and school holidays, and a missed crossing on an island itinerary costs a full day rather than an hour."],["Remarkable Rocks are slippery and unfenced","Two hours from the ferry","Camp at the west end"])]
  }),
  article({
    slug: "blue-mountains-camping-weekend", title: "Blue Mountains camping weekend from Sydney", description: "Two nights of sandstone lookouts, eucalypt valleys and cold air close to Sydney.", category: "Road trips", region: "NSW", readTime: 7,
    places: ["Katoomba", "Blackheath", "Euroka Campground", "Murphys Glen Campground", "Lithgow"], imageAlt: "Blue Mountains sandstone valley", intro: "A Blue Mountains camping weekend works when the first night is simple and the driving stops before Friday fatigue takes over.",
    sections: [
      section("Friday evening", ["For a late departure, use a booked caravan park or campground with clear after-hours arrival instructions. Do not navigate an unfamiliar forest road in darkness just to save an hour in the morning.", "Katoomba, Blackheath and Lithgow provide food and fuel. Temperatures can be much lower than Sydney, especially in exposed or high camps." ]),
      section("Saturday in the park", ["Choose one walking area rather than crossing the mountains between lookouts. Blackheath suits Grose Valley views, while Katoomba and Wentworth Falls offer classic cliff walks.", "Euroka and Murphys Glen can suit different vehicles and conditions. Check booking, access, fire and water information before leaving sealed roads."], ["Blackheath", "Euroka Campground", "Murphys Glen Campground"]),
      section("Sunday without the rush", ["Pack camp before the main walk if rain is due. A dry tent in the vehicle makes the trip home much easier.", "Return before the late-afternoon motorway queue or stop for an early meal. Wildlife and tired walkers share the roads near dusk."])
    ,section("It is a valley system, not a mountain range",["The Blue Mountains are a dissected plateau, which means the walks mostly go down first and climb back at the end when you are tired. The Grand Canyon and National Pass tracks both work this way and catch people out.","The Three Sisters at Echo Point is the famous view and the busiest spot. Sublime Point, Govetts Leap and Evans Lookout give comparable views with a fraction of the people, and are worth the short drives.","Katoomba is under two hours from Sydney, which makes this the standard Sydney weekend and means campgrounds and accommodation fill from Friday evening."],["Walks descend first, climb last","Govetts Leap beats Echo Point for crowds","Under two hours from Sydney"]),section("Where to camp",["Blue Mountains National Park has campgrounds at Euroka, Ingar, Murphys Glen and Perrys Lookdown, most requiring booking through NSW National Parks. Euroka is the most accessible and known for kangaroos.","Vehicle entry fees apply to parts of the park separately from camping fees. The Glenbrook entrance in particular has gate hours, so check closing time before planning a late arrival.","Several campgrounds are two-wheel drive accessible but a few require high clearance, particularly after rain. Check the specific site rather than assuming."],["Book NSW parks campgrounds","Glenbrook gate has closing hours","Some sites need high clearance"]),section("Canyoning, climbing and safety",["The Blue Mountains are a major canyoning destination and the slot canyons here are world class. They are also cold, technical and require abseiling skills, wetsuits and proper equipment. Guided trips are the sensible entry point.","Flash flooding is the specific hazard. Never enter a canyon if rain is forecast anywhere in the catchment, and understand that rain kilometres away can fill a slot canyon with no warning at the entrance.","On the walking tracks, the cliff edges are largely unfenced and the sandstone crumbles. Stay back from edges, particularly when wet, and do not step past barriers for a photograph."],["Canyons flash flood without warning","Guided trips for first-timers","Sandstone edges crumble"]),section("Weather and bushfire",["The mountains are consistently around eight degrees cooler than Sydney and can be genuinely cold, with snow occasionally falling in winter. Visitors regularly arrive underdressed after a warm morning on the coast.","Bushfire risk is severe in summer and the area has burnt repeatedly, including catastrophically in 2019 to 2020. Check fire danger ratings daily and have a plan to leave early rather than shelter.","Winter is arguably the best season here: clear air, long views, comfortable walking temperatures and Yulefest, where the mountain towns run midwinter Christmas dinners."],["Eight degrees cooler than Sydney","Severe summer fire risk","Winter is excellent for walking"]),section("Jenolan Caves and the western side",["Jenolan Caves sit beyond Katoomba and hold some of the oldest open cave systems in the world. Access roads have been affected by landslips in recent years, so check the current route before driving out.","Tours book ahead and range from easy walkthroughs to adventure caving. The drive in is steep and winding and unsuitable for large vehicles or caravans.","Wentworth Falls and Leura are quieter bases than Katoomba with the same access to the escarpment walks and better food.","Summer bushfire risk is severe here and the area has burnt repeatedly, so check the fire danger rating before committing to a night in forested camping."],["Check access roads before driving","Book cave tours ahead","Road unsuitable for caravans"])]
  }),
  article({
    slug: "australian-alps-camping-route", title: "Australian Alps camping route", description: "High plains, Snowy River camps and the winding mountain road from Jindabyne to Bright.", category: "Road trips", region: "Australian Alps", readTime: 10,
    places: ["Jindabyne", "Kosciuszko National Park", "Geehi Flats Campground", "Omeo", "Dinner Plain", "Bright"], imageAlt: "Australian Alps high country", intro: "Jindabyne to Bright crosses national parks, river valleys and high roads. Travel after seasonal roads open and keep an alternative ready for sudden alpine weather.",
    sections: [
      section("Jindabyne and Kosciuszko", ["Jindabyne is the resupply point for Kosciuszko National Park. Check park entry, campground bookings and road conditions before heading toward Thredbo, Charlotte Pass or Geehi.", "Cold wind and fast storms are normal alpine risks. Carry layers, rain protection and a turnaround time on every walk." ]),
      section("Geehi to Omeo", ["Geehi Flats offers river camping when open and conditions are suitable. Keep a safe distance from the water in wet weather and store food securely.", "The road toward Omeo is scenic and demanding. Fuel before the remote section, expect limited reception and stop early if fog or fatigue arrives."], ["Geehi Flats Campground", "Omeo", "Dinner Plain"]),
      section("Dinner Plain and Bright", ["Dinner Plain provides a high-country break before the descent to Harrietville and Bright. Even in summer, nights can be cold.", "Bright has holiday parks, repairs and an easy finish. Seasonal closures can reshape the entire route, so confirm them before departure, not at the gate."])
    ,section("The Alpine Way and the road network",["The Alpine Way between Khancoban and Jindabyne is the spine of this route, sealed and open year round but requiring wheel chains to be carried in winter within the national park regardless of conditions.","Kosciuszko National Park charges vehicle entry, higher in the ski season. The pass is per vehicle per day and an annual option exists if you are visiting repeatedly.","The Barry Way south to Victoria and several other connecting roads are unsealed, steep and seasonally closed. Check status before planning a crossing between states through the park."],["Chains required in winter, always carried","Park entry fee applies","Connecting roads close seasonally"]),section("Climbing Kosciuszko",["Australia's highest point at 2,228 metres is reached either from Thredbo via the chairlift and a 13 kilometre return walk on raised steel mesh, or from Charlotte Pass on a longer 18 kilometre return route.","The Thredbo route is the easy option and genuinely accessible for most people in summer. Neither route is technical, but both are fully exposed alpine terrain with no shelter and weather that changes fast.","In winter both become serious snow routes requiring navigation, avalanche awareness and proper equipment. People die on this mountain in winter, most often after underestimating a walk that is easy in January."],["13 km return from Thredbo","No shelter on either route","Winter is a serious mountaineering trip"]),section("Camping in the alpine country",["Kosciuszko has campgrounds at Thredbo Diggings, Island Bend, Geehi and Tom Groggin among others, most first come and basic. They fill over summer and long weekends and are cold at night in any season.","Above the treeline, camping is restricted to protect fragile alpine vegetation and water catchments, with minimum distances from lakes and roads. Read the park rules rather than assuming a flat spot is available.","Fires are prohibited across large parts of the park including above the treeline, and total fire bans are common in summer. Carry a gas cooker and check the current restrictions."],["Alpine camping is restricted above treeline","Sites are basic and cold","Fires prohibited in much of the park"]),section("Brumbies, huts and the season",["The high country huts are historic shelters maintained by volunteers, available as emergency refuge rather than accommodation. Leave them clean, close the doors properly and restock any wood.","Wild horses are present in the park and are a contentious management issue. They are large, unpredictable animals: do not approach or feed them, and take particular care driving at dawn and dusk.","Summer, from December to March, gives wildflowers on the high plains and comfortable walking. Winter is the ski season with a completely different set of requirements, costs and road conditions."],["Huts are emergency shelter","Do not approach brumbies","Summer wildflowers December to March"]),section("The Snowy scheme and the valleys",["The Snowy Mountains Scheme shaped this country and the visitor centre at Cooma and the Tumut area explain it. Lake Jindabyne and Lake Eucumbene are both products of it and both have lakeside camping.","Yarrangobilly Caves in the north of Kosciuszko has a thermal pool at twenty seven degrees year round, which is an excellent stop after a cold night on the high plains.","Bright and Mount Beauty on the Victorian side connect this route to the High Country, making a longer alpine loop across both states possible.","Wheel chains must be carried within Kosciuszko in winter regardless of the forecast, and the requirement is enforced at park entry points."],["Yarrangobilly has a thermal pool","Lake camping at Jindabyne and Eucumbene","Snowy scheme shaped the region"])]
  }),
  article({
    slug: "gibb-river-road-camping", title: "Gibb River Road camping guide", description: "Red dirt, deep gorges and station stays across the wild heart of the Kimberley.", category: "Road trips", region: "Kimberley", readTime: 11,
    places: ["Derby", "Windjana Gorge", "Mount Barnett Roadhouse", "Manning Gorge", "El Questro", "Kununurra"], imageAlt: "Red dirt road through the Kimberley", intro: "The Gibb River Road is a remote journey through changing conditions, not a guaranteed dry-season highway. Vehicle preparation and current local advice decide whether the trip should proceed.",
    sections: [
      section("Prepare in Derby", ["Service the vehicle, inspect tyres and carry the equipment needed to change one safely. Confirm road opening, fuel availability and accommodation before leaving Derby.", "Rental agreements often restrict the Gibb or its side tracks. Written permission matters more than a verbal assumption at the counter."], ["Two sound spare tyres where recommended", "Tyre repair equipment", "Water reserve", "Emergency communication"]),
      section("Gorges and station stays", ["Windjana Gorge, Mount Barnett and Manning Gorge divide the road into meaningful stops. Station and roadhouse arrangements vary, including fuel hours, camping fees and cash or card availability.", "Drive to conditions. Corrugations, creek crossings, dust and sharp stones can change within a day, and speed turns manageable damage into a stranded vehicle." ]),
      section("El Questro to Kununurra", ["The eastern end becomes busier around El Questro. Book popular stays and confirm whether side tracks suit your clearance and experience.", "Reach Kununurra with time to inspect the vehicle before the next leg. Heat, fatigue and small mechanical problems accumulate across the Gibb."])
    ,section("This is a serious four-wheel drive route",["The Gibb River Road runs roughly 660 kilometres between Derby and Kununurra, is largely unsealed, heavily corrugated, and includes river crossings. It requires a high-clearance four-wheel drive and is prohibited under almost every standard hire agreement.","Two spare tyres, tyre repair equipment, a compressor and the knowledge to use them are standard rather than optional. Tyre damage is the single most common problem and recovery costs here are substantial.","Specialist four-wheel drive hire companies in Broome and Darwin permit the Gibb and include the necessary equipment. Using one of those is the practical route for visitors without their own vehicle."],["660 km, mostly unsealed","Two spares and a compressor","Standard rentals are prohibited"]),section("The dry season is the only season",["The road closes in the wet, roughly November to April, when river crossings become impassable and the surface is destroyed by traffic. It typically reopens around May and closes again around October.","Even within the dry, early season crossings can be deep and late season corrugations are at their worst. June to August is the reliable window with the road graded and the gorges full.","Check the road status with Main Roads WA before setting out and again along the way. Sections close independently and a closure partway is a genuine problem given the distances involved."],["Closed roughly November to April","June to August is the window","Check Main Roads WA status"]),section("The gorges are the reason",["Windjana, Bell, Galvans, Adcock, Manning and Emma gorges run along the route, most with swimming and several with waterfalls into deep pools. El Questro at the eastern end holds Zebedee thermal springs and Emma Gorge.","Windjana Gorge has freshwater crocodiles basking on the sand, which are generally harmless if left well alone. Estuarine crocodiles are present in some waterways in this region, so follow the signage at every swimming hole.","Most gorges involve a walk in over rock, sometimes scrambling, and the heat is severe. Start early, carry far more water than the distance suggests and do not attempt the longer gorge walks in the middle of the day."],["Freshwater crocs at Windjana","Follow signage at every swimming hole","Walk the gorges early"]),section("Fuel, supplies and communication",["Fuel is available at Imintji, Mount Barnett, Drysdale River and El Questro, at high prices and sometimes with limited hours. The gaps require genuine range planning and carrying additional fuel is common.","There is no mobile coverage across most of the route. A satellite phone or a personal locator beacon is not optional equipment here, and telling someone your route and expected arrival is basic practice.","Stock food and water for longer than the plan. A breakdown or a closed crossing can add days, and the stations along the route are not shops in any conventional sense."],["Fuel at four points, high prices","No mobile coverage, carry a PLB","Stock for longer than planned"]),section("Station stays along the road",["Several pastoral stations along the Gibb offer camping, meals and fuel, including Mount Elizabeth, Drysdale River and Home Valley. They are the accommodation network for this route and often the only option.","Most take cash and have limited or no online booking, and phone contact may only be possible by satellite. Plan on arriving rather than reserving, and carry cash for fuel and fees.","Allow at least seven days for the road itself, and more if you intend to include the Mitchell Falls detour, which is rough and adds several days.","Check the road status with Main Roads before departure and again along the way, because sections close independently and a closure partway is a serious problem out here."],["Stations are the accommodation network","Carry cash for fuel and fees","Booking is often not possible"])]
  }),
  article({
    slug: "sunshine-coast-hinterland-camping", title: "Sunshine Coast and hinterland camping loop", description: "Saltwater mornings and cool rainforest nights in one easy loop north of Brisbane.", category: "Road trips", region: "Queensland Coast", readTime: 8,
    places: ["Noosa North Shore", "Kenilworth", "Conondale National Park", "Mapleton", "Glass House Mountains", "Caloundra"], imageAlt: "Sunshine Coast hinterland forest", intro: "A four-day loop can pair the Sunshine Coast with the Blackall Range and Mary Valley, swapping beach crowds for cool forest whenever the weather turns.",
    sections: [
      section("Coast to Mary Valley", ["Start around Caloundra or Noosa, then turn inland before the coast traffic steals the day. Noosa North Shore has special access considerations, including ferry and sand-driving conditions.", "Kenilworth offers food, a river-town base and several commercial camping options. Confirm flood risk and ground conditions after heavy rain." ]),
      section("Conondale and the range", ["Conondale National Park and nearby forests bring simple camps, walking and cooler nights. Roads can be narrow or unsealed, so check access for caravans and low-clearance vehicles.", "Mapleton, Montville and the Blackall Range provide caravan parks and roofed stays when a wet tent no longer feels romantic."], ["Kenilworth", "Conondale National Park", "Mapleton"]),
      section("Glass House Mountains return", ["Finish through the Glass House Mountains and keep walks within signed access. Some steep routes require scrambling experience and dry conditions.", "Return to Brisbane before Sunday traffic builds, or add a final powered night around Caloundra and leave early Monday."])
    ,section("Coast and hinterland are two different trips",["The coastal strip from Caloundra to Noosa is beaches, surf and holiday parks, busy and well serviced. The hinterland behind it, through Maleny, Montville and the Glass House Mountains, is rainforest, waterfalls and small towns twenty minutes inland.","Doing both is what makes the loop worthwhile, and they suit different weather. Keep the hinterland for a day when the beach is blown out, because the rainforest walks are better in cloud anyway.","The whole area is compact enough that you can base in one place and day trip. Noosa or Maleny both work as a single base for four or five days."],["Hinterland is 20 minutes inland","Rainforest is better in cloud","One base covers the whole loop"]),section("Noosa National Park and the headland",["The coastal track around Noosa headland is the standout walk, passing Tea Tree Bay and Hells Gates with a genuine chance of wild koalas in the trees along the way. It is flat, accessible and can be done in sections.","Parking at the entrance fills by mid-morning in peak season and the shuttle or a walk from Hastings Street is the practical alternative. Go early for both parking and wildlife.","The park has no camping. Accommodation is in Noosa itself, which is expensive, or the holiday parks at Noosaville and Tewantin which are considerably better value."],["Koalas along the coastal track","Parking fills by mid-morning","No camping in Noosa National Park"]),section("The Glass House Mountains",["These volcanic plugs rise abruptly out of flat country and several can be climbed, with Mount Ngungun the accessible option at around an hour return and Mount Beerwah a genuinely steep scramble.","Mount Tibrogargan and Mount Beerwah both carry cultural significance and specific safety warnings, and there have been fatalities on Tibrogargan. Read the track signage and be honest about your scrambling ability.","The lookout on the Glass House Mountains Road gives the classic view without any climbing, and it is best in the early morning before haze builds."],["Ngungun is the accessible climb","Beerwah and Tibrogargan are serious","Lookout gives the view without climbing"]),section("Waterfalls, markets and the wet season",["Kondalilla and Mapleton Falls both have short walks with swimming at Kondalilla, and Gardners Falls near Maleny is a local favourite that stays cool through summer. All run best after rain.","Eumundi Markets on Wednesday and Saturday mornings are among the best known in the country and worth planning a day around. Maleny and Montville have the food and craft side of the hinterland.","Summer here is hot, humid and the wet season brings heavy afternoon storms. Autumn and winter are drier, more comfortable for walking and still warm enough to swim on the coast."],["Eumundi Markets Wednesday and Saturday","Waterfalls run best after rain","Autumn and winter are most comfortable"]),section("Beaches and the surf",["Coolum, Peregian, Marcoola and Mooloolaba give a run of patrolled beaches with easier parking than Noosa. Swimming between the flags matters here because the surf is real and rips are common.","The Noosa Everglades, reached by boat or kayak from Boreen Point, is one of only two everglade systems in the world and considerably quieter than the coastal strip.","Rainbow Beach and the Cooloola section to the north extend the trip towards K'gari, and the coloured sands are worth the drive on their own.","Summer storms build quickly through the afternoon in this region, so plan walks for the morning and expect the hinterland roads to be slick afterwards."],["Swim between the flags","Noosa Everglades are quiet","Coolum parks more easily than Noosa"])]
  }),

  article({ slug:"camping-rules-new-south-wales", title:"Camping rules in New South Wales", description:"Bookings, designated sites, remote camps and fire checks before a night in NSW.", category:"Rules & safety", region:"New South Wales", readTime:8, places:["Myall Lakes","Kosciuszko National Park","Murramarang National Park"], imageAlt:"National park campground in New South Wales", intro:"NSW camping rules depend on who manages the land. National parks, state forests, councils and private campgrounds each set their own conditions.", sections:[section("National park campgrounds",["NSW National Parks requires advance bookings for listed campgrounds and hard-roof accommodation. Keep the confirmation available and enter the correct party and vehicle details.","Remote camping is allowed only in specific areas. A trip intention form may be recommended even where a standard campground booking is not used."]),section("Free and roadside camping",["A rest area is not automatically a campground. Read parking limits and council signs, keep truck bays clear and do not set up awnings or furniture where only a fatigue stop is intended.","Council reserves and showgrounds can have local permits, time limits or closures. Confirm them on the day."], ["Read signs on arrival","Keep access roads clear","Leave no wastewater"]),section("Fire and park alerts",["Check NSW park alerts, fire danger ratings and total fire bans before departure. A supplied fireplace does not make a fire legal during a ban.","Conditions can close parks with little notice. Keep a legal backup outside the affected area."]),section("Who manages the land you are on",["NSW splits camping between National Parks and Wildlife Service reserves, State Forests, Crown land, local council reserves and private property. Each has its own booking system, fees and rules, and the boundaries are frequently invisible from the road.","NPWS campgrounds are booked online and most charge both a camping fee and a separate vehicle entry fee for the park. State Forests are generally free and far less regulated, which makes them the practical option for dispersed camping.","Council reserves vary enormously between local government areas. A rest area that permits overnight stays in one shire will be prohibited in the next, and the signage is the only reliable guide."],["NPWS charges camping plus park entry","State Forests are mostly free","Council rules change at every boundary"]),section("Booking NPWS campgrounds",["Popular coastal and mountain campgrounds book out months ahead for summer, Easter and school holidays, and walk-up availability is rare in those windows. Outside them, most sites can be booked a few days out.","An All Parks Pass covers vehicle entry to most NSW parks for a year and pays for itself quickly if you are visiting more than a handful. It does not cover camping fees or the Sydney Harbour and Kosciuszko parks in all cases.","Bookings are per site with a stated maximum occupancy and vehicle count. Turning up with more people or vehicles than booked is a common cause of trouble at busy grounds."],["Book months ahead for summer","All Parks Pass covers entry only","Occupancy limits are enforced"]),section("Fires and total fire bans",["The NSW bush fire danger period usually runs from October to March and varies by local government area. During it, a permit is needed for most open fires, and on total fire ban days no open flame is allowed at all.","Solid fuel barbecues and campfires are prohibited on total fire ban days. Gas appliances are generally permitted subject to conditions, but check the specific ban wording because it changes.","Many NPWS campgrounds prohibit fires permanently regardless of the season. Check the individual campground page rather than assuming the state-wide position applies."],["Fire danger period October to March","No solid fuel on ban days","Many campgrounds ban fires always"]),section("Free camping and rest areas",["Transport for NSW rest areas are provided for driver fatigue management and many permit a stay of up to 24 hours, but they are not campgrounds and setting up awnings and chairs is not the intent.","Genuine free camping is most reliably found in State Forests, on some Crown land, and at council-designated sites, several of which ask for a small donation to the local community.","Enforcement varies but is real in coastal councils and popular areas. Fines apply for camping in prohibited areas, and the infringement attaches to the vehicle, so a rental company will pass it on."],["Rest areas are for fatigue, not camping","State Forests are the free option","Coastal councils enforce actively"]),section("Marine parks and coastal access",["NSW marine parks apply zoning rules that restrict fishing and collecting in sanctuary zones, and the boundaries are published rather than signed on every beach. Check before fishing anywhere on the coast.","Beach driving is permitted in some areas with a permit and prohibited elsewhere. Stockton and parts of the mid north coast allow it, and the permits are issued by the relevant council or parks agency.","State forests remain the most flexible option in New South Wales, and the forestry agency publishes maps showing where camping and vehicle access are permitted.","An All Parks Pass covers vehicle entry across most NSW parks for a year and pays for itself quickly once you visit more than a handful."],["Marine park zones restrict fishing","Beach driving needs a permit","Boundaries are published, not signed"])], sources:[{label:"NSW National Parks camping and accommodation",url:"https://www.nationalparks.nsw.gov.au/camping-and-accommodation/"}] }),
  article({ slug:"camping-rules-queensland", title:"Camping rules in Queensland", description:"Permits, advance bookings and park alerts for Queensland parks and forests.", category:"Rules & safety", region:"Queensland", readTime:8, places:["K'gari","Boodjamulla National Park","Carnarvon Gorge"], imageAlt:"Queensland national park campground", intro:"Queensland protected-area camping usually starts with a permit. Book before arrival and carry the permit details beyond phone coverage.", sections:[section("Book and pay before arrival",["Queensland requires a camping permit for national park and forest camping areas. Most permits are booked online, and popular places can fill weeks ahead during school holidays.","Display the camping tag as instructed. Vehicle access permits can be separate, particularly on recreation areas and islands."]),section("Bush camps and vehicle access",["Bush camping is allowed only where the park permits it. Stay away from waterways, tracks and picnic areas, and follow the specific low-impact conditions for the route.","K'gari and other sand destinations require vehicle preparation, tide knowledge and separate access checks. A two-wheel-drive map pin is not enough evidence of access."], ["Camping permit","Vehicle permit if required","Tide and road check"]),section("Alerts, weather and fires",["Check Queensland park alerts, Bureau of Meteorology warnings and fire bans before leaving. Wet-season roads and creek crossings can close quickly.","Never enter floodwater. Turn around and use the backup camp rather than waiting at an unsafe crossing."]),section("National parks and the permit system",["Queensland national park camping requires a permit booked in advance through the Queensland Parks system, and permits must be displayed. Many sites are remote, basic and have limited or no facilities.","Popular islands and coastal parks, including K'gari and the Whitsundays, book out months ahead and have specific vehicle and access requirements on top of the camping permit.","Some parks require a separate vehicle access permit, particularly for beach driving. Check both before travelling, because arriving with one and not the other is a common and expensive mistake."],["Permits must be booked and displayed","Islands book months ahead","Beach driving needs a separate permit"]),section("Crocodile country changes the rules",["Estuarine crocodiles are present from roughly Rockhampton northwards and in all tropical waterways including creeks, estuaries and beaches. Croc-wise signage is posted widely and should be treated as absolute.","Do not camp within about fifty metres of the water's edge in croc country, do not clean fish at the water, and never swim outside a designated safe area. Crocodile behaviour is not predictable from appearance or water clarity.","Report sightings to the relevant authority rather than assuming somebody already has. Removal of problem animals depends on reports, and it protects the next campers as much as you."],["Crocs from Rockhampton north","Camp well back from the water","Report sightings"]),section("The wet season and road closures",["Northern Queensland's wet season runs roughly November to April, bringing monsoonal rain, cyclones and widespread road closures. Many national park campgrounds close entirely for the season.","Unsealed roads become impassable quickly and driving them wet causes damage and attracts fines. Check closure status with the local council or the state road authority daily rather than relying on a forecast.","The dry season from May to October is when most of the state's camping works properly, and it is also when the popular sites fill with travellers escaping southern winters."],["Wet season November to April","Many campgrounds close seasonally","Dry season fills with southern travellers"]),section("Free camping and council sites",["Queensland has a strong network of council-run low-cost and free camping areas, many in small inland towns actively encouraging travellers to stop and spend locally. Stay limits are typically 24 to 72 hours.","Some require self-contained vehicles and most have specific signed conditions. Showground camping is also common and usually inexpensive with basic facilities.","Coastal council areas are considerably stricter than inland ones, reflecting demand. Assume that a beachfront car park is prohibited unless signage explicitly says otherwise."],["Inland towns welcome travellers","Showgrounds are a good cheap option","Coastal councils are strict"]),section("K'gari and dingo safety",["K'gari has specific and strictly enforced dingo safety rules, including staying in groups, never carrying food while walking and using the fenced camping areas. Serious attacks have occurred and the rules exist because of them.","Feeding or leaving food accessible to dingoes carries substantial fines. Habituated animals are the ones that attack, and every incident traces back to food access.","Queensland's parks booking system opens a rolling window ahead of arrival, and the most popular island and coastal sites are taken within minutes of release.","Vehicle access permits for beach driving are separate from camping permits, and arriving with only one is a common and expensive mistake on the islands."],["Dingo rules are strictly enforced","Never carry food while walking","Feeding carries substantial fines"])], sources:[{label:"Queensland Parks camping bookings",url:"https://parks.qld.gov.au/camping/bookings"}] }),
  article({ slug:"camping-rules-victoria", title:"Camping rules in Victoria", description:"Bookings, fees, seasonal roads and fire restrictions across Victoria.", category:"Rules & safety", region:"Victoria", readTime:8, places:["Tidal River","Lake Catani Campground","Johanna Beach"], imageAlt:"Victorian forest campground", intro:"Victoria has bookable national park campgrounds, free basic sites and commercial parks. The exact campground page is the only reliable place to confirm fees and facilities.", sections:[section("Bookings and campground conditions",["Book Parks Victoria sites through the official system where required. Bring the vehicle registration and keep the confirmation accessible.","Some camps are first come, first served, while others close seasonally. Do not occupy a booked or closed site because it appears empty."]),section("State forests and roadside stops",["Camping in state forests follows different rules from national parks. Use established sites, protect waterways and check local firewood and fire restrictions.","Roadside rest areas are for fatigue management and can have signed time limits. Councils may enforce separate overnight parking rules."], ["Check the land manager","Check seasonal closures","Check vehicle length limits"]),section("Fire and alpine access",["Victoria's fire danger can escalate quickly. Check VicEmergency and park alerts, and never light a fire when restrictions prohibit it.","Alpine and forest roads close seasonally or after storms. Respect gates and carry a lower-altitude alternative."]),section("Parks Victoria and the booking system",["Victorian national park camping is booked through Parks Victoria, with fees varying by site category. Popular coastal sites along the Great Ocean Road and in Wilsons Promontory book out months ahead and run ballots for peak periods.","Wilsons Promontory in particular allocates summer sites by ballot rather than first booking, which catches out travellers expecting to reserve normally. Check the process well before your dates.","Many sites have vehicle and occupancy limits stated on the booking. Bring what you booked for, because sites are compact and rangers do check at busy grounds."],["Wilsons Prom runs a summer ballot","Book coastal sites months ahead","Occupancy limits are checked"]),section("State forests and dispersed camping",["Victoria has extensive state forest where dispersed camping is permitted free of charge, subject to fire restrictions and seasonal road closures. This is where most of the state's genuinely free camping happens.","Camp on existing cleared sites rather than creating new ones, stay away from waterways and roads by the stated minimum distances, and take all rubbish out. There are no facilities.","Seasonal road closures in the High Country and other forest areas typically run from June to November, protecting tracks that are fragile when wet. Driving a closed road carries substantial fines."],["State forest camping is free","Use existing cleared sites","Seasonal closures June to November"]),section("Fire restrictions and the danger period",["Victoria's declared fire danger period varies by region and usually covers summer into autumn. During it, campfires are restricted and on total fire ban days all open flame including solid fuel barbecues is prohibited.","Fires must be in a properly constructed fireplace, no larger than one metre by one metre, with a three metre clear space and someone in attendance at all times. These conditions apply even outside a ban.","Check the CFA fire danger rating for your district each morning in summer. Campgrounds in forest are among the worst places to shelter on a bad day, and leaving early is the standard advice."],["One metre fire, three metre clearance","Never leave a fire unattended","Check CFA ratings each morning"]),section("Free camping and the coast",["Coastal councils along the Great Ocean Road and the Mornington Peninsula prohibit overnight vehicle camping almost entirely and enforce it actively. Assume prohibited unless signage says otherwise.","Inland, several councils provide free or low-cost camping in towns to attract travellers, and Victorian showgrounds frequently offer cheap sites with power and amenities.","Rest areas managed by the state road authority are for fatigue breaks. A sleep is fine; setting up camp is not, and the distinction matters where enforcement is active."],["Coastal councils prohibit and enforce","Inland towns offer free sites","Rest areas are for sleep, not camp"]),section("Alpine and river camping specifics",["Camping in Victorian alpine areas is restricted above certain elevations to protect fragile vegetation, and specific distances from water and roads apply in state forest.","River frontage camping on Crown land requires awareness of licensed water frontages, some of which permit camping and some of which do not. Signage and the state's public land maps are the guide.","Parks Victoria publishes seasonal road closure dates each year, and checking them before planning a High Country route saves a wasted drive to a locked gate.","Total fire ban days prohibit solid fuel entirely, so carrying a gas cooker means the trip never depends on being allowed to light a fire."],["Alpine camping is height-restricted","Distances from water apply","Check Crown land frontage rules"])], sources:[{label:"Parks Victoria booking information",url:"https://www.parks.vic.gov.au/where-to-stay/booking-information"}] }),
  article({ slug:"camping-rules-tasmania", title:"Camping rules in Tasmania", description:"Park passes, booked campgrounds, changing weather and low-impact camps in Tasmania.", category:"Rules & safety", region:"Tasmania", readTime:8, places:["Freycinet National Park","Cradle Mountain","Mount Field National Park"], imageAlt:"Tasmanian national park camping landscape", intro:"Tasmania combines small free camps, national park sites and commercial holiday parks. Weather and sensitive environments make the details of each site important.", sections:[section("Parks passes and bookings",["A valid parks pass is required when entering Tasmania's national parks. Camping fees or bookings can be separate from park entry.","Freycinet and other popular areas can use seasonal booking or ballot arrangements. Check before building fixed ferry and driving dates around one campground."]),section("Free camps and local rules",["Council and community camps can have registration, donation, vehicle-type or maximum-stay rules. Read signs and do not assume an old review still reflects the current arrangement.","Keep wastewater contained and use public dump points. Camp only on durable ground outside exclusion zones."], ["Parks pass","Camp booking","Cold-weather gear"]),section("Weather and biosecurity",["Tasmanian weather changes fast. Pack for cold rain in summer and avoid exposed camps when severe wind is forecast.","Clean boots, bikes and camping gear to avoid moving soil, seeds and aquatic pests between sensitive places."]),section("Parks passes are compulsory",["A Tasmania Parks Pass is required for vehicle entry to all national parks, and it is separate from any camping fee. A holiday pass covering all parks for eight weeks is far better value than daily passes if you visit more than two.","Passes are checked at major parks including Cradle Mountain and Freycinet, and fines apply for entering without one. Buy online before you travel rather than at the gate.","Cradle Mountain also runs a mandatory shuttle from the visitor centre during the day, with private vehicle access restricted. Factor the shuttle timetable into your plans."],["Parks pass required for vehicle entry","Holiday pass covers eight weeks","Cradle Mountain shuttle is mandatory"]),section("Quarantine at the border",["Tasmania enforces strict biosecurity on arrival by ferry or air. Fresh fruit and vegetables, plants, soil, honey and used beekeeping equipment are all restricted, and detector dogs work the ferry terminal.","Clean camping gear, boots and bicycles before travelling, and dispose of fresh produce before boarding rather than having it confiscated. Fines apply for undeclared items.","The rules exist because Tasmania is free of several pests and diseases present on the mainland. Complying takes a few minutes and protects an island agricultural economy."],["No fresh produce across Bass Strait","Clean boots and gear before travel","Detector dogs work the terminal"]),section("Alpine weather in any season",["Tasmania's weather is the most changeable in Australia and highland areas can get snow in any month. Walks above the treeline are alpine outings regardless of the date or the forecast at the car park.","Carry warm and waterproof layers on every walk, including in January. Hypothermia is the most common serious problem on Tasmanian day walks and it develops quickly in wind and rain.","Register your intentions in the log books at track heads. They are the first thing checked when someone is overdue and they have shortened searches repeatedly."],["Snow possible in any month","Waterproofs even in January","Fill in track head log books"]),section("Free camping and the west",["Tasmania has a good network of free and low-cost council camping areas, many in small towns, and the state is compact enough that you are rarely far from one. Stay limits are typically 24 to 72 hours.","National park campgrounds range from basic to serviced and are booked or first come depending on the site. Freycinet and Cradle Mountain both require booking in the peak season.","The west coast is wet, remote and sparsely serviced. Fill fuel at Queenstown or Strahan and carry supplies, because the gaps between towns on that side of the island are meaningful."],["Good network of free council sites","Book Freycinet and Cradle in season","Fuel up before the west coast"]),section("Walking track regulations",["The Overland Track requires a booking and fee in the walking season with a one-way north to south direction. Other multi-day walks have their own permit and registration requirements.","Fuel stove only areas apply across much of the Tasmanian wilderness, prohibiting campfires entirely regardless of the fire danger rating. Carry a stove and check the status for your route.","Tasmania's compact size means you are rarely more than an hour from a town, which makes resupply straightforward compared with mainland remote travel.","Fuel stove only areas cover much of the Tasmanian wilderness and apply regardless of the fire danger rating, so check the status for your specific route."],["Overland Track needs booking","Fuel stove only areas are common","One-way direction in season"])], sources:[{label:"Parks and Wildlife Service Tasmania",url:"https://parks.tas.gov.au/"}] }),
  article({ slug:"camping-rules-south-australia", title:"Camping rules in South Australia", description:"Book campsites, understand fire restrictions and camp responsibly in South Australian parks.", category:"Rules & safety", region:"South Australia", readTime:8, places:["Ikara-Flinders Ranges","Coorong National Park","Deep Creek National Park"], imageAlt:"South Australian national park campsite", intro:"South Australian national park camping is generally booked before arrival. Vehicle entry, campsite fees and fire rules can be separate parts of the same stay.", sections:[section("Book before you go",["Reserve the campsite online or through an authorised booking agent. Check the permitted vehicle number, site dimensions and check-in details before paying.","Keep the confirmation on your phone. Park entry can be restricted for safety, conservation or operational reasons even after a booking is made."]),section("Campfires and pets",["Check the park page, Country Fire Service restrictions and park alerts before using any flame. Bring clean firewood only where allowed and use supplied fire pits.","Most national parks do not allow pets. A lead does not override a no-pet rule."], ["Booking saved","CFS check","Clean firewood only if permitted"]),section("Remote country",["Outback tracks and camps can close after rain. Contact the park or local authority when conditions are uncertain, and do not damage a road by pushing through.","Carry water, fuel and an emergency communication plan appropriate to the distance."]),section("Parks passes and booking",["South Australian national park camping is booked online and many parks charge vehicle entry as well as camping. A multi-park or annual pass is available and worth it if you are visiting several.","Some parks, including the Flinders Ranges and Innamincka, have desert parks passes or specific permits. Check what your route needs before setting out, because gates and rangers do check.","Sites in popular parks fill over school holidays and long weekends, particularly in the Flinders and along the coast. Outside those, availability is generally good a few days ahead."],["Vehicle entry often separate from camping","Desert parks need specific passes","Book holidays and long weekends"]),section("Fruit fly quarantine",["South Australia maintains fruit fly exclusion zones and prohibits bringing fresh fruit and some vegetables across its borders and into the Riverland. Quarantine bins are provided at road borders and checkpoints operate.","Fines apply regardless of whether you knew, so plan your shopping around it: buy fresh produce after the border rather than before. This catches out a large number of travellers each year.","There are also internal checkpoints entering the Riverland zone. Carrying produce within the state can be an offence even after a legal purchase elsewhere in South Australia."],["No fresh produce across the border","Internal Riverland checkpoints too","Fines apply even if unaware"]),section("Outback travel and permits",["Travel on the Oodnadatta, Strzelecki and Birdsville tracks and into the far north requires genuine preparation, and some routes cross Aboriginal land requiring permits arranged in advance.","The Desert Parks Pass covers entry and camping in several remote parks and includes route information. It is required rather than optional for parks it covers.","Carry substantial water, fuel range, recovery equipment and a satellite communication device. Roads close after rain and stay closed for days, and there is no mobile coverage."],["Some routes need land access permits","Desert Parks Pass is required","Roads close for days after rain"]),section("Fire restrictions",["South Australia declares fire danger seasons by district, generally running from November to April. During the season, campfires are restricted and total fire bans prohibit all open flame including solid fuel barbecues.","Gas appliances are generally permitted on ban days subject to conditions including a cleared area and someone in attendance. Check the specific ban rather than assuming.","Many parks prohibit fires permanently, particularly in the arid zone where firewood collection damages fragile habitat. Bring a gas cooker and do not rely on being able to have a fire."],["Fire danger season November to April","Gas usually allowed on ban days","Arid parks often ban fires always"]),section("Coastal and conservation park rules",["Many South Australian conservation parks permit camping only in designated areas with a booked site, and several coastal parks restrict vehicle access to protect dune systems.","Beach driving is permitted in some areas with a permit, notably along parts of the Coorong and Yorke Peninsula. Check the specific area, because driving on a closed beach carries fines and does real damage.","South Australia's parks system publishes campground alerts for fire risk and track closures, and these change quickly in summer across the arid parks.","Desert parks require their own pass covering entry and camping, and it is a requirement rather than an optional convenience for the parks it covers."],["Designated sites only in most parks","Beach driving needs a permit","Dune systems are protected"])], sources:[{label:"South Australia camping essentials",url:"https://www.parks.sa.gov.au/know-before-you-go/camping-essentials"}] }),
  article({ slug:"camping-rules-western-australia", title:"Camping rules in Western Australia", description:"National park bookings, entry fees and long-distance camping across Western Australia.", category:"Rules & safety", region:"Western Australia", readTime:8, places:["Cape Range National Park","Karijini National Park","Cape Le Grand National Park"], imageAlt:"Western Australian national park campsite", intro:"Western Australian camping rules vary across national parks, local government land, pastoral areas and private parks. Large distances make a closed or full campground more than a minor inconvenience.", sections:[section("Park Stay WA and fees",["Many national park camps are booked through Park Stay WA. Camping fees are usually charged per person per night, and park entry can be separate.","Some campgrounds remain first come, first served. Arrive early and keep a legal alternative within your fuel range."]),section("Roadside and remote camping",["Use signed overnight areas and keep heavy-vehicle bays free. Local governments can prohibit camping outside licensed grounds, including beaches and town parking areas.","On remote roads, check access, station permission and Aboriginal land permit requirements before leaving the highway."], ["Camp booking","Park entry","Road and permit check"]),section("Fire, water and distance",["Carry drinking water and verify whether campground taps are potable. Fire restrictions differ by district and season.","Do not collect firewood in protected areas. Heat and wind can make a legal morning fire unsafe or prohibited by afternoon."]),section("The scale changes the planning",["Western Australia covers a third of the continent and the distances between parks, towns and fuel are unlike anywhere else. A camping trip here is a logistics exercise before it is anything else.","Parks and Wildlife campgrounds are booked online for popular sites and first come for many remote ones. A parks pass covering vehicle entry is available and is worth it beyond a few visits.","Many northern parks close for the wet season, roughly November to April, and reopen when roads and crossings allow. Check the current status rather than the published season."],["Book popular DBCA sites online","Parks pass covers vehicle entry","Northern parks close in the wet"]),section("Free camping and the 24 hour rule",["Many WA local governments permit 24 hour stays in designated rest areas and prohibit camping elsewhere. Shire rules vary widely, and the more remote the shire, the more relaxed it generally is.","Some rest areas along the North West Coastal Highway and the Great Northern Highway allow longer stays and are effectively free campgrounds. Signage states the limit and it is enforced in busier areas.","Station stays, where pastoral properties open camping areas to travellers, are a distinctive WA option and often the only accommodation for hundreds of kilometres. Most take cash and few have reliable booking."],["24 hour limits are common","Station stays fill the gaps","Carry cash for station stays"]),section("Water, fuel and communication",["Carry a minimum of four to five litres of drinking water per person per day plus a substantial reserve, and treat fuel range as the constraint that shapes the route. Roadhouses can be closed, out of fuel or card-only with unreliable connections.","Mobile coverage exists near towns and disappears entirely between them. A satellite messenger or personal locator beacon is standard equipment for remote WA travel rather than an optional extra.","Tell someone your route and expected arrival. If you break down, stay with the vehicle, which is shelter and is far easier to find than a person walking."],["Five litres per person per day","Carry a satellite messenger","Stay with the vehicle"]),section("Heat, cyclones and the dry",["The dry season from May to October is when the north works. The wet brings extreme humidity, monsoonal rain, cyclones between November and April, and widespread closures.","In the south west, the pattern reverses: winter is wet and cool, summer is hot and dry, and spring brings the wildflowers. The two halves of the state need completely different planning.","Heat is the underrated risk. Inland summer temperatures regularly exceed forty degrees, and vehicle breakdown in that heat without adequate water is genuinely life threatening."],["North works May to October","Cyclones November to April","Inland heat is a genuine risk"]),section("Aboriginal land and access permits",["Substantial areas of Western Australia are Aboriginal land requiring an entry permit, including sections of routes through the Kimberley and the interior. Permits are applied for in advance through the relevant body.","Some routes require a transit permit even if you are not stopping. Check whether your intended road crosses land requiring one, because they are not issued at the boundary.","Western Australia's parks agency publishes campground availability and closures online, which matters because the distances mean a closed site can cost a full day.","Distances between parks in Western Australia mean a closed campground can cost a full day, so confirm availability before committing to a long drive."],["Permits apply in advance, not at the gate","Transit permits cover pass-through","Check the route, not just the destination"])], sources:[{label:"Explore Parks WA camping fees",url:"https://exploreparks.dbca.wa.gov.au/camping-fees"}] }),
  article({ slug:"camping-rules-northern-territory", title:"Camping rules in the Northern Territory", description:"Online campsite bookings, visitor passes and remote permits in NT parks.", category:"Rules & safety", region:"Northern Territory", readTime:8, places:["Litchfield National Park","Kakadu National Park","Tjoritja"], imageAlt:"Northern Territory park campground", intro:"Designated NT park campsites generally require online booking and payment before arrival. Visitor passes and special permits can apply as well.", sections:[section("Bookings and visitor passes",["Book designated campsites through the NT parks system and keep the camping tag available. Rangers cannot always accept payment at the campground.","Visitors need an NT Parks Visitor Pass for most participating parks and reserves. Kakadu uses separate national park arrangements." ]),section("Camping outside designated areas",["A permit is required to camp overnight outside designated areas and for specific protected places such as Garig Gunak Barlu. Apply with enough time for assessment.","Remote permission does not remove the need for route, water, heat and communication planning."], ["Camping tag","Visitor pass","Separate permit if required"]),section("Seasonal access and water safety",["Wet-season flooding closes roads and campgrounds. Check the latest park page even when the weather is dry where you are standing.","Follow crocodile and swimming signs at every waterbody. Conditions and permitted swimming areas change."]),section("Permits for Aboriginal land",["Large areas of the Territory are Aboriginal freehold land requiring a permit to enter or transit, including much of Arnhem Land and sections of major routes. Permits are applied for through the relevant land council in advance.","Permits take time to process and are not issued at the boundary. Plan several weeks ahead for Arnhem Land, and check whether your route crosses land requiring a transit permit even if you are not stopping.","Alcohol restrictions apply across many Territory communities and areas, with substantial penalties for carrying alcohol into restricted zones. Check before travelling with any in the vehicle."],["Land council permits take weeks","Transit permits apply to some routes","Alcohol restrictions carry big penalties"]),section("Kakadu, Litchfield and park passes",["Kakadu requires a park pass purchased in advance, while Litchfield does not. Uluru-Kata Tjuta and Watarrka have their own arrangements, so check each park rather than assuming a single Territory system.","Many of the best sites in Kakadu require high clearance four-wheel drive and involve creek crossings, which most standard hire agreements prohibit. Litchfield delivers more per day for a two-wheel drive.","Sacred sites within parks have photography and access restrictions marked by signage. These are conditions of access rather than suggestions, and respecting them matters."],["Kakadu needs a pass, Litchfield does not","Jim Jim and Twin Falls need 4WD","Observe photography restrictions"]),section("Crocodiles and water",["Estuarine crocodiles are present throughout the Top End in rivers, creeks, billabongs, estuaries and along the coast. Any waterway should be assumed to contain them unless a current sign says otherwise.","Swimming holes are surveyed and opened seasonally, and the status changes. Check on the day rather than relying on a previous visit or a guidebook, and never camp at the water's edge.","Freshwater crocodiles are also widespread and generally leave people alone, but telling the two apart from a distance is not a reliable skill. Treat all crocodile habitat the same way."],["Assume crocs in every waterway","Swimming hole status changes","Never camp at the water's edge"]),section("The build-up and the seasons",["The Territory runs on two seasons plus the build-up. The dry, from May to September, is comfortable and busy. The build-up in October and November brings extreme humidity before the rain arrives.","The wet, from December to March, brings monsoonal rain, road closures, and closure of many parks and campgrounds. It also brings the waterfalls to full flow, which some travellers prefer.","Central Australia is different again: hot summers exceeding forty degrees and cold winter nights below freezing. Pack for a large diurnal swing rather than a single temperature."],["Dry season May to September","Build-up is October and November","Central Australia freezes at night"]),section("Fishing, hunting and collecting",["Recreational fishing in the Territory has size and bag limits and some areas are closed. Barramundi in particular have seasonal closures, and the rules differ between tidal and fresh water.","Collecting firewood, plants, rocks and artefacts is prohibited in parks and reserves. Artefacts in particular are protected and removing them is a serious offence.","Territory parks publish seasonal opening dates that shift with the wet, so confirm a campground is open rather than relying on the published season.","Alcohol restrictions apply across many Territory regions with substantial penalties, so check before travelling with any in the vehicle."],["Barramundi have seasonal closures","Collecting is prohibited in parks","Artefact removal is a serious offence"])], sources:[{label:"NT parks camping",url:"https://nt.gov.au/parks/camping"}] }),
  article({ slug:"camping-rules-act", title:"Camping rules in the ACT", description:"Approved campgrounds, protected areas, fires and closures around Canberra.", category:"Rules & safety", region:"Australian Capital Territory", readTime:7, places:["Namadgi National Park","Cotter Campground","Woods Reserve"], imageAlt:"Campground in the ACT ranges", intro:"Camping in the ACT is limited to approved campgrounds and their conditions. Namadgi, Cotter and other areas can close during fire danger or severe weather.", sections:[section("Choose an approved campground",["Use territory or privately managed campgrounds where overnight stays are expressly allowed. Picnic areas, trailheads and suburban parking spaces are not substitutes.","Check bookings, gate hours, vehicle size, generators and pet rules for the exact campground." ]),section("Namadgi and remote walks",["Namadgi protects sensitive natural and cultural places. Camp only in permitted areas and follow track, group and fire conditions.","Leave a trip intention with someone reliable when walking beyond busy areas. Mobile coverage is uneven."], ["Approved site","Weather check","Trip contact"]),section("Fire and water",["ACT fire danger can close parks at short notice. Check Emergency Services Agency advice and park alerts before departure.","Treat water unless the campground clearly identifies a maintained potable supply. Carry enough for the full stay when uncertain."]),section("A small territory with clear rules",["The ACT is compact and camping options are limited to Namadgi National Park, Cotter and a small number of designated areas. There is essentially no informal or roadside camping permitted anywhere in the territory.","Namadgi campgrounds are mostly free but require registration, and the park covers around half the territory's land area. Honeysuckle, Orroral and Mount Clear are the main sites.","Because the ACT is surrounded by NSW, most travellers end up camping across the border. Check which jurisdiction you are actually in, because the rules and fees differ immediately."],["No informal camping in the ACT","Namadgi sites are free but need registration","Rules change instantly at the NSW border"]),section("Namadgi and the alpine conditions",["Namadgi rises to over 1,900 metres and the higher country carries snow in winter. Conditions at Mount Clear are considerably colder than Canberra, and visitors regularly underestimate the difference.","The park was heavily burnt in the 2019 to 2020 fires and regeneration continues, with some tracks and facilities altered. Check the current status with the visitor centre before planning specific walks.","Water in the park should be treated. Tanks at campgrounds are rainwater and not guaranteed potable, and creek water carries the usual risks."],["Much colder than Canberra","2020 fires altered tracks","Treat all water in the park"]),section("Fire restrictions and the danger period",["The ACT declares a bushfire danger period, usually from October to March, during which fires are restricted. Total fire bans prohibit all open flame including solid fuel barbecues.","Namadgi prohibits campfires entirely in most areas year round, and gas cookers are the practical option. Check the current park conditions before assuming a fireplace can be used.","The territory has burnt severely twice in living memory, in 2003 and 2020. Fire danger ratings are taken seriously here and leaving early on a bad day is standard practice."],["Danger period October to March","Namadgi prohibits most campfires","Gas cooker is the practical option"]),section("Using Canberra as a base",["Canberra has caravan parks close to the centre and is compact enough that day trips reach Namadgi, Tidbinbilla and the Brindabellas easily. For many travellers this works better than camping in the park.","Tidbinbilla Nature Reserve has koalas, platypus and rock wallabies in an accessible setting and charges vehicle entry. It is a good half day and considerably easier than the Namadgi walks.","The national institutions, including the War Memorial, Questacon and the National Gallery, are mostly free and make excellent wet-weather options if the mountain forecast is poor."],["Caravan parks close to the centre","Tidbinbilla is an accessible half day","Free national institutions for wet days"]),section("Cotter and the reserves",["The Cotter Reserve and Casuarina Sands offer day use and limited camping close to Canberra, and they are heavily used on summer weekends. Alcohol restrictions apply at several of these sites.","Murrumbidgee River Corridor sites permit swimming but the river has strong currents and submerged hazards. Check conditions and swim only where signage permits it.","Because the ACT is small, most travellers treat it as a stop rather than a destination, using Canberra as a base and camping across the border in New South Wales.","Namadgi is considerably colder than Canberra and carries snow in winter, so pack for mountain conditions rather than the city forecast."],["Alcohol restrictions at some reserves","Cotter is busy on summer weekends","River currents are stronger than they look"])], sources:[{label:"ACT Parks and Conservation",url:"https://www.parks.act.gov.au/"}] }),

  article({ slug:"is-free-camping-legal-australia", title:"Is free camping legal in Australia?", description:"Free camping is legal only where the land manager allows an overnight stay.", category:"Rules & safety", region:"Australia", readTime:8, places:["Council campgrounds","National parks","Roadside rest areas"], imageAlt:"Simple free campground in Australia", intro:"Australia has free camps, but there is no national right to camp wherever a vehicle can park. The rule comes from the exact land, sign and local authority.", sections:[section("Parking is not camping permission",["A legal parking space may still prohibit sleeping, setting up camp or staying overnight. Look for explicit overnight permission, time limits and vehicle restrictions.","Do not rely on the absence of a no-camping sign. Confirm the land manager or council rule when the purpose of the area is unclear."]),section("Places that may be free",["Some council camps, community reserves, national park sites and roadside areas charge no nightly fee. Registration, booking, donation or maximum-stay conditions may still apply.","Rest areas primarily manage fatigue. Keep truck spaces clear and avoid awnings, chairs or levelling setups that turn a short rest into an illegal camp."], ["Read every sign","Confirm the land manager","Keep a backup stop"]),section("Leave the place open",["Contain rubbish and wastewater, use toilets where provided and move on within the allowed stay. Noise, fires and sprawling setups are common reasons communities restrict free camping.","If a site is full, do not invent a new bay on vegetation or a nearby street."]),section("There is no national answer",["Free camping legality is set by whoever manages the land: state parks agencies, state forests, local councils, road authorities and private owners all apply different rules. There is no Australia-wide position to learn.","The practical consequence is that the answer changes at every local government boundary, and those boundaries are invisible from the road. A rule confirmed in one shire tells you nothing about the next.","The reliable sources are the signage at the specific location and the relevant council's website. Everything else, including apps and guidebooks, is a starting point rather than an authority."],["No national rule exists","Answer changes at each shire boundary","Signage is the authority"]),section("Where it is generally permitted",["State forests in Victoria, NSW and Queensland permit dispersed camping free of charge in most areas, subject to fire restrictions and seasonal closures. This is the most reliable free camping in the eastern states.","Many inland councils, particularly in Queensland, NSW and South Australia, provide free or donation-based camping to attract travellers into town. These are signed, welcomed and often have basic facilities.","Station stays and roadhouse camping fill the gaps in remote areas. Both are usually inexpensive rather than free, and both are frequently the only option for hundreds of kilometres."],["State forests are the reliable option","Inland towns actively welcome travellers","Station stays fill remote gaps"]),section("Where it is generally prohibited",["Coastal councils near major cities and in tourist areas almost universally prohibit overnight camping in vehicles, and enforce it with patrols and fines. Assume prohibited on any popular coastline unless signage says otherwise.","National parks require a permit and a designated campground almost everywhere. Camping outside designated areas in a national park is an offence in every state.","Rest areas managed by road authorities are for fatigue breaks. Sleeping is generally fine; setting up camp with awnings and chairs is not what they are provided for and is often explicitly prohibited."],["Coastal councils prohibit and patrol","National parks need designated sites","Rest areas are for fatigue only"]),section("Self-containment and behaviour",["Some councils permit free camping only for self-contained vehicles with onboard toilet and waste storage. The definition varies between councils and some require certification while others rely on a declaration.","Regardless of the rules, behaviour is what keeps sites open. Arrive late, leave early, keep the footprint small, take all rubbish, and never empty waste anywhere but a dump point.","Sites close because of waste, noise and overcrowding, and closures are usually permanent. The districts with the strictest rules today are the ones where behaviour was worst previously."],["Self-containment rules vary by council","Small footprint, early departure","Bad behaviour closes sites permanently"]),section("Tools that actually help",["Council websites, state parks pages and the signage itself are the authoritative sources. Camping apps and community listings are useful for finding candidates and are not a defence if a site turns out to be prohibited.","Where a listing and a sign disagree, follow the sign and report the discrepancy so the listing improves. Enforcement officers work from the local law and the sign, not from any app.","When in genuine doubt, a low-cost council site or a showground is usually within reach and removes the question entirely for a very small amount of money.","Photographing the sign when you arrive costs nothing and is the only evidence that reliably helps if an infringement is later disputed."],["Apps find candidates, signs decide","Report discrepancies you find","Officers work from the local law"])] }),
  article({ slug:"campfires-camping-australia", title:"Campfire rules for camping in Australia", description:"Check local fire bans, park rules and weather before striking a match.", category:"Rules & safety", region:"Australia", readTime:8, places:["Designated fire pits","Park alerts","Local fire authority"], imageAlt:"Legal campfire in a designated fire ring", intro:"Campfire permission can change with the district, season, fuel type and fire danger rating. A fire ring proves that fires have been used there, not that one is legal today.", sections:[section("Three checks before lighting",["Read the campground rules, check the relevant state fire authority and look for local park alerts. Complete fire bans override normal campground permission.","Gas cookers can also be restricted during severe conditions. Check the rule for the appliance, not only open fires."]),section("Firewood and setup",["Collecting timber is prohibited in many parks because fallen wood is habitat. Bring clean, untreated firewood only where the land manager allows it.","Use an existing fireplace, clear the immediate area as directed and keep water beside you. Never light beneath branches or in strong wind."], ["Permission checked","Water ready","Fire attended by an adult"]),section("Put it out cold",["Extinguish with water, stir the remains and repeat until everything is cold enough to touch. Sand can hide hot embers rather than extinguish them.","Never leave a fire unattended, including while sleeping. If wind rises or conditions feel wrong, put it out."]),section("Fire danger ratings and total fire bans",["Australia uses a national Fire Danger Rating system with four levels from Moderate to Catastrophic, published daily by district. Total fire bans are declared separately and prohibit all open flame regardless of the rating.","On a total fire ban day, campfires and solid fuel barbecues are prohibited. Gas appliances are generally permitted with conditions including a cleared area and constant attendance, but the specific ban wording governs.","Ratings and bans are published each afternoon for the following day. Check them daily in summer rather than relying on how the weather feels, because the declaration is based on forecast conditions."],["Four rating levels, Moderate to Catastrophic","Bans prohibit solid fuel entirely","Check the declaration daily"]),section("Where fires are permitted at all",["Many national parks prohibit campfires permanently, particularly in arid zones where firewood collection destroys habitat that takes decades to form. Others permit them only in provided fireplaces.","Collecting firewood is prohibited in most national parks and reserves. Bring your own from outside the area, and be aware that some regions also restrict moving firewood to limit pest spread.","Check the specific campground page rather than the state-wide position. The land manager's rule is stricter than the fire danger system in many places and applies year round."],["Many parks ban fires permanently","Firewood collection is usually prohibited","Bring your own wood"]),section("Building and controlling a legal fire",["Where permitted, use an existing fireplace, keep the fire small, clear combustible material well back and have water immediately beside you rather than in the vehicle. Never light in wind or under overhanging branches.","Typical legal conditions specify a maximum fire size, a cleared radius of several metres and constant adult attendance. These apply outside total fire bans as well, and breaching them carries penalties.","Never leave a fire unattended, including while it burns down. Most escaped campfires start after the people who lit them decided it was nearly out."],["Water beside you, not in the vehicle","Cleared radius of several metres","Never leave it unattended"]),section("Putting it out and the consequences",["A fire is out when it is cold to the touch. Douse it, stir the ashes, douse again and keep going until you can put your hand in the remains. Embers survive under ash for many hours.","Escaped fires carry severe penalties in every state, including large fines and imprisonment where negligence is established. You can also be liable for suppression costs, which run into very large sums.","If a fire escapes, do not attempt to fight it beyond the first seconds. Move away and call triple zero immediately with the clearest location you can give."],["Out means cold to the touch","Liability includes suppression costs","Call 000 and move away"]),section("Cooking when fires are banned",["Gas cookers are generally permitted on total fire ban days subject to conditions: a cleared area, a person in attendance and immediate access to water. Check the specific ban wording, because conditions vary by state.","Never cook inside a tent, an awning or an unventilated vehicle. Carbon monoxide is odourless and has killed campers, and the risk is highest in exactly the cold or wet conditions that tempt people indoors.","Keep a lightweight gas cooker in the vehicle permanently, because a total fire ban can be declared with a day's notice and it removes any dependence on lighting a fire.","Fire danger ratings are published each afternoon for the following day, so checking them the evening before gives you time to change plans rather than react."],["Gas usually allowed with conditions","Never cook in a closed space","Carbon monoxide has no smell"])], sources:[{label:"Bureau of Meteorology warnings",url:"https://www.bom.gov.au/weather-and-climate/warnings-and-alerts/"}] }),
  article({ slug:"sleeping-in-car-australia", title:"Can you sleep in your car in Australia?", description:"Sleeping in a car is allowed only where local land, parking and vehicle rules permit it.", category:"Rules & safety", region:"Australia", readTime:7, places:["Caravan parks","Campgrounds","Roadside rest areas"], imageAlt:"Campervan parked at an authorised overnight site", intro:"The vehicle does not make the location legal. Council bylaws, signs, park rules and private property rights decide whether you can sleep there.", sections:[section("Read the location, not the internet",["Check signs for parking hours, no-camping rules and vehicle restrictions. Beach carparks and residential streets are commonly monitored in busy visitor towns.","An old review does not protect you from a fine. Use the current council or land-manager information." ]),section("Rest areas",["Driver-reviver and highway rest areas exist to reduce fatigue. Some allow a limited overnight rest, while others prohibit camping or restrict vehicle types.","Keep truck bays free, contain noise and do not spread equipment outside the vehicle unless the area permits camping."], ["Legal location","Ventilation","Safe exit","No engine running for heat"]),section("Safer alternatives",["A basic campground, showground, caravan park or farm stay provides clearer permission and often toilets or water. Arrive before dark and confirm access for the vehicle.","Never sleep with a fuel-burning heater or cooker operating inside a closed vehicle."]),section("Parking legally is not the same as camping legally",["A vehicle can be lawfully parked somewhere and still be prohibited from being slept in. That distinction is what most infringements turn on, and it is why travellers who checked the parking signs still get fined.","Council local laws govern this and they vary at every boundary. Some permit sleeping in a vehicle in designated areas, many prohibit it in all public places, and enforcement is heaviest in coastal and tourist areas.","Read the signage for the specific bay, not the street. Time-limited parking, permit zones and overnight prohibitions are frequently signed separately and all apply at once."],["Parking legally does not permit sleeping","Rules change at every council boundary","Read the sign for the specific bay"]),section("Where it is generally accepted",["Designated rest areas along highways permit sleeping for fatigue management, usually up to 24 hours, and this is the most reliably legal option nationwide. They are for rest rather than for setting up camp.","Many inland council towns provide free or low-cost overnight areas that expressly permit sleeping in vehicles. Showgrounds and sports grounds often do the same for a small fee.","Some 24 hour service stations and roadhouses permit overnight parking, particularly on long highway routes. Ask inside rather than assuming, and buy something."],["Rest areas allow up to 24 hours","Inland towns often permit it","Ask at roadhouses rather than assume"]),section("Doing it safely",["Choose somewhere with other vehicles present, lighting and an easy exit. Park facing out where you can, keep valuables out of sight, and lock the doors while keeping a clear way to get out quickly.","Ventilation matters more than people expect. A sealed car with people sleeping in it gets humid and stuffy quickly, and in heat it becomes genuinely dangerous. Crack windows with insect screens if you have them.","Never run the engine for air conditioning while sleeping. Exhaust can enter the cabin, and carbon monoxide is odourless and has killed people doing exactly this."],["Park facing out, keep an exit clear","Ventilate, do not seal the car","Never idle the engine while sleeping"]),section("Heat, cold and the practical limits",["An Australian summer makes sleeping in an unventilated car unsafe rather than uncomfortable. Interior temperatures rise fast and stay high overnight in the north, and this is the leading practical reason not to do it.","In winter, inland and alpine nights drop below freezing and a car offers almost no insulation. A proper sleeping bag rated to the conditions matters more in a vehicle than in a tent.","If you are doing this regularly, a window shade set, insect screens and a decent mattress transform it. Without those it works for a night and becomes miserable across a week."],["Cars overheat overnight in the north","Almost no insulation in winter","Screens and shades transform it"]),section("Making a car workable for a night",["Window shades, insect screens and a proper mattress transform sleeping in a car from an endurance exercise into something repeatable. Without them it works for one night and becomes miserable across a week.","Level ground matters more than it sounds, and a slight slope that is unnoticeable when parked becomes obvious once lying down. Turning the vehicle around is often enough to fix it.","For longer trips, a small van or a wagon with the seats folded gives far more usable room than a sedan for very little extra hire cost.","Australian summer heat makes an unventilated car genuinely unsafe overnight, which is the practical limit on this approach rather than any local law."],["Screens and shades change everything","Level ground matters when lying down","Turning around often fixes a slope"])] }),
  article({ slug:"driving-in-australia-overseas-licence", title:"Driving in Australia with an overseas licence", description:"Licence rules differ between states and territories, especially for longer stays.", category:"Rules & safety", region:"Australia", readTime:8, places:["Sydney","Melbourne","Brisbane","Perth"], imageAlt:"Campervan driving on an Australian road", intro:"International visitors can often drive on a current overseas licence for a limited period, but each state and territory sets its own conditions.", sections:[section("Check every jurisdiction",["Confirm the rule with the transport authority for each state or territory on the route. Residency, visa status and length of stay can change what is required.","Carry the original licence. If it is not in English, bring an accepted English translation or International Driving Permit as required." ]),section("Vehicle class and rental terms",["Your licence must cover the vehicle class and weight. A motorhome can be larger than the passenger vehicle you normally drive.","Rental agreements can prohibit unsealed roads, beaches, floodwater and driving after dark. Insurance may not cover a breach."], ["Current licence","Translation or IDP","Rental exclusions read"]),section("Australian road habits",["Drive on the left, learn local roundabout rules and leave more braking distance in a heavy vehicle. Long rural distances make fatigue a major risk.","Stop before tiredness becomes obvious. Avoid dawn and dusk on wildlife-heavy roads."]),section("Rental company conditions sit on top of the law",["Even where the law permits you to drive, rental companies apply their own rules: a minimum age, a licence held for a minimum period, young driver surcharges and sometimes refusal of licences from particular countries.","Confirm these at booking rather than at the counter. Being refused a vehicle at an airport depot after a long flight is a genuinely difficult problem to solve.","Many agreements also prohibit specific roads, unsealed surfaces and beach driving entirely, with damage on them uninsured. Read those clauses before planning a route."],["Confirm licence conditions at booking","Young driver surcharges are common","Unsealed road exclusions are widespread"]),section("Translations and international permits",["A licence not in English needs an accurate English translation or an International Driving Permit, carried alongside the original. The permit supports the licence rather than replacing it, so both must be present.","Get the permit in your home country before travelling, because it generally cannot be issued once you have arrived. It is inexpensive and quick to obtain from the relevant motoring authority.","Carry both documents in the vehicle at all times. Police can require them at a roadside stop and being unable to produce them is an offence in its own right."],["IDP supports, never replaces, the licence","Obtain the IDP before you travel","Carry both documents always"]),section("Vehicle class and campervans",["A standard car licence in most Australian states covers vehicles up to 4.5 tonnes gross vehicle mass and twelve occupants including the driver. Larger motorhomes require a light rigid or medium rigid class.","Your home licence class determines the Australian equivalence, and a car licence in one country does not automatically cover a 4.5 tonne vehicle. Check before booking a large motorhome.","Towing adds further constraints. The combination weight, not just the vehicle, determines what class you need, and exceeding it affects insurance as well as legality."],["Car licence usually covers 4.5 tonnes","Large motorhomes may need a higher class","Towing is assessed on combination weight"]),section("Insurance and what excess reduction covers",["Rental excess amounts in Australia are typically high, frequently several thousand dollars. Excess reduction products lower it but commonly exclude windscreens, tyres, undercarriage, water damage and single-vehicle accidents.","Those exclusions cover most of what actually happens on Australian roads, particularly on gravel. Read what is excluded rather than what is covered, and price a separate policy if the exclusions matter.","Third party injury cover works differently from many countries and varies by state. Compulsory third party insurance is included with registration, but property damage to others is not automatically covered."],["Excess is often several thousand dollars","Glass and tyres are usually excluded","Read exclusions, not inclusions"]),section("Roadside assistance and breakdowns",["Check whether roadside assistance is included with your rental and what it covers in remote areas, because many policies limit towing distance and remote recovery is extremely expensive.","Carry the assistance number written down as well as in a phone, and be able to describe your location using the nearest roadside marker or landmark. In remote areas, staying with the vehicle is always the right decision.","Take photographs of your licence, permit and rental agreement and store them separately, so a lost wallet does not also end the driving part of the trip.","Rental agreements commonly exclude unsealed roads entirely, so confirm what your vehicle is permitted to drive on before planning a route through gravel country."],["Check remote towing limits","Write the assistance number down","Stay with the vehicle"])], sources:[{label:"Australian Government road transport information",url:"https://www.infrastructure.gov.au/infrastructure-transport-vehicles/roads/road-transport-information"}] }),
  article({ slug:"interstate-biosecurity-road-trip", title:"Interstate biosecurity for Australian road trips", description:"Fruit, vegetables, honey, plants, soil and camping gear can be restricted at state borders.", category:"Rules & safety", region:"Australia", readTime:8, places:["Ceduna","Mildura","Kununurra","Devonport"], imageAlt:"Australian interstate quarantine checkpoint sign", intro:"Australia has quarantine zones within the country. Carrying the wrong produce or dirty equipment can spread pests and lead to an on-the-spot fine.", sections:[section("Check before shopping",["Rules vary by product, origin and destination. Check the official traveller information before crossing a state or quarantine-zone border.","Fresh fruit, vegetables, honey, plants and soil are common concerns. Restrictions can apply even when the item was bought in an Australian supermarket." ]),section("Use quarantine bins",["Eat allowed produce before the border or place restricted items in a quarantine bin. Do not hide food in the vehicle or leave it beside the road.","Keep receipts and packaging when official advice says a commercially treated product is permitted."], ["Check the next border","Separate produce","Clean gear"]),section("Clean camping equipment",["Remove soil, seeds and plant material from boots, tents, bikes and recovery gear. Dry water equipment before moving between catchments where required.","Clean gear also lasts longer and avoids carrying ants, weeds and pathogens into the next campground."]),section("Fruit fly zones are the main issue",["South Australia, Tasmania and parts of Victoria and New South Wales maintain fruit fly exclusion zones. Carrying fresh fruit and some vegetables into them is prohibited, with disposal bins provided at borders and checkpoints operating.","Fines apply whether or not you knew, and inspections at the South Australian border and the Tasmanian ferry terminal are routine. Detector dogs work some crossings.","The practical approach is to plan shopping around the borders: run the fridge down before a crossing and restock immediately after. This costs nothing and removes the problem entirely."],["Run the fridge down before a border","Bins provided at crossings","Fines apply even if unaware"]),section("Tasmania and Western Australia",["Tasmania restricts fresh produce, plants, soil, honey and used beekeeping equipment on arrival by ferry or air. The rules protect an island free of several mainland pests and are enforced at the terminal.","Western Australia operates quarantine checkpoints on eastern approaches including the Eyre Highway, restricting fruit, vegetables, honey, plants and soil. This catches travellers who stocked up before crossing the Nullarbor.","Both jurisdictions publish current restricted item lists that change with outbreaks. Check before travelling rather than relying on what applied on a previous trip."],["Tasmania checks at the ferry terminal","WA checkpoints on the Eyre Highway","Lists change with outbreaks"]),section("Soil, gear and weeds",["Soil on boots, tent pegs, bicycles and vehicles moves plant pathogens and weed seeds between regions. Phytophthora dieback in Western Australia is spread this way and has devastated large areas of native vegetation.","Clean footwear and gear between regions, use the cleaning stations provided at park entrances in dieback areas, and stay on formed tracks and roads where signage asks you to.","Firewood also moves pests. Several regions restrict moving firewood, and buying local rather than carrying a load across state lines is the safer practice."],["Clean boots between regions","Use dieback cleaning stations","Buy firewood locally"]),section("Why it matters",["Australia's agricultural industries are free of many pests present elsewhere, and that status depends on internal barriers as much as international ones. A single fruit fly outbreak can cost a region's growers their export markets.","For native ecosystems the stakes are similar. Dieback, myrtle rust and weed incursions have permanently altered large areas, and most of that movement was human-assisted and avoidable.","Complying costs a few minutes and some planning around shopping. Treat the bins at a border as a normal part of a road trip rather than an inconvenience."],["One outbreak can close export markets","Most pest movement is human-assisted","Plan shopping around borders"]),section("Planning the fridge around borders",["Run fresh produce down in the days before a quarantine crossing and restock immediately after. This costs nothing, avoids buying food twice and removes the risk of a fine entirely.","Cooked and processed food is generally fine, so a meal plan built around tinned, dried and cooked items across a border day works well. Check the current restricted list rather than guessing which items count.","Quarantine bins at borders are provided precisely so you can comply without penalty, and using one is treated very differently from being found with undeclared produce.","Restricted item lists change with outbreaks, so check the current position rather than relying on what applied on a previous trip."],["Run the fridge down before crossing","Cooked and processed food is usually fine","Check the current restricted list"])], sources:[{label:"Australian Government: travelling within Australia",url:"https://www.agriculture.gov.au/biosecurity-trade/travelling/within-australia"}] }),
  article({ slug:"camping-with-dogs-australia", title:"Camping with dogs in Australia", description:"Find dog-friendly stays without assuming pets are welcome in parks or shared campgrounds.", category:"Camping guides", region:"Australia", readTime:8, places:["Dog-friendly caravan parks","State forests","Private campgrounds"], imageAlt:"Dog resting beside a tent at a pet-friendly campground", intro:"A dog-friendly road trip needs a route built around permitted camps, safe exercise, heat and wildlife. National parks commonly prohibit pets.", sections:[section("Choose the right land",["Check the exact campground rule and any lead requirement. A listing marked dog-friendly may still exclude pets from cabins, beaches, trails or peak periods.","Never take a dog into a prohibited national park, even if it remains inside the vehicle." ]),section("Heat and travel",["A parked vehicle becomes dangerous quickly. Plan walks for cool hours, carry more water than usual and choose shade before arrival.","Secure the dog safely while driving and build rest breaks around places where exercise is allowed."], ["Lead and long line","Water bowl","Tick prevention","Waste bags"]),section("Wildlife and other campers",["Keep the dog controlled around kangaroos, livestock, snakes and ground-nesting birds. Do not allow barking or roaming to disturb neighbouring sites.","Collect waste every time, including in remote areas. Ask before approaching another camper or dog."]),section("National parks generally exclude dogs",["Dogs are prohibited in almost all Australian national parks, in every state, because of the risk to native wildlife and because many parks use 1080 baiting. This is the single biggest constraint on camping with a dog here.","State forests, regional parks, council reserves and private campgrounds are the workable alternatives, and many permit dogs on lead. Some state forests allow dogs off lead outside baiting periods.","Plan the route around dog-friendly places first rather than hoping to improvise. A standard national park itinerary with a dog produces a trip where somebody waits in the vehicle constantly."],["Dogs banned in almost all national parks","State forests are the usual alternative","Plan the route around dog-friendly stops"]),section("1080 baiting is the serious risk",["Sodium fluoroacetate, known as 1080, is used widely for fox, wild dog and rabbit control and is lethal to dogs in tiny quantities. Poisoning can occur from eating bait or from scavenging a poisoned carcass months later.","Baited areas are signed at access points and operations are published in advance by state agencies. Check before entering any state forest, reserve or pastoral area with a dog.","There is no reliable field antidote and death is distressing and rapid. Keep dogs leashed and muzzled in baited areas, or better, avoid those areas entirely."],["1080 kills dogs in tiny amounts","Risk persists in carcasses for months","Check baiting notices before entering"]),section("Heat and vehicles",["Heat in a parked vehicle kills dogs quickly, and shade moves through the day. An Australian summer makes leaving a dog in a vehicle unsafe even briefly, which rules out most attractions that exclude dogs.","Hot ground burns paws. Bitumen and sand reach temperatures that cause serious burns, and the test is whether you can hold the back of your hand on the surface for several seconds.","Carry more water for the dog than you think you need and offer it frequently. Dogs dehydrate faster than people in this climate and show it later."],["Never leave a dog in a parked vehicle","Test ground temperature with your hand","Carry extra water for the dog"]),section("Wildlife, ticks and snakes",["Paralysis ticks along the east coast are potentially fatal to dogs and preventatives are essential rather than optional in that region. Check the dog daily, particularly around the head, neck and ears.","Snakes are a genuine risk and dogs frequently investigate them. Keep dogs on lead in bush and long grass, and know where the nearest veterinary clinic with antivenom is on remote legs.","Cane toads across the north are toxic if mouthed and cause rapid poisoning. In toad country, supervise dogs closely at night when toads are most active."],["Tick preventatives on the east coast","Keep dogs leashed in long grass","Cane toads are toxic if mouthed"]),section("Snakes, ticks and emergency vets",["Snake bite in dogs is a genuine risk in warm months and requires immediate veterinary treatment. Know where the nearest clinic with antivenom is before heading somewhere remote, because time is the deciding factor.","Paralysis ticks on the east coast require preventatives and daily checking. In remote areas, the nearest vet may be hours away, which changes the risk calculation for taking a dog at all.","Where a national park is unavoidable, kennels and day-boarding operate in most regional towns and are usually inexpensive for a single day.","1080 baiting notices are published in advance by state agencies, and checking them before entering any forest or reserve with a dog is essential."],["Know the nearest vet with antivenom","Daily tick checks on the east coast","Remote areas change the risk"])] }),
  article({ slug:"caravan-park-vs-holiday-park", title:"Caravan park vs holiday park vs campground", description:"Choose the right mix of facilities, price and atmosphere for each night.", category:"Camping guides", region:"Australia", readTime:7, places:["Caravan parks","Holiday parks","Bush campgrounds","Roofed accommodation"], imageAlt:"Caravan park beside an Australian beach", intro:"The labels overlap, but the experience can be very different. Match the stay to what the trip needs that night rather than chasing one type for the whole route.", sections:[section("Caravan and holiday parks",["Caravan parks focus on powered and unpowered sites, amenities and vehicle access. Holiday parks often add pools, playgrounds, cabins and a more resort-like feel.","Ask about site length, surface, power connection, check-in time and whether facilities are seasonal." ]),section("Bush campgrounds",["National park and forest campgrounds trade services for location. Toilets may be basic, water may be untreated or absent and generators can be restricted.","Check road access and booking before driving in. A cheaper fee can cost more if the setup is unsuitable."], ["Power needed?","Potable water?","Shower or laundry?","Vehicle length?"]),section("Use a mixed strategy",["A simple bush camp followed by a powered holiday park makes laundry, charging and water refills easier. Roofed accommodation can rescue a route during severe weather.","Budget for a few service nights instead of expecting every camp to provide everything."]),section("What the names actually mean",["The terms are largely interchangeable in Australia and describe the same product: a commercial park with powered and unpowered sites, amenities blocks, and usually cabins. Holiday park tends to signal more facilities aimed at families.","What matters is the specification rather than the name: whether sites are powered, whether the amenities are modern, whether there is a camp kitchen, laundry, pool and dump point, and what the site dimensions are.","Chains and membership schemes discount nightly rates and on a long trip the membership frequently pays for itself. Check whether your home motoring association has a reciprocal arrangement first."],["The names mean much the same thing","Judge by specification, not label","Membership discounts add up quickly"]),section("Where each type earns its place",["A commercial park is worth paying for after several nights of free camping, before an early start, in bad weather, or when laundry, hot showers, charging and water all need attention at once. Counted against the jobs it replaces it is usually good value.","National park and conservation campgrounds cost less and give you the setting, at the price of self-sufficiency and usually no power. Free camps and rest areas cost nothing and provide nothing.","The pattern most long-trip travellers settle on is two or three low-cost nights followed by one serviced night that resets everything. That balance keeps both the budget and the vehicle workable."],["Serviced night resets the whole vehicle","National parks give setting, not services","Two or three cheap nights, then one paid"]),section("Booking and peak season",["Coastal parks in school holidays, at Easter and over Christmas book out months ahead, impose minimum stays and charge substantially more. Some run ballots or long-standing repeat bookings that make new bookings very difficult.","Declare your vehicle length accurately, because sites are allocated by size and under-declaring produces an awkward conversation at check-in. Say if you need drive-through access or are towing.","Ask about late arrival when booking. Most parks close reception in the evening and leave an envelope with a gate code, but you need that information before standing at a locked boom gate."],["Coastal parks book months ahead","Declare vehicle length accurately","Ask the late arrival procedure"]),section("Shared space and the amenities",["Quiet hours are enforced and parks are dense environments where sound carries. Keep to your site boundary, supervise children around internal roads and pools, and check the pet policy before arriving with a dog.","Use the camp kitchen and laundry deliberately, because they are what you are paying for. A single evening can clear a week of washing, charge everything and refill water while emptying waste in the right order.","Never fill drinking water from a tap near the dump point, and ask which taps are potable. Not all of them are, and the signage is not always obvious."],["Quiet hours are enforced","Check pet policy before arriving","Ask which taps are potable"]),section("Reading reviews usefully",["Review scores tell you less than the specific complaints. Repeated mentions of amenity cleanliness, road noise, site size or management attitude are the signals worth acting on.","Photographs from guests are more reliable than the park's own. Look for the site type you are booking rather than the pool and the playground, which every park photographs well.","Ask about a powered site's amperage if you intend to run air conditioning, because some older parks supply less than a modern van draws.","Ask about the late arrival procedure when booking, because most parks close reception in the evening and a locked boom gate at ten is a poor end to a driving day."],["Read complaints, not scores","Guest photos beat marketing shots","Look for your site type specifically"])] }),
  article({ slug:"dump-points-australia-guide", title:"How to find and use dump points in Australia", description:"Dispose of blackwater and greywater legally, cleanly and without blocking the next traveller.", category:"Camping guides", region:"Australia", readTime:7, places:["Public dump points","Caravan parks","Roadhouses"], imageAlt:"Public dump point for caravans", intro:"Wastewater belongs in an approved dump point, not a drain, bush, beach or campground toilet. Plan disposal before the tank is full.", sections:[section("Find a compatible point",["Public dump points can sit at caravan parks, visitor centres, showgrounds and roadside facilities. Check access hours, vehicle clearance and whether a key or fee is required.","A location can close for maintenance. Keep a second option on long routes." ]),section("Carry the right kit",["Use a secure hose and fittings that match the vehicle. Wear gloves, keep potable-water equipment separate and never use the drinking-water tap to rinse a waste hose.","Position the vehicle without blocking traffic, then follow the posted sequence."], ["Waste hose","Dedicated rinse hose","Gloves","Disinfectant"]),section("Leave it ready",["Rinse only as instructed, close lids and clean any spill immediately. Report a blockage instead of forcing more waste into it.","Never empty chemical toilet products into a system that prohibits them."]),section("Finding one before you need it",["Dump points are widely distributed at caravan parks, council facilities, service stations, rest areas and visitor centres, and most are free or charge a small fee. The habit that prevents problems is identifying the next one on your route rather than searching when a tank is full.","Caravan park dump points are often available to non-guests for a small charge, which is worth knowing on a long remote leg. Some are locked overnight, so arriving late with a full cassette is a planning failure.","In remote areas the gaps are substantial and some towns have none at all. On outback routes, plan the dump stop as deliberately as you plan fuel."],["Identify the next point in advance","Parks often serve non-guests for a fee","Remote gaps can be hundreds of kilometres"]),section("Using one correctly",["Park so other vehicles can pass, because dump points are frequently on a single access lane. Empty black water first, rinse, then grey water, and rinse the area afterwards rather than leaving it for the next person.","Keep the drinking water hose completely separate from anything used at the dump point, and never fill fresh water from a tap there unless it is explicitly marked potable. Wash your hands before touching anything in the vehicle.","Use only chemicals compatible with the receiving system. Many rural dump points feed septic tanks and harsh formaldehyde products damage the biological process that makes them work."],["Black water first, then rinse, then grey","Keep hoses strictly separate","Use septic-safe chemicals"]),section("What not to do and the penalties",["Emptying into a stormwater drain discharges directly to waterways with no treatment. Public toilets are not designed for cassette volumes and block. Emptying onto ground or into bush is the offence that draws the largest fines.","Penalties for illegal waste discharge are significantly higher than ordinary camping infringements and can run into thousands of dollars, with environmental protection legislation applying in several states.","It is also the behaviour most likely to close a free camping area permanently. Councils photograph it, residents report it, and the site closes for everyone."],["Stormwater drains go straight to waterways","Fines run into thousands","It closes free camps permanently"]),section("Building it into the routine",["The travellers who never have a waste problem empty on a schedule rather than on demand, typically whenever they pass a facility with tanks more than half full. That single habit removes almost every awkward situation.","Know your capacity in days rather than litres: how long the fresh water lasts, how long before grey needs attention, how many days the toilet supports at your party size. Those numbers determine how far off grid you can go.","Carry a spare cassette if your setup allows it. On remote legs it effectively doubles your range and costs very little."],["Empty on schedule, not on demand","Know capacity in days, not litres","A spare cassette doubles remote range"]),section("Cassette versus fixed tank",["A cassette toilet can be carried to the dump point, which means you can use facilities without moving the vehicle and can empty at a public toilet designed to accept them where signage permits.","A fixed black tank requires driving to a dump point and positioning over it. That difference matters when choosing a vehicle, because a cassette gives more flexibility in towns and at busy facilities.","Carry disposable gloves and hand sanitiser with the waste equipment, because handwashing facilities at dump points are not guaranteed.","Some dump points are locked overnight, so arriving late with full tanks is a planning failure rather than bad luck."],["Cassettes can be carried to the point","Fixed tanks need the vehicle positioned","Cassettes offer more town flexibility"])] }),
  article({ slug:"camping-water-planning", title:"Water planning for remote camping", description:"Carry enough for drinking, cooking and delays, then verify every refill before relying on it.", category:"Camping guides", region:"Australia", readTime:8, places:["Potable water filling","Roadhouses","Visitor centres"], imageAlt:"Water containers packed for remote camping", intro:"Water planning starts with the longest gap between confirmed potable supplies, then adds margin for heat, walking and a delayed day.", sections:[section("Calculate a real allowance",["Count drinking, cooking and basic hygiene for every person. Hot weather, altitude and physical work increase demand quickly.","Do not reduce drinking water to protect a low tank. Reduce washing or leave the route earlier." ]),section("Confirm the source",["A tap icon does not always mean potable water. Read signs, ask the manager and treat uncertain natural water before use.","Remote tanks can run dry or be reserved for emergencies. Carry enough to reach the next confirmed source."], ["Separate drinking reserve","Food-safe containers","Treatment method","Refill backup"]),section("Store it safely",["Use several containers rather than one large tank so a leak does not remove the whole supply. Secure heavy water low in the vehicle.","Clean containers between trips and keep fuel, waste hoses and chemicals away from drinking-water equipment."]),section("How much you actually need",["Plan on a minimum of four to five litres per person per day for drinking and cooking in temperate conditions, and considerably more in the heat. In outback summer, seven to ten litres per person per day is realistic.","That is drinking and cooking only. Washing, dishes and any showering come on top, which is why a vehicle tank empties faster than the arithmetic suggests.","Always carry a reserve that is not part of the working supply, ideally in a separate container. A vehicle breakdown in remote country turns water from a convenience into the thing that keeps you alive."],["Four to five litres per person per day minimum","Seven to ten in outback heat","Keep a separate untouched reserve"]),section("Where you can refill",["Towns, caravan parks, visitor centres and many rest areas have potable water, but not every tap is drinkable and signage is not always present. Where a supply is untreated or uncertain, treat it rather than assuming.","Bore water in inland Australia is common and frequently high in minerals or salts. It may be safe but unpleasant, or unsuitable for drinking entirely, and signage usually says which.","In remote areas, tanks at campgrounds are rainwater and their condition varies. Carry the means to treat water rather than relying on any single source being available and clean."],["Not every tap is potable","Bore water is often unsuitable","Carry treatment for remote tanks"]),section("Treating water in the field",["Boiling for one minute is the most reliable method and needs no equipment beyond a stove. Filters rated for protozoa and bacteria handle most Australian surface water, and chemical treatment works but takes time and affects taste.","Surface water in agricultural country can carry chemical contamination that filtering does not remove. Prefer tank or town water where available and treat creek water as a last resort in farmed areas.","In the tropics, avoid drawing water from any waterway that could hold crocodiles. This is a bigger practical constraint on water sourcing in the north than contamination is."],["Boiling one minute is most reliable","Filters do not remove chemicals","Crocodile risk limits sourcing up north"]),section("Storage and hygiene",["Use food-grade containers, keep them out of direct sun and rinse them regularly. Water stored in a warm vehicle for weeks develops taste and biological growth, particularly in a partially full tank.","Keep drinking containers and hoses physically separate from anything used near a dump point, and store hose ends off the ground. This is the single habit that prevents most illness on a self-contained trip.","Sanitise the tank periodically with a proper tank cleaning product, particularly before a long trip or after the vehicle has sat unused. It takes an afternoon and prevents a week of trouble."],["Food-grade containers, out of the sun","Store hose ends off the ground","Sanitise tanks before long trips"]),section("Reducing what you use",["Washing dishes in a bowl rather than under a running tap, using a spray bottle for rinsing and showering with the water off between wetting and rinsing all extend a tank substantially.","Grey water usually fills before fresh water empties, so reducing use extends both at once. On a long remote leg that difference can be a day or two of additional range.","Label containers clearly and consistently, because the one mistake that causes real illness is filling a drinking container from a non-potable source in a hurry.","Sanitise the water tank before a long trip and after the vehicle has sat unused, because it takes an afternoon and prevents a week of trouble."],["A bowl beats a running tap","Grey fills before fresh empties","Small habits add a day of range"])] }),
  article({ slug:"camping-packing-list-australia", title:"Australia camping packing list", description:"Pack for heat, cold, insects, long drives, simple meals and nights beyond reception.", category:"Trip planning", region:"Australia", readTime:9, places:["Campgrounds","Roadside rest areas","Outdoor recreation areas"], imageAlt:"Camping equipment packed beside a vehicle", intro:"The best packing list matches the route and the vehicle. Start with safety and sleep, then add comfort only while space and payload allow.", sections:[section("Sleep and shelter",["Pack a shelter suited to wind and rain, a ground layer, insulation and a sleeping bag for the coldest expected night. Test every pole, valve and zipper before leaving.","Carry a headlamp per person and keep one accessible before camp is set up." ]),section("Water, food and cooking",["Use food-safe water containers, a simple stove where permitted and meals that remain useful if weather delays the trip. Store food away from wildlife.","Check fire and gas restrictions. Never cook or run a fuel appliance in an enclosed sleeping space."], ["Water reserve","First-aid kit","Headlamps","Weather layers","Waste bags"]),section("Vehicle and communication",["Bring the correct spare tyre, jack, wheel tool, tyre gauge and basic fluids. Remote routes may require recovery gear and satellite communication.","Download bookings, emergency contacts and route notes. Tell someone when to expect the next check-in."]),section("Sun and heat gear is not optional",["Australia has among the highest UV levels anywhere and burning takes minutes rather than hours, including on overcast days. A broad-brimmed hat, high-factor sunscreen, sunglasses and long lightweight sleeves belong in the day bag rather than the boot.","Carry more water capacity than the trip appears to need, plus a separate reserve container. Water is the item whose absence turns a breakdown into an emergency, and it weighs nothing until you need it.","Shade is equipment. A tarp or awning transforms a campsite in the north and inland, where the difference between sun and shade is the difference between usable and unbearable."],["UV burns in minutes here","Separate reserve water container","A tarp is genuinely essential"]),section("Insects, snakes and first aid",["Repellent with DEET or picaridin, insect screens and a head net cover mosquitoes, flies and midges. Bush flies inland in summer are relentless enough that a head net stops being funny within a day.","Carry compression bandages for snake bite, at least two, and know the pressure immobilisation technique. Antivenom exists for all Australian snakes but getting to it is the problem, so the bandage is what buys the time.","A proper first aid kit, any personal medication in sufficient quantity, and a card noting allergies and conditions all matter more when the nearest hospital is hours away."],["Head net for inland bush flies","Two compression bandages minimum","Learn pressure immobilisation"]),section("Vehicle and recovery equipment",["Confirm the spare, jack and wheel brace are present and that you know the jacking points before leaving, because rental vehicles frequently arrive missing one. On gravel routes, two spares is the standard rather than the cautious option.","A tyre repair kit, a compressor and a tyre gauge cover the most common problem on unsealed roads. Lowering pressures for corrugations and reinflating afterwards is basic outback practice.","For remote travel add recovery boards, a snatch strap with rated recovery points, jumper leads and basic tools. None of it helps without knowing how to use it, so practise before you need to."],["Two spares on gravel routes","Compressor and gauge for pressures","Practise recovery before you need it"]),section("Communication and navigation",["Mobile coverage disappears across most of inland Australia and much of the coast between towns. A personal locator beacon or satellite messenger is standard equipment for remote travel and cheap to hire.","Carry offline maps and, for genuinely remote routes, paper maps as a backup. Phone navigation with no downloaded data and no signal is worse than useless because it invites false confidence.","Tell someone your route and expected arrival, and update them when it changes. That single habit is what triggers a search at the right time rather than days later."],["Hire a PLB for remote legs","Download offline maps in advance","Tell someone your route"]),section("What to leave at home",["Excessive clothing, duplicated cookware and speculative gear are the three things that fill a vehicle without earning their space. Most trips use a fraction of what is packed.","Weight matters for fuel and for handling, particularly in a campervan. Packing lighter improves consumption, stability and the amount of time spent moving things to reach something else.","Do a shakedown night close to home before a long trip if you can, because it exposes the missing items while they are still easy to buy.","Compression bandages for snake bite are the single most important item most travellers leave out, and two of them weigh almost nothing."],["Most trips use a fraction of the gear","Weight costs fuel and handling","Duplicated cookware is the usual culprit"])] }),
  article({ slug:"campervan-road-trip-budget-australia", title:"Australia campervan road trip budget", description:"Budget for the vehicle, fuel, camps, food, park fees and a contingency that can absorb change.", category:"Trip planning", region:"Australia", readTime:8, places:["Holiday parks","Free camps","National parks","Fuel stops"], imageAlt:"Campervan beside an Australian coastal road", intro:"The cheapest nightly camp does not create the cheapest trip. Distance, fuel consumption, insurance and service nights usually matter more.", sections:[section("Fixed vehicle costs",["Include rental or ownership, insurance excess reduction, extra drivers, bedding, chairs and one-way fees. Read kilometre limits and prohibited-road terms.","For an owned vehicle, budget servicing, tyres, registration and roadside assistance across the whole travel period." ]),section("Daily costs",["Estimate fuel using the vehicle's real consumption under load, not the brochure figure. Add camps, groceries, laundry, gas, park entry and paid activities.","Mix free or low-cost camps with powered nights for showers, charging and washing."], ["Vehicle","Fuel","Camps","Food","Park fees","Contingency"]),section("Keep a repair margin",["Hold money aside for a tyre, windscreen, towing, changed ferry or emergency accommodation. Do not spend the contingency on optional activities in week one.","Slower travel cuts fuel and creates room for free days that still feel like a holiday."]),section("Price the vehicle as a package",["Compare quotes on identical dates, vehicle class, insurance excess, kilometre allowance and included equipment. A low headline rate with a five thousand dollar excess and a daily kilometre cap is a different product from a slightly dearer one without them.","Then add what is quoted separately: one-way fees, additional drivers, bedding and kitchen packs, airport transfers and the cost of reducing the excess. These routinely add several hundred dollars to a fortnight.","Check the bond arrangement too. Most operators hold a substantial amount on a credit card, which reduces the credit available for fuel and campsites during the trip."],["Compare excess, not daily rate","One-way fees can be large","The bond ties up your credit"]),section("Fuel is the line that dominates",["Australian distances make fuel the largest variable cost after the vehicle. Calculate it properly: kilometres times litres per hundred, divided by a hundred, times the price per litre, then add fifteen percent for detours.","A campervan at twelve litres per hundred covering five thousand kilometres uses six hundred litres. That arithmetic matters far more than the difference between a twenty and a forty dollar campsite.","Remote roadhouse fuel carries a substantial premium and there is no avoiding it. Budget for the higher price on outback legs rather than assuming city averages."],["Add 15 percent for detours","Fuel beats campsite cost easily","Budget remote fuel at a premium"]),section("Accommodation mix and the real pattern",["A trip built entirely on free camping still pays for showers, laundry, water and dump points somewhere. One built entirely on caravan parks costs several times more and gains little on nights when you arrive late and leave early.","The pattern that works is two or three low-cost or free nights followed by one serviced night that resets laundry, water, waste and charging together. Costed against the jobs it replaces, the serviced night usually earns its rate.","National park camping sits between the two: cheap, scenic and usually without power. Booking fees and vehicle entry are frequently separate, so check both."],["Free camping still has costs","Two or three cheap nights, then one paid","Park entry is often separate"]),section("Keeping the budget honest",["Track actual spending for the first three or four days and compare against the plan. The lines that drift are almost always food, coffee and paid activities rather than accommodation, and they are the easiest to correct early.","Hold a genuine reserve for the things no plan includes: a tyre, a windscreen, a mechanical issue, a weather day that forces a cabin. A budget with no slack turns every small problem into a decision about continuing.","Catching a twenty percent overrun in week one means trimming a few meals out. Discovering it in week four means cancelling the part of the trip you most wanted."],["Track spending in week one","Food and coffee drift, not camps","Hold a real contingency"]),section("Shoulder season is the biggest saving",["Travelling immediately outside school holidays and peak season reduces vehicle hire, accommodation and campground rates simultaneously, frequently by a third or more.","It also improves availability, which means less need to book inflexibly ahead. For a flexible traveller this single choice saves more than every other economy combined.","Track spending in a simple shared note rather than an app, because the point is that everyone in the vehicle can see it rather than the sophistication of the tool.","Shoulder season reduces vehicle hire, campground rates and accommodation simultaneously, which makes the timing decision worth more than every other economy combined."],["Shoulder season cuts every line at once","Availability improves too","Beats every other saving combined"])] }),
  article({ slug:"best-time-camping-australia", title:"Best time to camp around Australia", description:"Match the route to Australia's climate zones instead of looking for one perfect national month.", category:"Trip planning", region:"Australia", readTime:8, places:["Top End","Red Centre","Tasmania","East Coast"], imageAlt:"Seasonal Australian camping landscape", intro:"Australia can be cold, tropical, flooded, windy and in fire season at the same time. The best month depends on where the road goes.", sections:[section("Tropical north",["The Top End, Kimberley and tropical Queensland are generally easiest in the dry season, roughly May to October. Popular camps fill and nights can still be warm.","The wet season brings humidity, storms, flooding and road closures. Some places become inaccessible." ]),section("South and the alpine regions",["Southern coasts and Tasmania have longer days in summer, but school holidays, fire danger and wind affect camps. Spring and autumn can be quieter with colder nights.","Alpine roads and campgrounds close seasonally. Snow or cold fronts can arrive outside winter."], ["Dry-season north","Shoulder-season coasts","Road openings checked"]),section("Desert and outback",["Travel the Red Centre, Nullarbor and inland ranges in cooler months where possible. Summer heat can make walking unsafe and vehicle problems more serious.","Check the route's historical climate, then use current forecasts and warnings close to departure."]),section("The country runs on two opposite seasons",["Northern Australia works in the dry season from May to October and is difficult in the wet from November to April. Southern Australia works in spring, summer and autumn, and is cold and wet in winter.","That inversion is the single most useful planning fact here. A winter trip means going north; a summer trip means going south or into the highlands. Trying to do both in one season produces the worst of each.","The shoulder months, roughly April to May and September to October, are when the largest part of the country is comfortable at once. They are the best windows for a long crossing."],["North is dry May to October","South suits spring to autumn","Shoulder months suit long trips"]),section("School holidays and the crowds",["Australian school holidays fall around Christmas and January, at Easter, and for two-week blocks in April, July and September or October, staggered slightly between states. Coastal campgrounds fill completely in those windows.","The July holidays coincide with peak northern dry season, which is why Broome, Exmouth, Cairns and Darwin are at their busiest and most expensive then. Booking months ahead is required.","Travelling immediately after a holiday block gives you good weather with a fraction of the people and lower prices. It is the single easiest way to improve a trip."],["Holiday blocks stagger between states","July peaks in the north","Travel just after a holiday block"]),section("Regional timing in short",["Tasmania and the alpine areas are summer destinations, roughly December to March, with snow possible outside that. The Red Centre is best in winter, with cold nights and comfortable days.","Western Australia's south west peaks with the wildflowers from August to November, while the north west works from May to October. The Kimberley and the Gibb River Road are strictly dry season.","The east coast is workable year round, shifting north in winter and south in summer. Queensland's tropical north follows the northern pattern rather than the coastal one."],["Tasmania and alps: summer","Red Centre: winter","Kimberley: dry season only"]),section("Cyclones, fire and flood seasons",["Cyclone season runs November to April across the northern coast and can close roads and towns with days of warning. Monitor warnings daily if travelling in that window.","Bushfire season peaks in summer in the south and east and in the dry season in the north. Fire danger ratings are published daily and should shape where you camp rather than being checked afterwards.","Flooding follows the wet in the north and severe storms in the south. Both close roads for days, and both are reasons to keep flexibility rather than a fixed schedule in those seasons."],["Cyclones November to April","Fire seasons differ north and south","Keep schedule flexibility in wet months"]),section("Planning a long lap around the seasons",["The classic big lap runs anticlockwise, heading north for winter and returning south for summer, which keeps you in comfortable weather almost year round.","That direction also matches the dry season in the north and avoids cyclone season in the Kimberley. Travelling the opposite way puts you in the tropics during the wet, which is the common planning mistake.","Public holidays vary by state and several are region-specific, so check the calendar for the states on your route rather than assuming a national pattern.","School holiday dates stagger between states, so a week that is quiet in one state can be peak season across the border."],["Anticlockwise follows the weather","North in winter, south in summer","Clockwise hits the tropics in the wet"])] }),
  article({ slug:"first-campervan-trip-australia", title:"Your first campervan trip in Australia", description:"Choose an easy first route, learn the vehicle and practise the daily routine before going remote.", category:"Trip planning", region:"Australia", readTime:8, places:["Powered sites","Holiday parks","National park campgrounds"], imageAlt:"Small campervan at an Australian campground", intro:"The first trip should teach the vehicle without punishing mistakes. Stay near services, keep driving days short and do one full setup before dark.", sections:[section("Learn the vehicle at handover",["Ask how to use power, water, gas, the fridge, wastewater, roof, awning and toilet. Photograph the controls and existing damage.","Check the vehicle height, length, fuel type and emergency numbers before leaving the depot." ]),section("Use an easy first night",["Book a powered site within a short drive. Set up in daylight, cook one meal and work out where wet gear and rubbish belong.","Fix small problems before a remote leg. A missing hose fitting is easy near a town and miserable after dark."], ["Height written down","Fuel type confirmed","Bed tested","Water system understood"]),section("Drive less than you think",["A campervan is slower to park, pack and resupply than a car. Two or three hours of driving can still fill a travel day.","Avoid night driving and choose a legal backup camp before the preferred site becomes urgent."]),section("The handover is the most important half hour",["Walk the vehicle with the operator and photograph every existing mark inside and out, with the odometer and fuel gauge visible. This is what prevents a dispute at return, and disputes are common.","Have them show you the water filling, waste emptying, gas, power, fridge switching between mains and battery, and the awning. Write the height on something visible from the driver's seat.","Ask what the vehicle is not allowed to do: which roads are excluded, whether unsealed surfaces are permitted, and what happens if you break down. Those answers shape the whole route."],["Photograph everything at pickup","Write the height where you can see it","Ask which roads are excluded"]),section("Drive the first day short",["Do not collect a campervan and drive several hours, particularly after a long-haul flight. Book somewhere near the depot for the first night and keep the first driving day short and on main roads.","Width, height, braking distance and cornering all need practice, and the first two days in a large vehicle are noticeably slower than the rest of the trip. Most rental damage happens in car parks in the first 48 hours.","Reversing is the skill worth practising deliberately in an empty car park before you need it at a campsite with neighbours either side."],["Stay near the depot the first night","Most damage happens in the first 48 hours","Practise reversing before you need it"]),section("Build a daily rhythm",["A workable routine is: pack up and leave by mid-morning, drive no more than three or four hours, arrive with daylight to spare, then set up, cook and rest. Trying to fit more in is what makes a first trip exhausting.","Deal with water, waste, fuel and groceries as a single town stop rather than four separate errands. One well-chosen stop clears the whole list in under an hour.","Empty and fill on a schedule rather than when tanks are full or empty. That single habit prevents almost every awkward situation on a first trip."],["Three to four hours driving maximum","One town stop for all the jobs","Empty and fill on schedule"]),section("What surprises first-timers",["Distances are larger than they look on a map and the country between towns is genuinely empty. A drive that looks like a morning is frequently a full day, and there is often nothing at all in between.","Everything takes longer in a campervan: setting up, packing down, finding a site, parking in town. Budget for that rather than planning a car-sized itinerary in a vehicle three times the size.","Flies inland, heat in the north and cold desert nights all catch people out. Pack for a much wider range of conditions than a single-climate trip would suggest."],["Distances are bigger than they look","Everything takes longer in a van","Pack for a wide temperature range"]),section("Choosing the right size vehicle",["Bigger is not better. A larger van is harder to park, restricted from more car parks and roads, uses more fuel and is more stressful to drive on narrow coastal routes.","Match the vehicle to the smallest setup you can genuinely live in for the trip length. Two people are usually comfortable in something far smaller than they initially book.","Book the first two nights and leave the rest flexible, which gives you a settled start while you work out what pace actually suits your party.","Photograph the vehicle inside and out at pickup with the odometer visible, because most return disputes are about damage that existed beforehand."],["Bigger vans restrict where you can go","Match size to the real party","Most people over-book on size"])] }),
  article({ slug:"camping-without-phone-signal", title:"Camping beyond phone signal", description:"Prepare place details, bookings, weather and emergency contacts before coverage disappears.", category:"Trip planning", region:"Australia", readTime:8, places:["Visitor centres","Remote campgrounds","Roadhouses"], imageAlt:"Remote campground beyond phone coverage", intro:"No reception is peaceful only when the essential information already travels with you.", sections:[section("Save what matters",["Keep booking confirmations, gate codes, campground details, emergency numbers and route notes available offline. Screenshot critical weather and closure notices close to departure.","Core place details in AussieCamps remain available offline, while live maps, routing, weather and websites may need reception." ]),section("Use the right communication",["A phone is not an emergency device outside coverage. Remote routes may justify a personal locator beacon or satellite messenger.","Know how to trigger help and who receives a check-in. Carry device batteries where heat cannot damage them."], ["Offline place details","Booking saved","Emergency contact","Power reserve"]),section("Leave a trip plan",["Tell a reliable person the route, vehicle, party, expected check-in and what to do if you miss it. Update them before changing direction.","Do not rely on a social post or shared map that no one is actively watching."]),section("Where coverage actually stops",["Mobile coverage in Australia follows highways and towns and disappears quickly away from them. Large parts of the outback, the Kimberley, the Nullarbor and long stretches of coast between towns have nothing at all.","Coverage maps flatter reality. A carrier may show service where a ridge, a valley or simply distance removes it, and roaming SIMs frequently perform worse than local ones. Telstra generally has the widest rural coverage.","Plan on the assumption of no signal rather than treating it as an exception. That means downloading, printing and telling somebody your plan before you leave the last town."],["Coverage follows highways and towns","Coverage maps are optimistic","Plan for no signal by default"]),section("Satellite communication",["A personal locator beacon is a one-way emergency device that summons rescue and requires no subscription. A satellite messenger adds two-way text and tracking for a monthly fee, and a satellite phone allows calls.","For most travellers a hired PLB is enough and costs very little for a trip. For long remote travel, a satellite messenger is worth the subscription because it lets you communicate without triggering a full rescue.","Register the beacon before you travel and carry it on your person rather than leaving it in the vehicle. A beacon in a car you have walked away from helps nobody."],["PLBs need no subscription","Register the beacon before travel","Carry it on you, not in the vehicle"]),section("Preparing before you lose signal",["Download offline maps for the whole route, not just the next leg, and confirm they work in flight mode before you rely on them. Save bookings, contacts and any access instructions as screenshots.","Fill fuel and water, check tyres and let somebody know your route and expected arrival, with an agreed time at which they should raise an alarm. That agreement is what turns a delay into a search at the right moment.","Carry paper maps for genuinely remote routes. They need no battery, work everywhere and give you the overview that a phone screen never does."],["Test offline maps in flight mode","Agree an alarm time with someone","Carry paper maps for remote routes"]),section("Power and what to do if things go wrong",["A phone searching for signal drains fast, so switch to flight mode when there is nothing to find. Carry a power bank and a working vehicle charger, and remember that heat and cold both reduce battery capacity.","If you break down, stay with the vehicle. It is shelter, it is visible from the air and the road, and walking has killed people in this country repeatedly. Conserve water, stay in shade and wait.","Set out a visible signal if you can: raise the bonnet, use something bright, and be ready to attract attention from an aircraft. Rescuers look for vehicles rather than people."],["Flight mode stops the battery drain","Stay with the vehicle, always","Rescuers look for vehicles"]),section("Entertainment and staying comfortable",["Download maps, music, podcasts and reading before losing signal. Long remote legs and early sunsets create more downtime than most travellers expect, and having something offline makes the evenings considerably better.","Tell family and friends in advance that you will be uncontactable for a defined period. That prevents unnecessary worry and, more importantly, makes a genuine overdue alarm meaningful.","Agree a check-in schedule with someone at home, even a single message every few days, so an unexplained silence means something rather than nothing.","Test offline maps in flight mode before leaving the last town, because discovering they did not download properly is a problem you cannot fix out there."],["Download entertainment in advance","Warn people you will be offline","Makes an overdue alarm meaningful"])] }),
  article({ slug:"road-trip-fuel-planning-australia", title:"Fuel planning for long Australian road trips", description:"Know the vehicle's real range, opening hours and backup fuel before a remote highway.", category:"Trip planning", region:"Australia", readTime:8, places:["Nullarbor Roadhouse","Erldunda","Mount Barnett Roadhouse"], imageAlt:"Remote Australian roadhouse fuel stop", intro:"Remote fuel planning uses conservative range and confirmed opening information. The next pump can be closed, out of fuel or farther away than the map suggests.", sections:[section("Calculate usable range",["Measure consumption with the vehicle loaded and account for wind, speed, sand, hills and air conditioning. Keep a reserve rather than planning to arrive nearly empty.","Use the correct fuel type and understand any approved auxiliary tank or jerry-can system." ]),section("Confirm remote stops",["Check roadhouse hours and recent local advice. Fuel whenever the next reliable stop would use too much of the reserve.","Do not assume card terminals or phone payment will work. Carry an accepted backup payment method."], ["Real consumption known","Stops confirmed","Reserve protected"]),section("Carry fuel safely",["Only carry fuel in approved containers, secured upright and outside occupied spaces as required. Never fill a hot container or store it near ignition sources.","If the route requires more fuel than can be carried safely, change the route."]),section("Range is the constraint, not price",["On outback routes the gap between fuel stops can exceed three hundred kilometres, and roadhouses can be closed, out of stock or card-only with an unreliable connection. Plan range around the worst case rather than the map.","Fill at every opportunity rather than at every need. The habit of topping up whenever you pass a station with more than half a tank showing is what prevents the situation that strands people.","Where the gaps genuinely exceed your range, carry additional fuel in approved jerry cans, secured and vented correctly. Never carry fuel in unsuitable containers or inside the living space."],["Top up above half a tank","Roadhouses can be closed or dry","Approved jerry cans only"]),section("Working out real consumption",["Record litres and kilometres for the first two fills and calculate what the vehicle actually uses loaded. Roof boxes, headwind, sustained climbing, towing and running the engine for air conditioning all push it well above the brochure figure.","Once you have a real number, any leg converts into litres and dollars in your head. That turns fuel from a background anxiety into an ordinary planning input.","Tyre pressures matter and should be set for the loaded vehicle. Lowering pressure for corrugated gravel and reinflating afterwards improves both comfort and fuel use, and reduces tyre damage."],["Measure across the first two fills","Set pressures for the loaded vehicle","Reinflate after gravel sections"]),section("Price differences and loyalty schemes",["Fuel is cheapest in the capitals and outer suburbs and most expensive at remote roadhouses, where the premium can be substantial. That premium is not a reason to stretch a tank, because running dry out there is a far larger problem.","Supermarket-linked discount schemes and fuel apps that show current prices both save real money in urban and regional areas. They are largely irrelevant once you are remote, where there is no choice.","Diesel is generally more available than premium unleaded in remote areas, which is one practical argument for a diesel vehicle on outback routes."],["Remote premiums are substantial","Fuel apps help in town, not outback","Diesel is more available remotely"]),section("Reducing the total without cutting the trip",["The largest saving available is fewer unnecessary kilometres. Grouping nearby stops, avoiding backtracks and accepting that you cannot cross the continent properly in ten days saves more than any driving technique.","Steady speeds help modestly, and every ten kilometres per hour above about ninety costs noticeably more fuel in a high-sided vehicle. Slowing down on long straights saves fuel and reduces fatigue at the same time.","Remove roof boxes and racks when not in use. On a long trip the aerodynamic penalty of an empty roof rack is a real and entirely avoidable cost."],["Fewer kilometres beats better technique","Speed costs more in a tall vehicle","Remove unused roof racks"]),section("Payment at remote stations",["Some remote roadhouses are card-only with satellite connections that fail, and others are cash-only. Carry both, because arriving with only one has stranded people at a station with fuel in the tanks.","Fuel cards and loyalty schemes are largely irrelevant remotely. What matters is having a payment method that works when the connection does not.","Keep a written note of fuel stops and prices for the first week, because it turns fuel from a recurring worry into a predictable line you can plan around.","Remote roadhouses can be closed, out of stock or unable to process a card, so plan range on the assumption that the next station may not serve you."],["Carry both cash and card","Satellite payment links fail","Loyalty schemes do not help remotely"])] }),
  article({ slug:"camping-weather-safety-australia", title:"Weather safety for Australian camping", description:"Plan around heat, storms, floodwater, cold, wind and fire weather.", category:"Rules & safety", region:"Australia", readTime:9, places:["Bureau of Meteorology","Park alerts","Emergency services"], imageAlt:"Storm approaching an Australian campground", intro:"A campground forecast needs more than a weather icon. Warnings, fire danger, river levels and the road home can matter more than the chance of rain.", sections:[section("Heat and fire weather",["Move walks to early morning, carry more water and create shade before the hottest hours. Never leave a person or animal in a parked vehicle.","Check fire danger ratings and local bans. Hot, dry wind can make a campground unsafe before flames are visible." ]),section("Storms, flood and wind",["Do not camp beneath dead limbs or in dry creek beds. Move away from exposed trees and unsecured awnings before severe wind arrives.","Never drive through floodwater. Water depth, road damage and current are impossible to judge safely from the driver's seat."], ["BOM warning checked","Park alert checked","Safe exit route"]),section("Cold and alpine change",["Hypothermia can occur in wet, windy conditions above freezing. Keep dry layers and insulation protected in waterproof storage.","Turn around when cloud, snow or wind removes the safety margin. The campground will still be there another day."]),section("Heat is the biggest killer",["Extreme heat kills more people in Australia than any other natural hazard. Inland summer temperatures regularly exceed forty degrees and the combination of heat, dehydration and vehicle trouble is what turns a trip into an emergency.","Plan activity around the day: walk at first light, rest through the middle, and treat any walk after mid-morning in summer as a decision rather than a default. Carry far more water than the distance suggests.","Know the signs of heat exhaustion and heat stroke. Confusion, stopping sweating and a lack of coordination are late signs requiring immediate cooling and medical help, not a rest and a drink."],["Heat kills more than any other hazard","Walk at first light, rest at midday","Confusion is a late, serious sign"]),section("Bushfire and the danger ratings",["Fire danger ratings are published daily by district and range from Moderate to Catastrophic. On Catastrophic days the official advice is to leave early, and campgrounds in forest are among the worst places to be.","Leaving early means before there is a fire, not once one is visible. Roads close quickly, fires move faster than people expect, and sheltering in a vehicle in bush is a last resort rather than a plan.","Download a state fire agency app and check it daily in summer. Reception is patchy in many camping areas, so check while you have signal rather than intending to look it up later."],["Leave early means before any fire starts","Forest campgrounds are poor shelter","Check fire apps while you have signal"]),section("Flooding and the wet season",["Flash flooding is the hazard that catches campers, particularly in dry creek beds and on floodplains that look like ideal sites. Rain falling far upstream and out of sight is what fills them.","Never camp in a dry creek bed or on a low river flat, and never drive through floodwater. Depth and whether the road is still under the water are both unknowable from the vehicle, and vehicles are swept away every wet season.","In the tropical north, the wet season from November to April brings road closures that can last days. Check road status daily and accept that a closure may hold you in place."],["Never camp in a dry creek bed","Never drive through floodwater","Wet season closures last days"]),section("Storms, wind and cold",["Severe thunderstorms bring damaging wind, hail and lightning, and a tent under trees is a poor place to be in one. Move to a solid building or a vehicle if a severe warning is issued for your area.","Wind damages more camping trips than rain. Awnings left out, tents pitched broadside and roof vents open account for most of it, and wind commonly rises through the evening rather than dropping.","Cold is underestimated in Australia. Inland and alpine nights drop below freezing across much of the country in winter, and hypothermia occurs in the desert as readily as in the mountains."],["Move to solid shelter in severe storms","Bring awnings in before bed","Desert nights drop below freezing"]),section("Getting warnings without signal",["An AM or FM radio receives ABC emergency broadcasts across most of the country and continues working when mobile networks are congested or down. It is the most reliable warning channel in an emergency.","Check forecasts and warnings while you have signal and note what is expected. In fire and cyclone season, that daily habit is what gives you time to act rather than react.","Know how to call triple zero and, where there is no coverage, that 112 will attempt any available network from a mobile phone.","Emergency mobile alerts reach most phones with coverage, but in remote areas an AM radio is the only warning channel that reliably works."],["ABC radio works when networks fail","Check warnings while you have signal","Daily habit buys reaction time"])], sources:[{label:"Bureau of Meteorology",url:"https://www.bom.gov.au/"}] }),
  article({ slug:"responsible-camping-australia", title:"Responsible camping in Australia", description:"Respect Country, protect wildlife, manage waste and leave each camp ready for the next arrival.", category:"Camping guides", region:"Australia", readTime:8, places:["National parks","Council campgrounds","Private land"], imageAlt:"Clean low-impact Australian campsite", intro:"Responsible camping is practical: use legal sites, keep impact within the marked space and follow the people who care for the land.", sections:[section("Respect Country and access",["Learn whose Country you are visiting and follow cultural closures, requests and photography guidance. A track or place can be significant even when no barrier is present.","Do not enter private property without permission or bypass a closed gate." ]),section("Waste and water",["Pack out rubbish, use dump points for wastewater and keep soap away from creeks. Leave toilets clean and never place rubbish in a fire ring.","Use existing campsites instead of clearing vegetation for a better view."], ["Legal site","Waste contained","Noise low","Wildlife unfed"]),section("Share the campground",["Keep music, generators, lights and conversation considerate. Follow quiet hours and give other campers physical space.","Report damage or unsafe conditions to the land manager without turning a sensitive location into social-media bait."]),section("Leave No Trace in Australian conditions",["The principles translate directly but the specifics differ. Camp on durable surfaces means existing cleared pads rather than fragile spinifex or dune vegetation, which takes decades to recover from a single vehicle.","Pack out everything including food scraps. Organic waste attracts animals, alters their behaviour and in arid country takes far longer to break down than people assume. Assume there are no bins unless you can see one.","Toilet waste belongs in a dump point or, where genuinely remote and permitted, buried well away from water and camps. Many arid parks now require carrying it out entirely."],["Use existing cleared pads","Pack out food scraps","Some parks require carrying waste out"]),section("Fire, firewood and habitat",["Fallen timber is habitat rather than fuel. Collecting firewood is prohibited in most national parks because hollow logs shelter reptiles, mammals and invertebrates and take decades to form.","Where fires are permitted, bring your own wood from outside the area, use existing fireplaces and keep the fire small. Never burn rubbish, plastic or treated timber.","On total fire ban days, no open flame is permitted at all. Carry a gas cooker so the trip does not depend on being able to light a fire."],["Fallen timber is habitat","Bring wood, do not collect it","Gas cooker for ban days"]),section("Wildlife and feeding",["Do not feed any native animal. Human food causes disease, dependence and aggression, and habituated animals end up being killed on roads or destroyed as problem animals. This applies to dingoes, kangaroos, possums and birds equally.","Store food and rubbish securely overnight. Dingoes on K'gari in particular have caused serious injuries and deaths, and every incident traces back to food access and habituation.","Keep well back when photographing, never position yourself between an animal and its escape route, and give nesting and resting animals a wide berth entirely."],["Never feed native animals","Store food securely overnight","Never block an escape route"]),section("Country, culture and access",["Much of Australia is Aboriginal land or holds sites of cultural significance, and access conditions, permits and photography restrictions exist for good reasons. Observing them is a condition of being there.","Rock art, burial sites and ceremonial areas should not be touched, climbed or entered. Damage to these places is irreversible and, in many cases, a criminal offence.","Where guided experiences with Traditional Owners are available, they transform the visit. Understanding what a landscape means to the people who have lived in it for tens of thousands of years is the thing most visitors say they remember."],["Permits and restrictions are conditions of access","Never touch or climb rock art","Guided cultural walks transform a visit"]),section("Reporting problems and giving back",["Report damaged facilities, illegal dumping and problem wildlife encounters to the land manager. Sites close because problems went unreported until the cost of fixing them outweighed keeping them open.","Spend money in the towns you camp near. Free camping survives politically because councils can point to visitor spending, and that argument is made with receipts rather than good intentions.","Leaving a site better than you found it, including picking up somebody else's rubbish, costs a few minutes and is what keeps these places open.","Never feed native animals, because habituated dingoes, kangaroos and birds end up injured, destroyed or dangerous, and every incident traces back to food access."],["Report problems to the land manager","Spend locally where you camp","Receipts are the political argument"])] }),
  article({ slug:"choosing-campsite-australia", title:"How to choose a campsite in Australia", description:"Compare access, exposure, facilities, price and booking confidence before driving in.", category:"Camping guides", region:"Australia", readTime:8, places:["Campgrounds","Caravan parks","Farm stays"], imageAlt:"Australian campsite beside a vehicle", intro:"A beautiful campsite is useless when the road is wrong for the vehicle or the last water tap is dry. Choose by constraints first, scenery second.", sections:[section("Check access",["Confirm sealed or unsealed road, clearance, four-wheel-drive requirements, creek crossings, site length and turning room. Rental and insurance restrictions can be stricter than the road itself.","Read recent official alerts and call the manager when a large rig or late arrival is involved." ]),section("Match the facilities",["Decide whether the night needs potable water, toilets, showers, power, laundry, a dump point or mobile coverage. Do not treat an unknown facility as available.","For simple camps, arrive self-contained and carry waste out."], ["Vehicle fits","Water confirmed","Arrival before dark","Backup chosen"]),section("Read the weather around the site",["Avoid exposed coast in strong wind, creek flats before heavy rain and dead trees in storms. Shade matters in heat, but overhead branches can be dangerous.","Choose the safe site over the photogenic one."]),section("Read the ground before you commit",["Walk the pitch before driving onto it, particularly in a heavy vehicle. Check for softness, hidden stumps, ant nests and whether you can get out again if it rains overnight.","Look up. Eucalypts drop limbs without warning, a habit serious enough that they are widely known as widow makers, and camping directly under large gums is a genuine risk rather than a theoretical one.","Check the drainage. A slight hollow that is comfortable in dry weather becomes a puddle in a storm, and a dry creek bed is the most dangerous ground available in flash flood country."],["Never camp under large eucalypts","Walk the pitch before driving on","Dry creek beds flood without warning"]),section("Sun, wind and where the shade goes",["Work out where the morning sun will hit. In the north and inland, a tent in full sun becomes unusable by seven in the morning, and shade in the afternoon is worth more than a view.","Wind rises in the evening in most coastal and inland areas. Pitch with the smallest profile into the prevailing wind, use every guyline, and bring awnings in before you go to bed rather than when they start moving.","In the tropics, a breeze is worth seeking out because it suppresses insects. In the desert, shelter from wind matters more because the nights are cold and the wind carries dust."],["Plan for where morning sun lands","Bring awnings in before bed","Breeze suppresses tropical insects"]),section("Water, and how close is too close",["Being near water is pleasant and comes with constraints. In the tropical north, never camp within about fifty metres of any waterway because of crocodiles, and in flood country stay well above the obvious flood level.","Elsewhere, camping close to water concentrates impact on the most fragile ground and blocks wildlife access to a drinking source. Many parks specify a minimum distance for exactly this reason.","Mosquitoes and sandflies are worst near still water at dawn and dusk. A pitch fifty metres back with a breeze is frequently far more comfortable than one on the bank."],["Fifty metres from water in croc country","Camping close blocks wildlife access","Set back for fewer insects"]),section("Neighbours and arriving late",["Arrive with daylight to spare. Choosing a pitch, levelling a vehicle and assessing hazards are all much harder in the dark, and a site that would obviously be wrong at four is easy to accept at nine.","At a busy ground, set up within your allocated space and leave room for whoever comes after you. Generators, bright lights and late noise are the three things that make you unpopular fastest.","Keep a legal fallback identified before you arrive. A full campground at dusk is a normal event rather than bad luck, and having somewhere to go removes the pressure to make a poor decision."],["Arrive with daylight to spare","Generators and lights annoy fastest","Identify a fallback before arriving"]),section("Insects and where they concentrate",["Mosquitoes and midges concentrate near still water at dawn and dusk, and bush flies inland are worst in the middle of a warm day. A breezy site is dramatically more comfortable than a sheltered one in both cases.","Ants are the underrated problem. Check the ground for trails and nests before pitching, because a tent placed on an ant highway is a night nobody enjoys.","Walk the site once more before you leave in the morning to check nothing has been left behind, which is when most gear is lost.","Look up before pitching, because eucalypts drop limbs without warning and camping directly beneath large gums is a genuine rather than theoretical risk."],["Breeze suppresses most insects","Check for ant trails before pitching","Still water means mosquitoes"])] }),

  article({ slug:"how-to-plan-trip-aussiecamps", title:"How to plan a road trip with AussieCamps", description:"Put overnight stops, dates, notes, distance and packing tasks in one trip.", category:"App guides", region:"Australia", readTime:6, places:["Trip Planner","Collections","Nearby suggestions"], imageAlt:"AussieCamps trip planner screen", intro:"Start with the nights that are hardest to replace, then build the flexible parts of the route around them.", sections:[section("Create the trip",["Open Planner, add a name, dates and the first confirmed stop. Add other places in driving order and drag them when the route changes.","Attach arrival details, booking references and stop notes where they will be useful on the road." ]),section("Check the distance",["Use the route and distance as a planning signal, then confirm current roads and closures. Split any day that leaves no time for fuel, food or an unexpected stop.","Nearby suggestions can help find a backup around a full campground."], ["Dates added","Stops ordered","Backup saved"]),section("Pack beside the plan",["Add the camping essentials preset or make a trip-specific checklist. Mark tasks as gear enters the vehicle, not when it is sitting near the door.","Calendar sync can place itinerary details beside the rest of the travel schedule."]),section("Anchor the trip on the dates that cannot move",["Start with the fixed points: a ferry to Tasmania or Kangaroo Island, a booked national park site, a reef trip, a flight out. Create the trip, add those first, and treat everything between them as adjustable.","Building chronologically from day one is how people discover on day nine that the ferry does not line up and half the bookings are non-refundable. Anchoring the hard dates first makes every later change cheap.","On Australian distances this matters more than elsewhere, because a mistake in the middle of a route can mean a thousand kilometres of backtracking rather than an afternoon."],["Ferries and park bookings go in first","Chronological planning breaks late","Backtracking here costs days"]),section("Order the stops and read the distance",["Arrange saved places into the sequence you will actually drive, then look at the route distance across the ordered stops. This is where an optimistic Australian itinerary usually falls apart.","Three to four hours of driving is a comfortable day with stops. Long outback legs occasionally need more, but consecutive long days produce fatigue, which is a documented cause of crashes on these roads.","Split any leg that leaves no room for fuel, food, a walk or finding a site. Arrival in daylight is worth planning for rather than hoping for."],["Three to four hours is a comfortable day","Consecutive long days cause fatigue","Plan to arrive in daylight"]),section("Attach the details to the individual stop",["Booking references, park permit numbers, gate codes, arrival windows and access notes belong on the specific stop rather than in one long note. On the road you are looking for one fact at a time, usually while tired.","Add the note when you book, while the information is in front of you. Reconstructing it later from an email thread in an area with no reception is exactly the situation to avoid.","Keep the notes short. A single line about which gate to use is more useful at dusk than a paragraph describing the campground."],["One fact per note","Write it at booking time","Short beats comprehensive on the road"]),section("Use the to-do list for the jobs that strand you",["Fuel before a remote leg, water before a dry stretch, a dump point before a run of free camps, groceries before the last real supermarket, and produce disposal before a quarantine border. These are the tasks whose absence ends a day badly.","Keep the list beside the itinerary rather than in a separate app, and mark items complete only when they are actually done. A half-filled water tank ticked off optimistically is worse than an unticked one.","Before a remote leg, work through the list deliberately as a single town stop. One well-chosen stop clears fuel, water, waste, food and tyres in under an hour."],["Quarantine borders belong on the list","Tick only when actually done","Clear the whole list in one town stop"]),section("Sharing the plan with the people in the vehicle",["Trip dates can be pushed to Calendar so the plan sits alongside flights and bookings, which is the simplest way to keep somebody who is not using the app in the loop.","Keep the calendar copy as a summary and the trip itself as the source of truth. The trip holds the notes, ordering and alternatives; the calendar just needs enough for a passenger to follow along.","Review the trip the evening before each driving day, because that is when a change is cheap and a problem is still solvable.","Open the critical stops before leaving reception, because core place details stay readable offline while routing, weather and booking pages do not."],["Calendar is a summary, not the plan","Useful for people not using the app","Trip stays the source of truth"])] }),
  article({ slug:"how-to-use-aussiecamps-filters", title:"How to find your kind of camp with filters", description:"Narrow places by category, fee, rating, booking, state and the facilities that matter.", category:"App guides", region:"Australia", readTime:5, places:["Boodjamulla National Park","Pebbly Beach Campground","Cape Le Grand"], imageAlt:"AussieCamps campground filters screen", intro:"Use only the filters that would genuinely rule a place out. Too many filters can hide a good backup a few kilometres away.", sections:[section("Start with category and area",["Choose campgrounds, caravan parks, roofed accommodation or another place type, then move the map to the part of the route you are planning.","Restrict results to the visible map area when distance matters more than a place name." ]),section("Add essential facilities",["Select fee, booking, rating and features such as toilets, drinking water, power, dogs or big-rig access.","Treat missing information as unknown, not as proof that a facility is absent."], ["Access","Water","Toilets","Power if needed"]),section("Open the final few",["Compare place details, reported fees, nearby useful stops and weather. Follow booking or contact information to confirm the stay.","Save the preferred place and one alternative before leaving coverage."]),section("Start with the type of night, then the map",["Decide what kind of stop you need before narrowing anything else. A national park campground, a caravan park, a free rest area, a station stay and a showground are different products with different rules, prices and booking systems.","Then position the map along the route you are actually driving. Searching the visible area keeps results relevant and stops a well-known place three hours off the route dominating a shortlist it does not belong on.","On Australian distances this matters enormously. A detour that looks small on a national map can be a full day of driving."],["Choose the type of night first","Search along the route","Small map detours are big drives"]),section("Filter on deal-breakers, not preferences",["Apply a filter when its absence genuinely ends the option: rig length, powered site, drinking water, dump point, dog access. If you have full tanks, filtering for water removes places that would have been fine and quieter.","Work down from the hardest constraint. Vehicle size and access eliminate the most options and are the least negotiable, so applying them first leaves a shorter and more honest list.","For a big rig, length and access notes matter more than facilities. For a tent, shade and ground surface matter more than power."],["Filter only genuine deal-breakers","Hardest constraint first","Rig length is the key filter for vans"]),section("Blank fields mean unknown",["Missing data means nobody recorded it, not that the facility is absent. Filtering strictly on facilities silently discards places that may well suit you, and this is the most common reason a region looks empty.","When a filtered search returns almost nothing, loosen the least important condition rather than concluding the area has no camping. Results usually change substantially with one filter removed.","Open several results and read the details rather than trusting the filter alone. A filter narrows a list; it cannot confirm today's closure, fire ban or booking availability."],["Blank means unknown, not absent","Loosen one filter before giving up","Read details, not just filter results"]),section("Search for services as their own task",["Dump points, drinking water, fuel and laundries are trip-critical and worth searching for deliberately rather than hoping they appear near tonight's camp. Planning a dump stop on the way somewhere is far easier than a special trip.","Before a remote leg, identify the specific fuel and water stops you will use rather than assuming something will appear. In outback Australia that assumption is how people get into trouble.","Always save a legal alternative alongside your preferred site. A filter set tight enough to return one result has removed your fallback, and full campgrounds in peak season are normal."],["Plan dump and water stops in advance","Name the specific remote fuel stop","Always save a fallback site"]),section("Resetting between regions",["Filters left on from a previous region are a common reason a search looks unexpectedly empty. The requirements for a tropical coastal night, an outback roadhouse stop and an alpine campground share almost nothing.","Clear the set whenever the trip changes character, particularly when crossing from the coast inland, from temperate to tropical, or from a touring stretch into a few days based in one town.","When a search returns nothing useful, zoom the map out before loosening filters, because the answer is frequently a good option slightly further along the route.","Always save a legal alternative alongside your preferred site, because a filter tight enough to return one result has removed your fallback."],["Yesterday's filters cause today's empty search","Clear when the trip changes character","Coastal and outback needs differ entirely"])] }),
  article({ slug:"save-collections-aussiecamps", title:"How to organise saved places in AussieCamps", description:"Separate booked stays, maybes, favourites and future trips without losing the map.", category:"App guides", region:"Australia", readTime:5, places:["Starred","Want to Visit","Visited","Custom Collections"], imageAlt:"AussieCamps saved collections screen", intro:"A small saved system makes a large country easier to think about. Use smart lists for status and custom collections for the trip or idea.", sections:[section("Use smart lists",["Mark a place Liked, Visited, Want to Visit or Starred and it appears in the matching smart collection. Pins and All Saved provide broader views.","Use Starred for the few places that should remain visible above ordinary maybes." ]),section("Make custom collections",["Create a named collection for a region, season, vehicle or trip. Add an icon and short note so the purpose is obvious months later.","A collection can hold alternatives without forcing them into an active trip."], ["Booked","Backup","Next season","Big-rig friendly"]),section("Clean up after travel",["Mark visited places and remove options that no longer interest you. Keep useful notes about access or timing for the next visit.","Private iCloud sync can carry saved states and collections across your devices when enabled."]),section("Separate saved places by intent",["The useful division is by what you intend to do with a place: one list for the trip you are taking, one for realistic backups within reach of the route, and one for ideas you may never use.","The backup list earns its place repeatedly. Knowing you have two legal alternatives within an hour changes how you handle a full campground, particularly at dusk on a long weekend.","Mixing all three into one list is what makes a saved collection unusable at exactly the moment you need it."],["Trip, backups, ideas as three lists","Backups within reach of the route","One mixed list becomes unusable"]),section("Name lists so they make sense later",["A list called Queensland tells you nothing in four months. Queensland July, powered sites for the van tells you what you were solving for and whether it is reusable.","Name by region, season, vehicle or trip, and add a short description where you can. The reason you saved a place fades fastest and is usually the part that mattered.","Prune after each trip: mark what you visited, delete what did not suit, and keep the access notes that will still be true next time."],["Name by region, season and vehicle","Record why you saved it","Prune while the trip is fresh"]),section("Save from the details, not the pin",["Open the place before saving it. Access notes, rig suitability, facilities, fees and the source of the information determine whether it works for your setup, and none of that is visible from a map pin.","Add a note about the specific thing that made it worth keeping: only site here with a dump point, gravel access unsuitable for a low car, shaded in the afternoon. That is what makes a shortlist usable.","Saving from the map produces a list of names. Saving from the details produces a list of options you can actually choose between."],["Open the place before saving","Note the specific reason","Pins are names, details are options"]),section("Sync and moving lists into trips",["With iCloud available and enabled, saved states, collections and trip data sync privately across your devices, so you can plan on a larger screen and have the same lists in the vehicle.","It also means a replaced or reset phone does not take the trip with it, which matters more on a long lap than on a weekend.","When stops are confirmed, move them into a trip. Lists hold possibilities; the planner turns them into an ordered route with distance, and keeping the two separate is what makes either useful."],["iCloud sync across devices","A reset phone does not lose the trip","Lists hold options, trips hold plans"]),section("Using smart collections",["Liked, Visited, Want to Visit and Starred update automatically as you mark places, so they track status rather than plans. Visited is genuinely useful on a long lap because it stops you researching somewhere twice.","Pins and All Saved give the wide view when you cannot remember which list something went into. Treat those as the safety net rather than the filing system.","Review the lists at the end of each trip while the detail is fresh, because a note written a month later is never as useful as one written that week.","With iCloud enabled, saved places and trips sync privately across devices, so planning on a larger screen at home carries straight into the vehicle."],["Smart collections track status","Visited prevents duplicate research","All Saved is the safety net"])] }),
  article({ slug:"aussiecamps-place-details", title:"How to read a place in AussieCamps", description:"Check fee reports, facilities, access, weather, nearby services and directions before relying on a stop.", category:"App guides", region:"Australia", readTime:5, places:["Place details","Weather","Nearby useful stops"], imageAlt:"AussieCamps place details screen", intro:"Open the details before turning off the highway. The useful question is not only where the place is, but whether it works tonight.", sections:[section("Read the basics",["Check category, location, fee, rating and description first. Expand grouped features for access, amenities, activities, services and affiliations.","Look at reported fee information and compare nearby places when price matters." ]),section("Check the day",["Use the weather outlook and nearby useful stops to understand the stay around the pin. Fuel, water, a dump point or groceries can determine the better camp.","Live weather and external provider pages need reception."], ["Access","Fee","Facilities","Weather","Nearby services"]),section("Confirm and save",["Open the booking, website or contact details when present. Current provider information and on-site signs take priority.","Save the place to a smart list, custom collection or trip, then add a note that will matter on arrival."]),section("Read the access notes first",["Access is what determines whether a place works for your vehicle, and it is the field most worth reading before anything else. Road surface, gradient, clearance, turning space and rig length limits all sit here.","A site with excellent facilities reached by a road your vehicle cannot use is not an option. In Australia this matters more than elsewhere because so many good sites sit at the end of unsealed roads.","Cross-check against your rental agreement if you are hiring. A road being legal and passable does not mean your insurance follows you onto it."],["Access decides suitability, not facilities","Many good sites are on unsealed roads","Check the rental agreement too"]),section("Fees, booking and what they include",["Check whether the fee is per person, per site or per vehicle, and whether park entry is charged separately from camping. Those two figures are frequently separate and travellers regularly budget for only one.","Note whether the site is bookable or first come. In Australia this varies by state and by park, and turning up at a booking-only site is a wasted drive of potentially hundreds of kilometres.","Where a permit is required, it usually must be arranged in advance and sometimes displayed. Arriving without it is an offence even where sites are available."],["Park entry is often separate","Bookable or first come varies by state","Permits must be arranged ahead"]),section("Facilities, and what missing data means",["A blank facility field means nobody recorded it rather than that it is absent. Treat the listed facilities as a floor rather than a complete description, and carry what you need to be independent.","Water shown at a site is not necessarily potable, particularly in remote areas where tanks are rainwater and bores are mineralised. Carry treatment and enough drinking water to be self-sufficient.","Where facilities matter for a specific reason, such as accessibility or a dump point before a long leg, confirm with the land manager rather than relying on the listing alone."],["Blank means unrecorded, not absent","Listed water may not be potable","Confirm anything critical directly"]),section("The listing never outranks the sign",["Place data reflects what was true when the record was made. Rangers close sites, councils change local laws, fires and floods take out access, and fire bans arrive quickly. On arrival, the sign and the land manager decide.","If what you find contradicts what you saved, follow what is in front of you and move to your saved alternative. That is the entire reason for identifying one before leaving reception.","Where a listing is clearly wrong, send a correction. The directory improves through reports, and the next traveller benefits from thirty seconds of your time."],["Signs outrank any listing","Move to your saved alternative","Send corrections when you find them"]),section("Booking and contact links",["Where a place has booking or contact details, opening them lets you confirm availability, price and current conditions directly with the provider. That confirmation is what turns a listing into a plan.","Do this while you still have reception. A booking link is useless three hours into a leg with no signal, and the providers most worth calling are frequently in the areas with the least coverage.","Where a place has been visited recently, the details are more likely to reflect current conditions, but nothing replaces reading the sign when you arrive.","Where a listing contradicts what you find on arrival, follow the sign and send a correction so the next traveller gets better information."],["Confirm directly with the provider","Do it while you have signal","A listing is not a booking"])] }),
  article({ slug:"aussiecamps-widgets-guide", title:"AussieCamps widgets: trips, collections and nearby places", description:"Keep the next stop, trip progress, favourite places or a nearby map on the Home Screen.", category:"App guides", region:"Australia", readTime:5, places:["Trip widget","Collections widget","Nearby map widget"], imageAlt:"AussieCamps iPhone widgets", intro:"Widgets keep the next useful piece of a trip visible without opening the full app.", sections:[section("Trip widget",["Choose a trip to show the next stop and visited progress. Small, medium and large layouts expose different amounts of the itinerary.","The Lock Screen accessory can keep the next stop close during a driving day." ]),section("Collection widgets",["Show top collections, saved totals or a selected smart collection such as Starred or Want to Visit.","Use a focused collection rather than displaying every saved place."], ["Next trip","Starred","Want to Visit"]),section("Nearby map",["The nearby widget uses the latest available location snapshot to show nearby places on a map. Medium and large sizes provide more context.","Refresh behaviour depends on iOS and location availability, so open the app before relying on a newly changed route."]),section("What a widget is good for",["A widget puts one piece of information on the home screen without opening anything, which matters when you are in and out of a vehicle all day. The useful ones answer a single recurring question at a glance.","For a road trip that question is usually where am I staying tonight, what is nearby, or what is still on the to-do list. A widget answers it in the time it takes to unlock the phone.","Widgets read stored data, so the place information they show remains available when reception does not. Anything live, such as weather, still needs a connection to update."],["One question, answered at a glance","Stored place data works offline","Live data still needs signal"]),section("Trip and nearby widgets",["A trip widget surfaces the next stop and keeps the plan visible without opening the app, which is the single most useful thing on a driving day. It is also what a passenger can check without taking your phone.","A nearby widget answers the other common question, which is what is around here right now. This matters most when a plan changes and you need an option quickly rather than a full search.","Between them, these two cover most of what you actually need while moving, with the full app reserved for planning rather than navigation."],["Trip widget for the next stop","Nearby widget for changed plans","Full app for planning, widgets for moving"]),section("Collections on the home screen",["A collection widget puts a specific saved list one tap away, which suits a shortlist of backups or the places you are choosing between for tonight.","Pair it with the list structure that works: trip, backups, ideas. Putting the backup list on the home screen is what makes it useful at the moment a campground turns out to be full.","Widgets are most useful when the underlying lists are well maintained. A widget pointing at a list of two hundred unsorted pins does not help."],["Put the backup list on the home screen","Widgets reflect list quality","Keep the underlying lists pruned"]),section("Setting them up and battery",["Add widgets by long pressing the home screen and choosing the app, then pick the size that suits what you want to see. Larger sizes show more entries and take more space.","Widgets refresh periodically rather than continuously, so a very recently added stop may take a moment to appear. Opening the app updates it immediately.","Battery matters on a road trip because the phone is already doing navigation, photographs and searching for signal. Widgets are light, but flight mode in no-coverage areas saves considerably more."],["Long press to add, choose the size","Widgets refresh periodically","Flight mode saves the most battery"]),section("Choosing which widgets to use",["Two widgets usually cover a road trip: one showing the next stop on the current trip, and one showing what is nearby. Adding more tends to dilute rather than help.","Put them on the first home screen where you will actually see them. A widget two screens across answers a question you have already opened the app to solve.","Widgets are worth revisiting when the trip changes character, since the useful one on a driving day is not the useful one during a week in a single base.","Widgets read stored data, so place information stays visible offline while anything live, such as weather, still needs a connection to update."],["Two widgets usually suffice","Put them on the first screen","More widgets dilute the value"])] }),
  article({ slug:"best-camping-app-australia", title:"What to look for in a camping app for Australia", description:"Choose an app that covers the route, explains the stop and turns saved places into a workable trip.", category:"App guides", region:"Australia", readTime:7, places:["Campgrounds","Caravan parks","Rest areas","Dump points"], imageAlt:"Camping app open beside an Australian road", intro:"A useful camping app should reduce uncertainty before the turnoff and stay understandable when the route changes.", sections:[section("Coverage beyond campgrounds",["Long trips need caravan parks, roofed stays, rest areas, dump points, potable water, fuel and other useful stops. A campground-only map leaves gaps between nights.","Look for clear categories and a way to focus on the current map area." ]),section("Details that affect the decision",["Access, fees, toilets, water, power, dogs, vehicle suitability and booking information matter more than a large pin count.","Offline place information is valuable beyond coverage, while live maps, weather and routing still depend on data."], ["Offline place details","Access filters","Trip planning","Source links"]),section("From saved pin to route",["A strong app should organise favourites, separate maybes from booked stays and order trip stops with notes.","Choose the product whose workflow matches how you travel, not the one with the longest marketing list."]),section("Offline data is the first test",["Australia removes mobile coverage faster than almost anywhere, and it does so exactly where you are choosing a campsite. An app that needs a connection to show place details is not useful across most of the continent.","Offline means different things: some tools cache map tiles only, leaving you with a map and no information. Others bundle the place directory so categories, facilities, fees and access notes stay readable with no signal.","Test it before you leave the last town. Put the phone in flight mode and open a place you have not looked at. Whatever appears is what you will have out there."],["Test offline in flight mode first","Cached tiles are not cached details","Coverage stops where you need it most"]),section("Rules clarity and how the app is funded",["The second test is whether the app distinguishes what is legally different: a national park campground with a permit, a council free camp with a stay limit, a rest area for fatigue only, and private land. Blurring those is what produces fines.","The third is how the app makes money. A tool funded by bookings has a structural reason to surface bookable commercial sites ahead of free ones, which is not dishonest but does shape what you see first.","A subscription or one-off licence removes that incentive. A free app with no visible revenue is worth a moment's thought about where the value goes."],["Legal categories must be distinct","Booking-funded apps favour paid sites","Know how the app is funded"]),section("Trip planning that survives a change",["The fourth test is whether the app helps when the plan breaks, which on an Australian trip it will. Ordered stops, saved alternatives, notes attached to the right place and a visible route distance are what matter.","Bookmarks alone are not trip planning. The difference shows at the point where a campground is full, a road is closed or the weather turns, and you need to rearrange without rebuilding from scratch.","Filters matter too, particularly rig length and access, because Australia has more large vehicles and more roads unsuitable for them than most countries."],["Bookmarks are not trip planning","Rig length filtering matters here","Judge it by how it handles a change"]),section("Nothing replaces the sign",["Every app is a planning aid. On-site signage, current fire bans, ranger directions and council local laws override anything cached on a phone, and they change faster than any dataset refreshes.","Before settling in for the night, read the sign at the entrance. If it disagrees with the app, the sign wins. That habit costs nothing and is what keeps free camping areas open.","Most travellers end up carrying more than one app, and that is a reasonable outcome rather than a failure to choose. Use each for what it is actually good at."],["Signs override every app","Fire bans change daily","Carrying two apps is normal"]),section("What no app can do",["No app confirms that a site is open today, that a fire ban has just been declared, or that a road closed after last night's rain. Those change faster than any dataset refreshes.","Use the app to plan and shortlist, then verify anything critical with the land manager, the state road authority or the sign at the entrance. That division of labour is what makes the tool genuinely useful.","Whichever you choose, test it properly in the first week while you still have easy access to alternatives rather than discovering its limits somewhere remote.","Test any app in flight mode before you rely on it, because whatever appears with no signal is exactly what you will have when it matters."],["Apps cannot confirm today's status","Verify critical facts directly","Plan with the app, confirm with the source"])] }),
  ...expandedArticles,
// Each guide gets its own two-question FAQ attached by slug (see lib/article-faqs.ts).
].map((article) => (articleFaqs[article.slug] ? { ...article, faq: articleFaqs[article.slug] } : article));

export const categories: ArticleCategory[] = ["Road trips", "Camping guides", "Rules & safety", "Trip planning", "Costs & budget", "App guides"];
export const getArticle = (slug: string) => articles.find((item) => item.slug === slug);
